import type {
  ColumnFiltersState,
  RowSelectionState,
  OnChangeFn,
} from "@tanstack/react-table"

import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"

import { buildAdminTableXlsxExport } from "@ui/components/admin"

import { api } from "@/lib/api"

import { getContactRequestColumns } from "../columns"

import type { ContactRequest } from "../types"

interface ContactRequestTableProps {
  data: ContactRequest[]

  isLoading: boolean

  total: number

  page: number

  pageSize: number

  appliedPage?: number

  appliedPageSize?: number

  onPageChange: (page: number) => void

  onPageSizeChange: (pageSize: number) => void

  columnFilters: ColumnFiltersState

  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>

  globalFilter: string

  onGlobalFilterChange: OnChangeFn<string>

  selectedRowIds: RowSelectionState

  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>

  onView: (contact: ContactRequest) => void

  onDelete: (contact: ContactRequest) => void

  onPurge: (contact: ContactRequest) => void

  onStatusChange: (
    contact: ContactRequest,

    status: ContactRequest["status"]
  ) => void | Promise<void>

  onSetRead: (contact: ContactRequest, isRead: boolean) => void | Promise<void>

  onSetPriority: (
    contact: ContactRequest,

    priority: NonNullable<ContactRequest["priority"]>
  ) => void | Promise<void>

  busy: boolean

  canUpdate?: boolean

  canDelete?: boolean

  onBulkDelete: (ids: string[]) => void

  onBulkPurge: (ids: string[]) => void

  onClearFilters: () => void

  onRowPrefetch?: (row: ContactRequest) => void

  listParams: {
    search?: string
    filters?: Record<string, string>
  }
}

export function ContactRequestTable(props: ContactRequestTableProps) {
  const {
    data,

    isLoading,

    total,

    page,

    pageSize,

    appliedPage,

    appliedPageSize,

    onPageChange,

    onPageSizeChange,

    columnFilters,

    onColumnFiltersChange,

    globalFilter,

    onGlobalFilterChange,

    selectedRowIds,

    onSelectedRowIdsChange,

    onView,

    onDelete,

    onPurge,

    onStatusChange,

    onSetRead,

    onSetPriority,

    busy,

    canUpdate,

    canDelete,

    onBulkDelete,

    onBulkPurge,

    onClearFilters,

    onRowPrefetch,

    listParams,
  } = props

  const columns = getContactRequestColumns({
    view: "list",
    onView,
    onDelete,
    onRestore: () => {},
    onPurge,

    onStatusChange,

    onSetRead,

    onSetPriority,

    busy,

    canUpdate,

    canDelete,
  })

  const exportConfig = buildAdminTableXlsxExport("contact-requests", {
    pageCount: data.length,
    total,
  })

  return (
    <AdminDataTable<ContactRequest>
      tableScope="contact-requests"
      data={data}
      getRowId={(row) => String(row.id)}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Không có yêu cầu liên hệ khớp tìm kiếm hoặc bộ lọc."
      defaultExpandedAll={false}
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo tên, email, tiêu đề…"
      onClearFilters={onClearFilters}
      onRowPointerEnter={
        onRowPrefetch ? (row) => onRowPrefetch(row.original) : undefined
      }
      clearFiltersVariant="destructive"
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        ...(canDelete
          ? [
              {
                id: "bulk-contact-delete" as const,

                label: "Xóa tạm đã chọn",

                variant: "destructive" as const,

                onAction: async (rows: ContactRequest[]) => {
                  const ids = rows.map((c) => String(c.id))

                  if (!ids.length) return

                  await onBulkDelete(ids)
                },
              },
            ]
          : []),

        ...(canDelete
          ? [
              {
                id: "bulk-contact-purge" as const,

                label: "Xóa vĩnh viễn đã chọn",

                variant: "destructive" as const,

                onAction: async (rows: ContactRequest[]) => {
                  const ids = rows.map((c) => String(c.id))

                  if (!ids.length) return

                  await onBulkPurge(ids)
                },
              },
            ]
          : []),
      ]}
      xlsxExport={exportConfig}
      exportFetchPage={async ({ page: exportPage, limit }) => {
        const result = await api.contactRequests.list({
          page: exportPage,
          limit,
          search: listParams.search,
          filters: listParams.filters,
        })
        return { items: result.items, total: result.total }
      }}
      pagination={{
        page,
        pageSize,
        total,
        appliedPage,
        appliedPageSize,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có yêu cầu liên hệ",
        itemLabel: "yêu cầu",
      }}
    />
  )
}

import type {
  ColumnFiltersState,
  RowSelectionState,
  OnChangeFn,
} from "@tanstack/react-table"

import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"

import { buildAdminTableXlsxExport } from "@ui/components/admin"

import { api } from "@/lib/api"

import { downloadAdminTableXlsx } from "@/lib/admin-xlsx-export"

import { getContactRequestColumns } from "../columns"

import { getContactRequestExportFields } from "../contact-export"

import type { ContactRequest } from "../types"

interface ContactRequestTrashTableProps {
  data: ContactRequest[]

  isLoading: boolean

  total: number

  page: number

  pageSize: number

  appliedPage?: number

  appliedPageSize?: number

  onPageChange: (page: number) => void

  onPageSizeChange: (pageSize: number) => void

  columnFilters: ColumnFiltersState

  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>

  globalFilter: string

  onGlobalFilterChange: OnChangeFn<string>

  selectedRowIds: RowSelectionState

  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>

  onRestore: (contact: ContactRequest) => void

  onPurge: (contact: ContactRequest) => void

  busy: boolean

  canRestore?: boolean

  canDelete?: boolean

  onBulkRestore: (ids: string[]) => void

  onBulkPurge: (ids: string[]) => void

  onClearFilters: () => void

  listParams: {
    search?: string
    filters?: Record<string, string>
  }
}

export function ContactRequestTrashTable(props: ContactRequestTrashTableProps) {
  const {
    data,

    isLoading,

    total,

    page,

    pageSize,

    appliedPage,

    appliedPageSize,

    onPageChange,

    onPageSizeChange,

    columnFilters,

    onColumnFiltersChange,

    globalFilter,

    onGlobalFilterChange,

    selectedRowIds,

    onSelectedRowIdsChange,

    onRestore,

    onPurge,

    busy,

    canRestore,

    canDelete,

    onBulkRestore,

    onBulkPurge,

    onClearFilters,

    listParams,
  } = props

  const columns = getContactRequestColumns({
    view: "trash",
    onView: () => {},
    onDelete: () => {},
    onRestore,
    onPurge,
    onStatusChange: async () => {},
    onSetRead: async () => {},
    onSetPriority: async () => {},
    busy,
    canRestore,
    canDelete,
  })

  const exportConfig = buildAdminTableXlsxExport("contact-requests-trash", {
    pageCount: data.length,
    total,
  })

  return (
    <AdminDataTable<ContactRequest>
      tableScope="contact-requests-trash"
      data={data}
      getRowId={(row) => String(row.id)}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Thùng rác trống hoặc không khớp bộ lọc."
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo tên, email, tiêu đề…"
      onClearFilters={onClearFilters}
      clearFiltersVariant="destructive"
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        ...(canRestore
          ? [
              {
                id: "bulk-contact-restore" as const,

                label: "Khôi phục đã chọn",

                variant: "default" as const,

                onAction: async (rows: ContactRequest[]) => {
                  const ids = rows.map((c) => String(c.id))

                  if (!ids.length) return

                  await onBulkRestore(ids)
                },
              },
            ]
          : []),

        ...(canDelete
          ? [
              {
                id: "bulk-contact-purge" as const,

                label: "Xóa vĩnh viễn đã chọn",

                variant: "destructive" as const,

                onAction: async (rows: ContactRequest[]) => {
                  const ids = rows.map((c) => String(c.id))

                  if (!ids.length) return

                  await onBulkPurge(ids)
                },
              },
            ]
          : []),
      ]}
      xlsxExport={{
        ...exportConfig,
        runExport: () =>
          downloadAdminTableXlsx({
            templateId: "contact-requests-trash",

            data,

            fields: getContactRequestExportFields("trash"),

            options: { pageCount: data.length, total },
          }),
      }}
      exportFetchPage={async ({ page: exportPage, limit }) => {
        const result = await api.contactRequests.list({
          page: exportPage,
          limit,
          search: listParams.search,
          trash: true,
          filters: listParams.filters,
        })
        return { items: result.items, total: result.total }
      }}
      pagination={{
        page,
        pageSize,
        total,
        appliedPage,
        appliedPageSize,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có yêu cầu trong thùng rác",
        itemLabel: "yêu cầu",
      }}
    />
  )
}

