import { useCallback, useState } from "react"
import { useForm } from "react-hook-form"
import type { UseMutationResult } from "@tanstack/react-query"
import type { CourseConfirmAction, CourseFormValues } from "../types"
import { courseFormSchema } from "../types"
import { zodResolver } from "@hookform/resolvers/zod"

const EMPTY_VALUES: CourseFormValues = {
  name: "",
  startYear: undefined,
  endYear: undefined,
  departmentId: "",
  status: 1,
}

function parseDepartmentId(value: string | undefined): number | null {
  const trimmed = value?.trim()
  if (!trimmed) return null
  const num = Number(trimmed)
  return Number.isFinite(num) ? num : null
}

export function buildCoursePayload(
  values: CourseFormValues
): Record<string, unknown> {
  return {
    name: values.name.trim(),
    startYear: values.startYear || null,
    endYear: values.endYear || null,
    departmentId: parseDepartmentId(values.departmentId),
    status: values.status,
  }
}

export function useCourseForm() {
  const form = useForm<CourseFormValues>({
    resolver: zodResolver(courseFormSchema),
    defaultValues: EMPTY_VALUES,
  })
  const resetForm = useCallback(() => {
    form.reset(EMPTY_VALUES)
  }, [form])
  return { form, resetForm }
}

export function useHandleConfirmAction(
  deleteMutation: UseMutationResult<unknown, Error, string>,
  restoreMutation: UseMutationResult<unknown, Error, string>,
  purgeMutation: UseMutationResult<unknown, Error, string>,
  setConfirmAction: React.Dispatch<
    React.SetStateAction<CourseConfirmAction | null>
  >
) {
  return useCallback(
    async ({ kind, row }: CourseConfirmAction) => {
      try {
        if (kind === "delete") {
          await deleteMutation.mutateAsync(row.id)
        } else if (kind === "restore") {
          await restoreMutation.mutateAsync(row.id)
        } else if (kind === "purge") {
          await purgeMutation.mutateAsync(row.id)
        }
      } catch {
        /* toast: MutationCache */
      } finally {
        setConfirmAction(null)
      }
    },
    [deleteMutation, restoreMutation, purgeMutation, setConfirmAction]
  )
}

export function useConfirmAction() {
  const [confirmAction, setConfirmAction] =
    useState<CourseConfirmAction | null>(null)
  return { confirmAction, setConfirmAction }
}

src/app/courses/_component/_query/use-co.content:
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@/lib/fetch-all-admin-list"
import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@/lib/admin-detail-query"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client"
import type { CourseDetail, CourseRow } from "../types"

export const courseDetailQueryKey = (id: string) =>
  ["courses", "detail", id] as const

export function prefetchCourseDetail(
  queryClient: QueryClient,
  apiParam: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(queryClient, courseDetailQueryKey(id), () =>
    apiParam.courses.get<CourseDetail>(id)
  )
}

export function useCourseDetailQuery(
  apiParam: StoreSyncSdk,
  id: string
): UseQueryResult<CourseDetail> {
  return useQuery({
    ...adminDetailQueryOptions(
      courseDetailQueryKey(id),
      async () => apiParam.courses.get<CourseDetail>(id),
      id
    ),
  })
}

export function useCoursesListQuery(
  apiParam: StoreSyncSdk,
  enabled: boolean,
  filters?: Record<string, string>
): UseQueryResult<CourseRow[]> {
  return useQuery({
    queryKey: ["courses", "list", filters],
    queryFn: async (): Promise<CourseRow[]> => {
      const limit = ADMIN_LIST_EXPORT_FETCH_LIMIT
      const items: CourseRow[] = []
      let page = 1
      let total = Number.POSITIVE_INFINITY

      while (items.length < total) {
        const result = await apiParam.courses.list<CourseRow>({
          page,
          limit,
          status: "active",
          filters,
        })
        items.push(...result.items)
        total = result.total
        if (result.items.length === 0) break
        page += 1
      }

      return items
    },
    enabled,
  })
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk
  trashPage: number
  trashPageSize: number
  debouncedTrashQ: string
  enabled: boolean
}

export function useCoursesTrashQuery({
  api: apiParam,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  enabled,
  filters,
}: UseTrashQueryProps & { filters?: Record<string, string> }): UseQueryResult<
  PagedResult<CourseRow>
> {
  return useQuery({
    queryKey: [
      "courses",
      "trash",
      trashPage,
      trashPageSize,
      debouncedTrashQ,
      filters,
    ],
    enabled,
    queryFn: async (): Promise<PagedResult<CourseRow>> => {
      return apiParam.courses.list<CourseRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        ...filters,
      })
    },
  })
}

