import type { CourseRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"
import { api } from "@/lib/api"
import {
  createAdminTrashExportFetchPage,
  type AdminTrashExportParams,
} from "@/lib/admin-trash-export"

export interface CoursesTrashTableProps {
  data: CourseRow[]
  columns: ColumnDef<CourseRow>[]
  isLoading: boolean
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  onClearFilters: () => void
  onBulkRestore: (rows: CourseRow[]) => Promise<void>
  onBulkPurge: (rows: CourseRow[]) => Promise<void>
  trashExportParams?: AdminTrashExportParams
}

export function CoursesTrashTable({
  data,
  columns,
  isLoading,
  columnFilters,
  onColumnFiltersChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  page,
  pageSize,
  total,
  onPageChange,
  onPageSizeChange,
  onClearFilters,
  onBulkRestore,
  onBulkPurge,
  trashExportParams,
}: CoursesTrashTableProps) {
  return (
    <AdminDataTable<CourseRow>
      tableScope="courses-trash"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Thùng rác trống."
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm trong thùng rác..."
      onClearFilters={onClearFilters}
      clearFiltersVariant="destructive"
      xlsxExport={buildAdminTableXlsxExport("courses-trash", {
        pageCount: data.length,
        total,
      })}
      exportFetchPage={
        trashExportParams
          ? createAdminTrashExportFetchPage<CourseRow>(
              (params) => api.courses.list<CourseRow>(params),
              trashExportParams
            )
          : undefined
      }
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        {
          id: "bulk-course-restore",
          label: "Khôi phục đã chọn",
          variant: "default",
          confirm: {
            title: "Khôi phục các khóa học đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} khóa học. Các khóa học sẽ được đưa trở lại danh sách đang hoạt động.`,
            confirmLabel: "Khôi phục",
          },
          onAction: onBulkRestore,
        },
        {
          id: "bulk-course-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          confirm: {
            title: "Xóa vĩnh viễn các khóa học đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} khóa học. Hành động này không thể hoàn tác.`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      pagination={{
        page,
        pageSize,
        total,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có khóa học trong thùng rác",
        itemLabel: "khóa học",
      }}
    />
  )
}

src/app/data/import-progress-panel.tsx.content:
"use client"

import { useCallback, useState } from "react"
import { toast } from "@ui/components/sonner"
import { Button } from "@ui/components/button"
import { Badge } from "@ui/components/badge"
import { FieldSectionValue } from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import {
  Check,
  CheckCircle2,
  Circle,
  Copy,
  Loader2,
  MinusCircle,
  XCircle,
} from "lucide-react"
import {
  buildImportProgressReport,
  buildModelImportCopyText,
  formatImportErrorMessage,
} from "./_component/import-error-message"
import {
  formatImportDuration,
  formatModelTimingSummary,
} from "./_component/import-timing"
import type {
  ImportJobTimingEntry,
  ImportModelTimingStats,
} from "./_component/import-timing"

export type ImportModelStatus =
  | "pending"
  | "importing"
  | "done"
  | "error"
  | "skipped"

export type ImportModelProgress = {
  name: string
  records: number
  status: ImportModelStatus
  /** Ví dụ: "lô 2/5" khi import file lớn theo từng phần. */
  detail?: string
  /** Tóm tắt ngắn (1 dòng). */
  error?: string
  /** Chi tiết từng dòng lỗi — hiển thị danh sách. */
  rowErrorDetails?: string[]
  /** Tooltip: lỗi gốc từ API (SQL đầy đủ). */
  errorTitle?: string
  /** Thời gian import bảng (wall + HTTP + server). */
  timing?: ImportModelTimingStats
}

export type ImportProgressState = {
  active: boolean
  models: ImportModelProgress[]
  currentIndex: number
  total: number
  totalRecords: number
  cumulativeImported: number
  status: "idle" | "importing" | "done" | "error"
  message?: string
  /** Tổng thời gian import (ms). */
  totalDurationMs?: number
  /** Chi tiết từng lô HTTP (báo cáo copy). */
  jobTimings?: ImportJobTimingEntry[]
}

export function withSkippedRemaining(
  models: ImportModelProgress[]
): ImportModelProgress[] {
  return models.map((model) =>
    model.status === "pending" || model.status === "importing"
      ? { ...model, status: "skipped" as const }
      : model
  )
}

const STATUS_META: Record<
  ImportModelStatus,
  {
    label: string
    icon: typeof Circle
    className: string
    spin?: boolean
  }
> = {
  pending: {
    label: "Chờ",
    icon: Circle,
    className: "text-muted-foreground",
  },
  importing: {
    label: "Đang import",
    icon: Loader2,
    className: "text-primary",
    spin: true,
  },
  done: {
    label: "Xong",
    icon: CheckCircle2,
    className: "text-emerald-600",
  },
  error: {
    label: "Lỗi",
    icon: XCircle,
    className: "text-destructive",
  },
  skipped: {
    label: "Bỏ qua",
    icon: MinusCircle,
    className: "text-muted-foreground",
  },
}

async function copyTextToClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    try {
      const textarea = document.createElement("textarea")
      textarea.value = text
      textarea.setAttribute("readonly", "")
      textarea.style.position = "fixed"
      textarea.style.left = "-9999px"
      document.body.appendChild(textarea)
      textarea.select()
      const ok = document.execCommand("copy")
      document.body.removeChild(textarea)
      return ok
    } catch {
      return false
    }
  }
}

function CopyTextButton({
  text,
  label,
  copiedLabel = "Đã copy",
  className,
  onCopied,
}: {
  text: string
  label: string
  copiedLabel?: string
  className?: string
  onCopied?: () => void
}) {
  const [copied, setCopied] = useState(false)

  const handleCopy = useCallback(async () => {
    const ok = await copyTextToClipboard(text)
    if (!ok) {
      toast.error("Không copy được — thử chọn và copy thủ công.")
      return
    }
    setCopied(true)
    onCopied?.()
    window.setTimeout(() => setCopied(false), 2000)
  }, [onCopied, text])

  return (
    <Button
      type="button"
      size="sm"
      variant="ghost"
      className={cn("h-7 gap-1 px-2 text-xs", className)}
      onClick={() => void handleCopy()}
      title={label}
    >
      {copied ? (
        <>
          <Check className="size-3.5" aria-hidden />
          {copiedLabel}
        </>
      ) : (
        <>
          <Copy className="size-3.5" aria-hidden />
          {label}
        </>
      )}
    </Button>
  )
}

function ModelStatusIcon({ status }: { status: ImportModelStatus }) {
  const meta = STATUS_META[status]
  const Icon = meta.icon
  return (
    <Icon
      className={cn(
        "size-3.5 shrink-0",
        meta.className,
        meta.spin && "animate-spin"
      )}
      aria-hidden
    />
  )
}

type ImportProgressPanelProps = {
  progress: ImportProgressState
  onReset: () => void
}

export function ImportProgressPanel({
  progress,
  onReset,
}: ImportProgressPanelProps) {
  const {
    active,
    models,
    total,
    totalRecords,
    cumulativeImported,
    status,
    message,
    currentIndex,
    totalDurationMs,
  } = progress

  const doneCount = models.filter((m) => m.status === "done").length
  const errorCount = models.filter((m) => m.status === "error").length
  const skippedCount = models.filter((m) => m.status === "skipped").length
  const chunkMode = total > models.length
  const percent =
    totalRecords > 0
      ? Math.min(100, Math.round((cumulativeImported / totalRecords) * 100))
      : total > 0
        ? Math.min(100, Math.round(((currentIndex + 1) / total) * 100))
        : 0

  const headerLabel =
    status === "importing"
      ? "Đang import dữ liệu…"
      : status === "done"
        ? "Import hoàn tất"
        : status === "error"
          ? "Import có lỗi"
          : "Tiến trình import"

  const canReset = status === "done" || status === "error"

  const displayMessage = message ? formatImportErrorMessage(message) : undefined

  const copyReportText = buildImportProgressReport({
    status,
    message,
    cumulativeImported,
    totalRecords,
    currentIndex,
    total,
    models,
    totalDurationMs: progress.totalDurationMs,
    jobTimings: progress.jobTimings,
  })
  const canCopyReport = active && status !== "idle"
  const copyButtonLabel =
    status === "error" || errorCount > 0
      ? "Copy báo cáo"
      : status === "importing"
        ? "Copy tiến độ"
        : "Copy báo cáo"

  return (
    <FieldSectionValue
      className="max-w-full min-w-0 space-y-3 overflow-hidden px-4 py-3"
      data-import-progress-panel
    >
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="max-w-full min-w-0 flex-1 space-y-1 overflow-hidden">
          <p className="text-sm font-medium">{headerLabel}</p>
          <p className="text-xs text-muted-foreground">
            {cumulativeImported.toLocaleString("vi-VN")}
            {totalRecords > 0
              ? ` / ${totalRecords.toLocaleString("vi-VN")} bản ghi`
              : null}
            {chunkMode
              ? ` · lô ${Math.min(currentIndex + 1, total)}/${total}`
              : total > 0
                ? ` · ${doneCount}/${models.length} bảng`
                : null}
            {totalDurationMs != null && totalDurationMs > 0
              ? ` · ${formatImportDuration(totalDurationMs)}`
              : null}
          </p>
          {displayMessage ? (
            <p
              className={cn(
                "text-xs leading-relaxed font-medium break-words",
                status === "error"
                  ? "text-destructive"
                  : "text-muted-foreground"
              )}
              title={message !== displayMessage ? message : undefined}
            >
              {displayMessage}
            </p>
          ) : null}
        </div>
        <div className="flex flex-wrap items-center gap-1.5">
          {errorCount > 0 ? (
            <Badge variant="destructive" className="text-[10px] font-normal">
              {errorCount} lỗi
            </Badge>
          ) : null}
          {skippedCount > 0 ? (
            <Badge variant="secondary" className="text-[10px] font-normal">
              {skippedCount} bỏ qua
            </Badge>
          ) : null}
          {canCopyReport ? (
            <CopyTextButton
              text={copyReportText}
              label={copyButtonLabel}
              onCopied={() =>
                toast.success(
                  status === "importing"
                    ? "Đã copy tiến độ import."
                    : "Đã copy báo cáo import."
                )
              }
            />
          ) : null}
          {canReset ? (
            <Button
              type="button"
              size="sm"
              variant="ghost"
              className="h-7 px-2 text-xs"
              onClick={onReset}
            >
              Đóng
            </Button>
          ) : null}
        </div>
      </div>

      <div
        className="h-1.5 overflow-hidden rounded-full bg-muted"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        aria-label="Tiến trình import"
      >
        <div
          className={cn(
            "h-full rounded-full transition-all duration-300",
            status === "error" ? "bg-destructive" : "bg-primary"
          )}
          style={{ width: `${percent}%` }}
        />
      </div>

      <ul className="max-h-72 space-y-1 overflow-y-auto rounded-md border bg-background/60 p-2 text-xs">
        {models.map((model) => {
          const meta = STATUS_META[model.status]
          const displayError = model.error
            ? formatImportErrorMessage(model.error)
            : undefined
          const rowDetails = model.rowErrorDetails ?? []
          return (
            <li
              key={model.name}
              className="flex items-start gap-2 rounded px-1.5 py-1 hover:bg-muted/40"
            >
              <ModelStatusIcon status={model.status} />
              <div className="min-w-0 flex-1">
                <div className="flex w-full items-start justify-between gap-1.5">
                  <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
                    <span className="font-mono text-[11px]">{model.name}</span>
                    <span className="text-muted-foreground">
                      ({model.records.toLocaleString("vi-VN")})
                    </span>
                    <span className={cn("text-[10px]", meta.className)}>
                      {meta.label}
                    </span>
                    {model.detail ? (
                      <span className="text-[10px] text-muted-foreground">
                        {model.detail}
                      </span>
                    ) : null}
                    {model.timing && model.timing.wallMs > 0 ? (
                      <span
                        className="text-[10px] text-muted-foreground"
                        title={formatModelTimingSummary(model.timing)}
                      >
                        {formatModelTimingSummary(model.timing)}
                      </span>
                    ) : null}
                  </div>
                  {model.status === "error" ? (
                    <CopyTextButton
                      text={buildModelImportCopyText(model)}
                      label="Copy"
                      copiedLabel="OK"
                      className="h-6 shrink-0 px-1.5 text-[10px]"
                      onCopied={() =>
                        toast.success(`Đã copy lỗi bảng ${model.name}.`)
                      }
                    />
                  ) : null}
                </div>
                {displayError ? (
                  <p
                    className="mt-0.5 text-[10px] leading-relaxed font-medium break-words text-destructive"
                    title={model.errorTitle}
                  >
                    {displayError}
                  </p>
                ) : null}
                {rowDetails.length > 0 ? (
                  <ul className="mt-1 space-y-0.5 border-l border-destructive/30 pl-2">
                    {rowDetails.map((line, index) => (
                      <li
                        key={`${model.name}-err-${index}`}
                        className="text-[10px] leading-relaxed break-words text-destructive/90"
                      >
                        {line}
                      </li>
                    ))}
                  </ul>
                ) : null}
              </div>
            </li>
          )
        })}
      </ul>
    </FieldSectionValue>
  )
}

src/app/data/page.tsx.content:
"use client"

import { useState, useCallback } from "react"
import { toast } from "@ui/components/sonner"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { Badge } from "@ui/components/badge"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import {
  Field,
  FieldDescription,
  FieldLabel,
  FieldSectionDivider,
  FieldSectionLabel,
  FieldSectionLegend,
  FieldSectionValue,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import { readAdminSession } from "@/lib/auth-session"
import {
  AdminListPageHeader,
  AdminPageGuard,
  AdminPageSection,
} from "@ui/components/admin"
import {
  DEFAULT_API_URL,
  canUserAccess,
  PERMISSION_CODES,
} from "@workspace/api-client"
import { useAuth } from "@/providers/auth-provider"
import {
  Database,
  Download,
  FileSpreadsheet,
  FileJson,
  FolderOpen,
  Loader2,
  Upload,
} from "lucide-react"
import {
  ImportProgressPanel,
  type ImportProgressState,
} from "./import-progress-panel"
import { EntitySchemaPanel } from "./_component"
import {
  fetchImportConfig,
  runChunkedImport,
} from "./_component/import-chunked"
import { parseExcelToImportData } from "./_component/excel-to-import-data"
import {
  pickExportDirectory,
  saveExportBlob,
  supportsExportDirectoryPicker,
} from "@/lib/export-file-save"

function apiBase(): string {
  return (process.env.NEXT_PUBLIC_API_URL ?? DEFAULT_API_URL).replace(/\/$/, "")
}

type ApiEnvelope<T> = {
  success: boolean
  message?: string
  error?: string | null
  data?: T
}

const FILE_INPUT_CLASS =
  "h-9 w-full border-0 bg-transparent px-0 shadow-none focus-visible:ring-0 cursor-pointer text-sm file:mr-2 file:rounded-md file:border-0 file:bg-primary/10 file:px-2.5 file:py-1 file:text-xs file:font-medium file:text-primary hover:file:bg-primary/15"

function DataBackupPageInner() {
  const { user } = useAuth()
  const canExport = user
    ? canUserAccess(user, PERMISSION_CODES.SETTINGS_EXPORT) ||
      canUserAccess(user, PERMISSION_CODES.SETTINGS_MANAGE)
    : false
  const canImport = user
    ? canUserAccess(user, PERMISSION_CODES.SETTINGS_IMPORT) ||
      canUserAccess(user, PERMISSION_CODES.SETTINGS_MANAGE)
    : false
  const [exporting, setExporting] = useState<"json" | "excel" | null>(null)
  const [importProgress, setImportProgress] = useState<ImportProgressState>({
    active: false,
    models: [],
    currentIndex: 0,
    total: 0,
    totalRecords: 0,
    cumulativeImported: 0,
    status: "idle",
  })
  const [pickingDirectory, setPickingDirectory] = useState(false)
  const [exportDirectory, setExportDirectory] =
    useState<FileSystemDirectoryHandle | null>(null)
  const directoryPickerSupported = supportsExportDirectoryPicker()

  const dateStamp = () => {
    const now = new Date()
    const y = now.getFullYear()
    const m = String(now.getMonth() + 1).padStart(2, "0")
    const d = String(now.getDate()).padStart(2, "0")
    return `${y}-${m}-${d}`
  }

  const authHeaders = useCallback((): HeadersInit => {
    const headers: Record<string, string> = {}
    const uid = readAdminSession()?.id
    if (uid != null) headers["X-User-Id"] = String(uid)
    return headers
  }, [])

  const toastFetchError = useCallback(
    async (res: Response): Promise<string> => {
      let msg = ""
      try {
        const json = (await res.json()) as ApiEnvelope<unknown>
        msg =
          json.message?.trim() ||
          (typeof json.error === "string" ? json.error.trim() : "") ||
          ""
      } catch {
        const t = await res.text()
        msg = t.length > 280 ? `${t.slice(0, 280)}…` : t
      }
      if (res.status === 401) {
        const m =
          "API từ chối: thiếu hoặc sai X-User-Id — hãy đăng nhập lại admin."
        toast.error(m)
        return m
      }
      if (res.status === 403) {
        const m =
          msg || "Không đủ quyền xuất nhập hệ thống cho tài khoản hiện tại."
        toast.error(m)
        return m
      }
      const m = msg || `Lỗi ${res.status}`
      toast.error(m)
      return m
    },
    []
  )
  const chooseExportDirectory = async (): Promise<void> => {
    if (!directoryPickerSupported) {
      toast.error(
        "Trình duyệt không hỗ trợ chọn thư mục. Dùng Chrome hoặc Edge, hoặc hộp thoại lưu file sẽ mở khi xuất."
      )
      return
    }
    setPickingDirectory(true)
    try {
      const dir = await pickExportDirectory()
      if (!dir) return
      setExportDirectory(dir)
      toast.success(`Đã chọn thư mục lưu: ${dir.name}`)
    } catch {
      /* toast: MutationCache */
    } finally {
      setPickingDirectory(false)
    }
  }

  const persistExportBlob = async (
    blob: Blob,
    filename: string,
    mimeType: string,
    mimeLabel: string
  ): Promise<boolean> => {
    const mode = await saveExportBlob(blob, filename, {
      directory: exportDirectory,
      mimeType,
      mimeLabel,
    })
    if (mode === "cancelled") {
      toast.message("Đã hủy lưu file export.")
      return false
    }
    if (mode === "directory") {
      toast.success(
        `Đã lưu ${filename} vào thư mục ${exportDirectory?.name ?? "đã chọn"}.`
      )
      return true
    }
    if (mode === "save-picker") {
      toast.success(`Đã lưu ${filename}.`)
      return true
    }
    toast.success(`Đã tải ${filename} (thư mục Tải xuống mặc định).`)
    return true
  }

  const exportReady = !directoryPickerSupported || exportDirectory !== null

  const exportJson = async (): Promise<void> => {
    if (!exportReady) {
      toast.error("Hãy chọn thư mục lưu trước khi xuất JSON.")
      return
    }
    setExporting("json")
    try {
      const res = await fetch(`${apiBase()}/admin/system/export`, {
        headers: authHeaders(),
      })
      if (!res.ok) {
        await toastFetchError(res)
        return
      }
      const payload = (await res.json()) as ApiEnvelope<
        Record<string, unknown[]>
      >
      if (!payload.success || !payload.data) {
        toast.error(payload.message || "API không trả dữ liệu export hợp lệ.")
        return
      }

      const filename = `hub-system-export-${dateStamp()}.json`
      const blob = new Blob([JSON.stringify(payload.data, null, 2)], {
        type: "application/json;charset=utf-8",
      })
      await persistExportBlob(blob, filename, "application/json", "JSON")
    } catch (e) {
      toast.error(
        e instanceof Error ? e.message : "Lỗi mạng — kiểm tra API đang chạy."
      )
    } finally {
      setExporting(null)
    }
  }

  const exportExcel = async (): Promise<void> => {
    if (!exportReady) {
      toast.error("Hãy chọn thư mục lưu trước khi xuất Excel.")
      return
    }
    setExporting("excel")
    try {
      const res = await fetch(`${apiBase()}/admin/system/export/excel`, {
        headers: authHeaders(),
      })
      if (!res.ok) {
        await toastFetchError(res)
        return
      }
      const filename = `hub-system-export-${dateStamp()}.xlsx`
      const blob = await res.blob()
      await persistExportBlob(
        blob,
        filename,
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "Excel"
      )
    } catch (e) {
      toast.error(
        e instanceof Error ? e.message : "Lỗi mạng — kiểm tra API đang chạy."
      )
    } finally {
      setExporting(null)
    }
  }

  const resetImportProgress = useCallback(() => {
    setImportProgress({
      active: false,
      models: [],
      currentIndex: 0,
      total: 0,
      totalRecords: 0,
      cumulativeImported: 0,
      status: "idle",
    })
  }, [])

  const runFileImport = useCallback(
    async (data: Record<string, unknown[]>, sourceLabel: string) => {
      const modelKeys = Object.keys(data).filter(
        (key) => Array.isArray(data[key]) && data[key].length > 0
      )
      if (modelKeys.length === 0) {
        toast.error(`File ${sourceLabel} không chứa dữ liệu nào.`)
        return
      }

      setImportProgress((prev) => ({ ...prev, active: true }))

      try {
        const config = await fetchImportConfig(apiBase(), authHeaders)
        const result = await runChunkedImport({
          apiBase: apiBase(),
          authHeaders,
          config,
          data,
          onProgress: setImportProgress,
          toastFetchError,
        })
        toast[result.success ? "success" : "error"](result.message)
      } catch (error) {
        toast.error(
          error instanceof Error
            ? error.message
            : "Lỗi mạng — kiểm tra API đang chạy."
        )
        resetImportProgress()
      }
    },
    [authHeaders, resetImportProgress, toastFetchError]
  )

  const importJsonFile = async (file: File | null): Promise<void> => {
    if (!file) return
    resetImportProgress()

    try {
      const text = await file.text()
      let body: Record<string, unknown[]>
      try {
        body = JSON.parse(text) as Record<string, unknown[]>
      } catch {
        toast.error("File không phải JSON hợp lệ.")
        return
      }
      await runFileImport(body, "JSON")
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Không đọc được file JSON."
      )
      resetImportProgress()
    }
  }

  const importExcelFile = async (file: File | null): Promise<void> => {
    if (!file) return
    resetImportProgress()

    try {
      const buffer = await file.arrayBuffer()
      const body = parseExcelToImportData(buffer)
      await runFileImport(body, "Excel")
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "Không đọc được file Excel."
      )
      resetImportProgress()
    }
  }

  const importBusy =
    importProgress.active && importProgress.status === "importing"
  const exportBusy = exporting !== null

  const showBackupPanel = canExport || canImport

  return (
    <AdminPageSection className="space-y-4">
      <AdminListPageHeader
        icon={Database}
        title="Sao lưu & phục hồi dữ liệu"
        subtitle="Snapshot toàn hệ thống — chọn thư mục lưu, xuất hoặc import file export."
      />

      {readAdminSession() == null ? (
        <Alert variant="destructive" className="py-3">
          <AlertTitle className="text-sm">Chưa đăng nhập admin</AlertTitle>
          <AlertDescription className="text-xs">
            Cần quyền{" "}
            <code className="rounded bg-muted px-1">settings:manage</code> hoặc{" "}
            <code className="rounded bg-muted px-1">settings:import</code>.
          </AlertDescription>
        </Alert>
      ) : null}

      {showBackupPanel ? (
        <FieldSet variant="section">
          <FieldSectionLegend
            icon={Database}
            title="Thao tác sao lưu"
            description="hub-system-export-YYYY-MM-DD (.json / .xlsx)"
            badge={
              canExport ? (
                exportReady ? (
                  <Badge variant="outline" className="text-xs font-normal">
                    Sẵn sàng xuất
                  </Badge>
                ) : (
                  <Badge variant="secondary" className="text-xs font-normal">
                    Chọn thư mục
                  </Badge>
                )
              ) : undefined
            }
          />
          <FieldSetContent
            variant="section"
            className="space-y-4 px-4 pt-0 pb-4 sm:px-5"
          >
            {canExport ? (
              <div className="space-y-2">
                <FieldSectionLabel icon={Download}>
                  Xuất dữ liệu
                </FieldSectionLabel>
                <FieldSectionValue className="flex min-h-10 flex-wrap items-center gap-2 py-2">
                  <FolderOpen
                    className="size-4 shrink-0 text-muted-foreground"
                    aria-hidden
                  />
                  <span
                    className={cn(
                      "min-w-0 flex-1 truncate font-mono text-xs sm:text-sm",
                      exportDirectory
                        ? "text-foreground"
                        : "text-muted-foreground"
                    )}
                    title={
                      exportDirectory?.name ??
                      (directoryPickerSupported
                        ? "Chưa chọn thư mục"
                        : "Hộp thoại lưu khi xuất")
                    }
                  >
                    {exportDirectory
                      ? exportDirectory.name
                      : directoryPickerSupported
                        ? "Chưa chọn thư mục"
                        : "Hộp thoại lưu khi xuất"}
                  </span>
                  {directoryPickerSupported ? (
                    <>
                      <Button
                        type="button"
                        size="sm"
                        variant="outline"
                        className="h-8 shrink-0 gap-1.5"
                        disabled={pickingDirectory || exportBusy}
                        onClick={() => void chooseExportDirectory()}
                      >
                        {pickingDirectory ? (
                          <Loader2 className="size-3.5 animate-spin" />
                        ) : (
                          <FolderOpen className="size-3.5" />
                        )}
                        Thư mục
                      </Button>
                      {exportDirectory ? (
                        <Button
                          type="button"
                          size="sm"
                          variant="ghost"
                          className="h-8 shrink-0 px-2 text-muted-foreground"
                          disabled={exportBusy}
                          onClick={() => setExportDirectory(null)}
                        >
                          Bỏ
                        </Button>
                      ) : null}
                    </>
                  ) : null}
                  <span
                    className="hidden h-5 w-px shrink-0 bg-border sm:block"
                    aria-hidden
                  />
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    className="h-8 shrink-0 gap-1.5"
                    disabled={exportBusy || !exportReady}
                    onClick={() => void exportJson()}
                  >
                    {exporting === "json" ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : (
                      <FileJson className="size-3.5" />
                    )}
                    JSON
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    className="h-8 shrink-0 gap-1.5"
                    disabled={exportBusy || !exportReady}
                    onClick={() => void exportExcel()}
                  >
                    {exporting === "excel" ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : (
                      <FileSpreadsheet className="size-3.5" />
                    )}
                    Excel
                  </Button>
                </FieldSectionValue>
              </div>
            ) : null}

            {canExport && canImport ? <FieldSectionDivider /> : null}

            {canImport ? (
              <div className="space-y-2">
                <FieldSectionLabel
                  icon={Upload}
                  className="text-destructive normal-case"
                >
                  Import — ghi đè toàn bộ
                  <Badge
                    variant="destructive"
                    className="ml-2 align-middle text-[10px] font-normal"
                  >
                    Nguy hiểm
                  </Badge>
                </FieldSectionLabel>
                <FieldDescription className="text-xs">
                  Xóa dữ liệu các bảng đã đăng ký rồi nạp lại — chỉ dùng khi đã
                  sao lưu. File lớn được gửi theo từng lô (mặc định 500 bản
                  ghi/lần) để tránh timeout MySQL.
                </FieldDescription>
                <div className="grid gap-3 sm:grid-cols-2">
                  <Field className="gap-1.5">
                    <FieldLabel className="flex items-center gap-1.5 text-xs font-medium normal-case">
                      <FileJson className="size-3.5 text-sky-600" />
                      File JSON
                    </FieldLabel>
                    <FieldSectionValue className="px-4 py-1">
                      <Input
                        type="file"
                        accept="application/json,.json"
                        disabled={importBusy}
                        className={FILE_INPUT_CLASS}
                        onChange={(e) =>
                          void importJsonFile(
                            e.target.files?.[0] ?? null
                          ).finally(() => {
                            e.target.value = ""
                          })
                        }
                      />
                    </FieldSectionValue>
                  </Field>

                  <Field className="gap-1.5">
                    <FieldLabel className="flex items-center gap-1.5 text-xs font-medium normal-case">
                      <FileSpreadsheet className="size-3.5 text-emerald-600" />
                      File Excel
                    </FieldLabel>
                    <FieldSectionValue className="px-4 py-1">
                      <Input
                        type="file"
                        accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                        disabled={importBusy}
                        className={FILE_INPUT_CLASS}
                        onChange={(e) =>
                          void importExcelFile(
                            e.target.files?.[0] ?? null
                          ).finally(() => {
                            e.target.value = ""
                          })
                        }
                      />
                    </FieldSectionValue>
                  </Field>
                </div>

                {importProgress.active ? (
                  <ImportProgressPanel
                    progress={importProgress}
                    onReset={resetImportProgress}
                  />
                ) : null}
              </div>
            ) : null}
          </FieldSetContent>
        </FieldSet>
      ) : null}

      <EntitySchemaPanel />
    </AdminPageSection>
  )
}

export default function DataBackupPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin"]}>
      <DataBackupPageInner />
    </AdminPageGuard>
  )
}

src/app/data/_component/columns.tsx.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { Badge } from "@ui/components/badge"
import { cn } from "@ui/lib/utils"
import { ArrowRight, GitBranch } from "lucide-react"
import type { EntityRelationRow, EntitySchemaRow } from "./types"
import { DOMAIN_BADGE_CLASS, formatEntityRowCount } from "./utils"

function RefBadges({ tables }: { tables: string[] }) {
  if (!tables.length) {
    return <span className="text-xs text-muted-foreground">—</span>
  }
  return (
    <div className="flex flex-wrap gap-1">
      {tables.map((table) => (
        <Badge key={table} variant="outline" className="font-mono text-[10px]">
          {table}
        </Badge>
      ))}
    </div>
  )
}

const CARDINALITY_LABEL: Record<EntityRelationRow["cardinality"], string> = {
  "many-to-one": "N:1",
  "one-to-one": "1:1",
  self: "self",
}

export function getEntitySchemaColumns(): ColumnDef<EntitySchemaRow>[] {
  return [
    {
      accessorKey: "tableName",
      header: "Bảng DB",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm font-medium">
          {String(getValue())}
        </span>
      ),
    },
    {
      accessorKey: "entityName",
      header: "Entity",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      accessorKey: "exportModelName",
      header: "Model export",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => (
        <span className="font-mono text-xs">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "activeRowCount",
      header: "Bản ghi",
      enableColumnFilter: false,
      size: 100,
      meta: { className: "w-[100px] min-w-[100px] max-w-[120px]" },
      cell: ({ row }) => {
        const { activeRowCount, rowCount, trashedRowCount } = row.original
        if (activeRowCount < 0) {
          return <span className="text-xs text-muted-foreground">—</span>
        }
        return (
          <div className="tabular-nums">
            <span className="text-sm font-medium">
              {formatEntityRowCount(activeRowCount)}
            </span>
            {trashedRowCount > 0 ? (
              <p className="text-[10px] text-muted-foreground">
                +{formatEntityRowCount(trashedRowCount)} thùng rác
              </p>
            ) : rowCount !== activeRowCount ? (
              <p className="text-[10px] text-muted-foreground">
                tổng {formatEntityRowCount(rowCount)}
              </p>
            ) : null}
          </div>
        )
      },
    },
    {
      accessorKey: "domain",
      header: "Nhóm",
      enableColumnFilter: false,
      cell: ({ getValue }) => {
        const domain = String(getValue())
        return (
          <Badge
            variant="outline"
            className={cn(
              "text-[10px] font-normal",
              DOMAIN_BADGE_CLASS[domain]
            )}
          >
            {domain}
          </Badge>
        )
      },
    },
    {
      accessorKey: "columnCount",
      header: "Cột",
      enableColumnFilter: false,
      size: 72,
      meta: { className: "w-[72px] min-w-[72px] max-w-[72px]" },
      cell: ({ row }) => (
        <span className="text-sm text-muted-foreground tabular-nums">
          {row.original.columnCount}
          {row.original.fkCount > 0 ? (
            <span className="text-[10px]"> ({row.original.fkCount} FK)</span>
          ) : null}
        </span>
      ),
    },
    {
      accessorKey: "referencesOut",
      header: "Tham chiếu tới",
      enableColumnFilter: false,
      cell: ({ row }) => <RefBadges tables={row.original.referencesOut} />,
    },
    {
      accessorKey: "referencedBy",
      header: "Được tham chiếu bởi",
      enableColumnFilter: false,
      cell: ({ row }) => <RefBadges tables={row.original.referencedBy} />,
    },
    {
      accessorKey: "description",
      header: "Mô tả",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => (
        <span className="line-clamp-2 text-xs text-muted-foreground">
          {String(getValue() || "—")}
        </span>
      ),
    },
  ]
}

export function getEntityRelationColumns(): ColumnDef<EntityRelationRow>[] {
  return [
    {
      accessorKey: "fromTable",
      header: "Từ bảng",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "fromColumn",
      header: "Cột",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      id: "arrow",
      header: "",
      enableSorting: false,
      enableColumnFilter: false,
      size: 40,
      meta: { className: "w-10 min-w-10 max-w-10 px-0 text-center" },
      cell: () => (
        <ArrowRight className="mx-auto size-4 text-muted-foreground" />
      ),
    },
    {
      accessorKey: "toTable",
      header: "Đến bảng",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-sm">{String(getValue())}</span>
      ),
    },
    {
      accessorKey: "toColumn",
      header: "Cột đích",
      enableColumnFilter: false,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue())}
        </span>
      ),
    },
    {
      accessorKey: "cardinality",
      header: "Quan hệ",
      enableColumnFilter: false,
      size: 88,
      cell: ({ getValue }) => {
        const value = getValue() as EntityRelationRow["cardinality"]
        return (
          <Badge variant="secondary" className="gap-1 font-mono text-[10px]">
            <GitBranch className="size-3" />
            {CARDINALITY_LABEL[value]}
          </Badge>
        )
      },
    },
    {
      accessorKey: "deleteRule",
      header: "On delete",
      enableColumnFilter: false,
      meta: { defaultHidden: true },
      cell: ({ getValue }) => {
        const rule = getValue() as string | undefined
        return rule ? (
          <Badge variant="outline" className="font-mono text-[10px]">
            {rule}
          </Badge>
        ) : (
          <span className="text-xs text-muted-foreground">—</span>
        )
      },
    },
  ]
}

src/app/data/_component/entity-schema-pa.content:
"use client"

import { useMemo, useState } from "react"
import type { ColumnFiltersState } from "@tanstack/react-table"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import { Badge } from "@ui/components/badge"
import { AdminDataTable } from "@ui/components/data-table"
import {
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell"
import { GitBranch, Loader2, TableProperties } from "lucide-react"
import { getEntityRelationColumns, getEntitySchemaColumns } from "./columns"
import { useDatabaseSchema } from "./_hooks"
import {
  buildEntityRelationRows,
  buildEntitySchemaRows,
  formatEntityRowCount,
} from "./utils"

export function EntitySchemaPanel() {
  const { schema, loading, error } = useDatabaseSchema(true)
  const [schemaTab, setSchemaTab] = useState<"tables" | "relations">("tables")
  const [globalFilter, setGlobalFilter] = useState("")
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])

  const entityRows = useMemo(
    () => (schema ? buildEntitySchemaRows(schema) : []),
    [schema]
  )
  const relationRows = useMemo(
    () => (schema ? buildEntityRelationRows(schema.relations) : []),
    [schema]
  )

  const entityColumns = useMemo(() => getEntitySchemaColumns(), [])
  const relationColumns = useMemo(() => getEntityRelationColumns(), [])

  return (
    <FieldSet variant="section">
      <FieldSectionLegend
        icon={TableProperties}
        title="Bảng entity (MikroORM)"
        description="Danh sách bảng từ apps/api/src/entities, số bản ghi và quan hệ FK"
        badge={
          schema ? (
            <Badge variant="outline" className="text-xs font-normal">
              {schema.tables.length} bảng · {schema.relations.length} quan hệ ·{" "}
              {formatEntityRowCount(
                schema.totalActiveRows ??
                  schema.tables.reduce(
                    (sum, t) =>
                      sum + Math.max(0, t.activeRowCount ?? t.rowCount ?? 0),
                    0
                  )
              )}{" "}
              bản ghi
            </Badge>
          ) : undefined
        }
      />
      <FieldSetContent
        variant="section"
        className="space-y-4 px-4 pt-0 pb-4 sm:px-5"
      >
        {loading ? (
          <div className="flex items-center gap-2 py-8 text-sm text-muted-foreground">
            <Loader2 className="size-4 animate-spin" />
            Đang tải metadata entity và đếm bản ghi…
          </div>
        ) : null}

        {error ? (
          <Alert variant="destructive">
            <AlertTitle className="text-sm">Không tải được schema</AlertTitle>
            <AlertDescription className="text-xs">{error}</AlertDescription>
          </Alert>
        ) : null}

        {!loading && !error && schema ? (
          <Tabs
            value={schemaTab}
            onValueChange={(v) => setSchemaTab(v as "tables" | "relations")}
          >
            <TabsList className={ADMIN_LIST_TABS_LIST_CLASS}>
              <TabsTrigger
                value="tables"
                className={ADMIN_LIST_TABS_TRIGGER_CLASS}
              >
                <TableProperties className="size-4" />
                Bảng ({entityRows.length})
              </TabsTrigger>
              <TabsTrigger
                value="relations"
                className={ADMIN_LIST_TABS_TRIGGER_CLASS}
              >
                <GitBranch className="size-4" />
                Quan hệ FK ({relationRows.length})
              </TabsTrigger>
            </TabsList>

            <TabsContent value="tables">
              <AdminDataTable
                tableScope="data-entity-tables"
                data={entityRows}
                getRowId={(row) => row.id}
                columns={entityColumns}
                isLoading={false}
                emptyLabel="Không có bảng entity."
                manualFiltering
                globalFilter={globalFilter}
                onGlobalFilterChange={setGlobalFilter}
                globalFilterPlaceholder="Tìm theo tên bảng, entity, domain…"
                columnFilters={columnFilters}
                onColumnFiltersChange={setColumnFilters}
                showIndexColumn
                showColumnFilters={false}
                footer={
                  <p className="text-xs text-muted-foreground">
                    Nguồn: MikroORM metadata từ{" "}
                    <code className="rounded bg-muted px-1">
                      apps/api/src/entities
                    </code>
                    . &quot;Bản ghi&quot; = số dòng đang hoạt động; bảng có{" "}
                    <code className="rounded bg-muted px-1">deletedAt</code>{" "}
                    hiển thị thêm số trong thùng rác. Sắp xếp theo số bản ghi
                    giảm dần.
                  </p>
                }
              />
            </TabsContent>

            <TabsContent value="relations">
              <AdminDataTable
                tableScope="data-entity-relations"
                data={relationRows}
                getRowId={(row) => row.id}
                columns={relationColumns}
                isLoading={false}
                emptyLabel="Không có quan hệ FK."
                manualFiltering
                globalFilter={globalFilter}
                onGlobalFilterChange={setGlobalFilter}
                globalFilterPlaceholder="Tìm theo bảng hoặc cột…"
                columnFilters={columnFilters}
                onColumnFiltersChange={setColumnFilters}
                showIndexColumn
                showColumnFilters={false}
                footer={
                  <p className="text-xs text-muted-foreground">
                    Mỗi dòng là một quan hệ ManyToOne / OneToOne giữa hai
                    entity. Sơ đồ trực quan: menu{" "}
                    <code className="rounded bg-muted px-1">
                      /database-schema
                    </code>
                    .
                  </p>
                }
              />
            </TabsContent>
          </Tabs>
        ) : null}
      </FieldSetContent>
    </FieldSet>
  )
}

src/app/data/_component/excel-to-import-.content:
import * as XLSX from "xlsx"

const EXCEL_META_SHEET = "__meta"

function parseCellValue(value: unknown): unknown {
  if (value == null || value === "") return undefined
  if (value instanceof Date) return value.toISOString()
  return value
}

/**
 * Parse file .xlsx trên trình duyệt — cùng cấu trúc JSON export/import của API.
 * Tránh upload một file lớn; dữ liệu được import theo lô qua `runChunkedImport`.
 */
export function parseExcelToImportData(
  arrayBuffer: ArrayBuffer
): Record<string, unknown[]> {
  const workbook = XLSX.read(arrayBuffer, {
    type: "array",
    cellDates: true,
    dense: true,
  })

  const sheetMap = new Map<string, string>()
  const modelNamesFromMeta: string[] = []
  const metaSheet = workbook.Sheets[EXCEL_META_SHEET]
  if (metaSheet) {
    const metaRows = XLSX.utils.sheet_to_json<(string | number | null)[]>(
      metaSheet,
      { header: 1, defval: null }
    )
    for (let rowIndex = 1; rowIndex < metaRows.length; rowIndex++) {
      const row = metaRows[rowIndex]
      if (!row) continue
      const modelName = String(row[0] ?? "").trim()
      const sheetName = String(row[1] ?? "").trim()
      const tableName = String(row[2] ?? "").trim()
      if (modelName && sheetName) {
        sheetMap.set(modelName, sheetName)
        modelNamesFromMeta.push(modelName)
        if (tableName) sheetMap.set(tableName, sheetName)
      }
    }
  }

  const data: Record<string, unknown[]> = {}
  const modelNames =
    modelNamesFromMeta.length > 0
      ? modelNamesFromMeta
      : workbook.SheetNames.filter((name) => name !== EXCEL_META_SHEET)

  for (const rawModelName of modelNames) {
    const sheetName = sheetMap.get(rawModelName) ?? rawModelName
    if (sheetName === EXCEL_META_SHEET) continue

    const worksheet = workbook.Sheets[sheetName]
    if (!worksheet) continue

    const matrix = XLSX.utils.sheet_to_json<(string | number | null)[]>(
      worksheet,
      { header: 1, defval: null }
    )
    if (matrix.length === 0) {
      data[rawModelName] = []
      continue
    }

    const headerRow = matrix[0] ?? []
    const headers = headerRow
      .map((value) => String(value ?? "").trim())
      .filter(Boolean)
    if (headers.length === 0) {
      data[rawModelName] = []
      continue
    }

    const rows: Record<string, unknown>[] = []
    for (let rowIndex = 1; rowIndex < matrix.length; rowIndex++) {
      const row = matrix[rowIndex]
      if (!row) continue

      const record: Record<string, unknown> = {}
      let hasValue = false

      headers.forEach((header, columnIndex) => {
        const parsed = parseCellValue(row[columnIndex])
        if (parsed === undefined) return
        record[header] = parsed
        hasValue = true
      })

      if (hasValue) {
        rows.push(record)
      }
    }

    data[rawModelName] = rows
  }

  return data
}

