import { useCallback, useState } from "react"
import { useForm } from "react-hook-form"
import type { UseMutationResult } from "@tanstack/react-query"
import type { EventConfirmAction, EventFormValues } from "../types"
import { eventFormSchema } from "../types"
import { buildPosterPayload } from "../utils"
import { zodResolver } from "@hookform/resolvers/zod"

const EMPTY_EDITOR_STATE = {
  root: {
    children: [
      {
        children: [],
        direction: null,
        format: "",
        indent: 0,
        type: "paragraph",
        version: 1,
      },
    ],
    direction: null,
    format: "",
    indent: 0,
    type: "root",
    version: 1,
  },
}

const EMPTY_VALUES: EventFormValues = {
  title: "",
  slug: "",
  posterUrl: "",
  description: "",
  startDate: "",
  endDate: "",
  checkinStart: "",
  checkinEnd: "",
  checkoutStart: "",
  checkoutEnd: "",
  registrationStart: "",
  registrationEnd: "",
  organizer: "",
  location: "",
  address: "",
  status: 1,
  isFeatured: false,
  featuredOrder: 0,
  allowCheckin: true,
  allowCheckout: true,
  requireFaceId: false,
  checkinCameraId: "",
  checkoutCameraId: "",
  maxParticipants: 0,
  format: 0,
  onlineLink: "",
  content: EMPTY_EDITOR_STATE,
  speakers: [],
}

export function buildEventPayload(
  values: EventFormValues
): Record<string, unknown> {
  return {
    title: values.title.trim(),
    slug: values.slug?.trim() || null,
    poster: buildPosterPayload(values.posterUrl),
    description: values.description?.trim() || null,
    startDate: values.startDate || null,
    endDate: values.endDate || null,
    checkinStart: values.checkinStart || null,
    checkinEnd: values.checkinEnd || null,
    checkoutStart: values.checkoutStart || null,
    checkoutEnd: values.checkoutEnd || null,
    registrationStart: values.registrationStart || null,
    registrationEnd: values.registrationEnd || null,
    organizer: values.organizer?.trim() || null,
    location: values.location?.trim() || null,
    address: values.address?.trim() || null,
    status: values.status,
    isFeatured: values.isFeatured ?? false,
    featuredOrder: values.featuredOrder ?? 0,
    allowCheckin: values.allowCheckin,
    allowCheckout: values.allowCheckout,
    requireFaceId: values.requireFaceId,
    checkinCameraId: values.checkinCameraId?.trim() || null,
    checkoutCameraId: values.checkoutCameraId?.trim() || null,
    maxParticipants: values.maxParticipants,
    format: values.format ?? 0,
    onlineLink: values.onlineLink?.trim() || null,
    content: values.content ?? null,
  }
}

export function useEventForm() {
  const form = useForm<EventFormValues>({
    resolver: zodResolver(eventFormSchema),
    defaultValues: EMPTY_VALUES,
  })
  const resetForm = useCallback(() => {
    form.reset(EMPTY_VALUES)
  }, [form])
  return { form, resetForm }
}

export function useHandleConfirmAction(
  deleteMutation: UseMutationResult<unknown, Error, string>,
  restoreMutation: UseMutationResult<unknown, Error, string>,
  purgeMutation: UseMutationResult<unknown, Error, string>,
  setConfirmAction: React.Dispatch<
    React.SetStateAction<EventConfirmAction | null>
  >
) {
  return useCallback(
    async ({ kind, row }: EventConfirmAction) => {
      try {
        if (kind === "delete") {
          await deleteMutation.mutateAsync(row.id)
        } else if (kind === "restore") {
          await restoreMutation.mutateAsync(row.id)
        } else if (kind === "purge") {
          await purgeMutation.mutateAsync(row.id)
        }
      } catch {
        /* toast: MutationCache */
      } finally {
        setConfirmAction(null)
      }
    },
    [deleteMutation, restoreMutation, purgeMutation, setConfirmAction]
  )
}

export function useConfirmAction() {
  const [confirmAction, setConfirmAction] = useState<EventConfirmAction | null>(
    null
  )
  return { confirmAction, setConfirmAction }
}

src/app/events/_component/_live/event-at.content:
"use client"

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react"
import { useQueryClient } from "@tanstack/react-query"
import { api } from "@/lib/api"
import { useEventRegistrationsQuery } from "../_query"
import { syncEventAttendanceUi } from "./event-attendance-sync"
import {
  eventRegistrationsPollInterval,
  useEventAttendanceSocket,
} from "./use-event-attendance-socket"
import type { EventAttendanceSocketPayload } from "./use-event-attendance-socket"

type EventAttendanceContextValue = {
  connected: boolean
  socketError: boolean
  lastPayload: EventAttendanceSocketPayload | null
  /** Tăng mỗi lần check-in/out — ép bảng re-render tức thì. */
  liveRevision: number
  applyAttendance: (payload: EventAttendanceSocketPayload) => void
}

const EventAttendanceContext =
  createContext<EventAttendanceContextValue | null>(null)

/** Socket + cache đăng ký luôn sống trên trang chi tiết sự kiện. */
export function EventAttendanceProvider({
  eventId,
  enabled = true,
  children,
}: {
  eventId: string
  enabled?: boolean
  children: ReactNode
}) {
  const queryClient = useQueryClient()
  const [liveRevision, setLiveRevision] = useState(0)
  const [lastPayload, setLastPayload] =
    useState<EventAttendanceSocketPayload | null>(null)

  const applyAttendance = useCallback(
    (payload: EventAttendanceSocketPayload) => {
      setLastPayload(payload)
      setLiveRevision((r) => r + 1)
      syncEventAttendanceUi(queryClient, eventId, payload)
    },
    [queryClient, eventId]
  )

  const { connected, socketError } = useEventAttendanceSocket(
    eventId,
    enabled,
    applyAttendance
  )

  const pollMs = eventRegistrationsPollInterval(connected)

  useEventRegistrationsQuery(api, eventId, {
    enabled: enabled && !!eventId,
    refetchInterval: pollMs,
  })

  const value = useMemo<EventAttendanceContextValue>(
    () => ({
      connected,
      socketError,
      lastPayload,
      liveRevision,
      applyAttendance,
    }),
    [applyAttendance, connected, lastPayload, liveRevision, socketError]
  )

  return (
    <EventAttendanceContext.Provider value={value}>
      {children}
    </EventAttendanceContext.Provider>
  )
}

export function useEventAttendanceContext(): EventAttendanceContextValue {
  const ctx = useContext(EventAttendanceContext)
  if (!ctx) {
    return {
      connected: false,
      socketError: false,
      lastPayload: null,
      liveRevision: 0,
      applyAttendance: () => {},
    }
  }
  return ctx
}

import type { QueryClient } from "@tanstack/react-query"
import type { EventDetail } from "../types"
import { patchRegistrationAttendanceCache } from "./patch-registration-attendance-cache"
import type { EventAttendanceSocketPayload } from "./use-event-attendance-socket"

type RegistrationRow = Record<string, unknown>

/** API / DB có thể trả 0/1 thay vì boolean. */
export function asAttendanceBool(value: unknown): boolean {
  return value === true || value === 1 || value === "1"
}

function recountFromRegistrations(regs: RegistrationRow[]) {
  let totalCheckins = 0
  let totalCheckouts = 0
  for (const row of regs) {
    if (asAttendanceBool(row.hasCheckin)) totalCheckins += 1
    if (asAttendanceBool(row.hasCheckout)) totalCheckouts += 1
  }
  return { totalCheckins, totalCheckouts }
}

function patchEventDetailCounts(
  queryClient: QueryClient,
  eventId: string,
  regs: RegistrationRow[]
): void {
  const { totalCheckins, totalCheckouts } = recountFromRegistrations(regs)
  queryClient.setQueryData<EventDetail>(
    ["events", "detail", eventId],
    (detail) => {
      if (!detail) return detail
      return {
        ...detail,
        totalCheckins,
        totalCheckouts,
      }
    }
  )
}

function cloneRegistrations(regs: RegistrationRow[]): RegistrationRow[] {
  return regs.map((row) => ({ ...row }))
}

/**
 * Gộp cache React Query + payload realtime mới nhất — bảng re-render ngay
 * kể cả khi query observer chưa kịp notify.
 */
export function mergeRegistrationRowsForDisplay(
  rows: RegistrationRow[] | undefined,
  lastPayload: EventAttendanceSocketPayload | null
): RegistrationRow[] {
  const base = cloneRegistrations(rows ?? [])
  if (!lastPayload?.registrationId) return base

  const targetId = String(lastPayload.registrationId)
  return base.map((row) => {
    if (String(row.id ?? "") !== targetId) {
      return {
        ...row,
        hasCheckin: asAttendanceBool(row.hasCheckin),
        hasCheckout: asAttendanceBool(row.hasCheckout),
        avatar: row.avatar ?? null,
      }
    }

    const hasCheckin =
      lastPayload.hasCheckin !== undefined
        ? asAttendanceBool(lastPayload.hasCheckin)
        : lastPayload.kind === "checkout"
          ? true
          : true
    const hasCheckout =
      lastPayload.hasCheckout !== undefined
        ? asAttendanceBool(lastPayload.hasCheckout)
        : lastPayload.kind === "checkout"

    return {
      ...row,
      hasCheckin,
      hasCheckout,
      avatar: row.avatar ?? null,
      updatedAt: lastPayload.at,
    }
  })
}

export function buildManualAttendancePayload(
  eventId: string,
  registrationId: string,
  row: RegistrationRow,
  action:
    | "checkin"
    | "checkout"
    | "reset-checkin"
    | "reset-checkout"
    | "reset-all"
): EventAttendanceSocketPayload {
  const at = new Date().toISOString()
  let hasCheckin = asAttendanceBool(row.hasCheckin)
  let hasCheckout = asAttendanceBool(row.hasCheckout)

  switch (action) {
    case "checkin":
      hasCheckin = true
      break
    case "checkout":
      hasCheckin = true
      hasCheckout = true
      break
    case "reset-checkout":
      hasCheckout = false
      break
    case "reset-checkin":
      hasCheckin = false
      hasCheckout = false
      break
    case "reset-all":
      hasCheckin = false
      hasCheckout = false
      break
  }

  return {
    kind: action === "checkout" ? "checkout" : "checkin",
    eventId,
    at,
    email: String(row.email ?? ""),
    fullName: String(row.fullName ?? ""),
    source: "manual",
    registrationId,
    hasCheckin,
    hasCheckout,
  }
}

export function buildPayloadFromRegistrationRow(
  eventId: string,
  row: RegistrationRow
): EventAttendanceSocketPayload {
  return {
    kind: asAttendanceBool(row.hasCheckout) ? "checkout" : "checkin",
    eventId,
    at: String(row.updatedAt ?? new Date().toISOString()),
    email: String(row.email ?? ""),
    fullName: String(row.fullName ?? ""),
    source: "manual",
    registrationId: String(row.id ?? ""),
    hasCheckin: asAttendanceBool(row.hasCheckin),
    hasCheckout: asAttendanceBool(row.hasCheckout),
  }
}

/**
 * Đồng bộ cache + đánh dấu stale (không refetch đồng loạt — tránh ghi đè optimistic).
 */
export function syncEventAttendanceUi(
  queryClient: QueryClient,
  eventId: string,
  payload: EventAttendanceSocketPayload
): void {
  patchRegistrationAttendanceCache(queryClient, eventId, payload)

  const regs = queryClient.getQueryData<RegistrationRow[]>([
    "events",
    eventId,
    "registrations",
  ])
  if (regs?.length) {
    patchEventDetailCounts(queryClient, eventId, regs)
  }

  void queryClient.invalidateQueries({
    queryKey: ["events", eventId],
    refetchType: "active",
  })
}

export function applyOptimisticRegistrationAttendance(
  rows: RegistrationRow[] | undefined,
  registrationId: string,
  action:
    | "checkin"
    | "checkout"
    | "reset-checkin"
    | "reset-checkout"
    | "reset-all"
): RegistrationRow[] | undefined {
  if (!rows?.length) return rows
  const at = new Date().toISOString()
  const CHECKIN_METHOD_MANUAL = 3

  return rows.map((row) => {
    if (String(row.id) !== registrationId) return row
    switch (action) {
      case "checkin":
        return {
          ...row,
          hasCheckin: true,
          checkinMethod: CHECKIN_METHOD_MANUAL,
          updatedAt: at,
        }
      case "checkout":
        return {
          ...row,
          hasCheckin: true,
          hasCheckout: true,
          updatedAt: at,
        }
      case "reset-checkout":
        return {
          ...row,
          hasCheckout: false,
          updatedAt: at,
        }
      case "reset-checkin":
        return {
          ...row,
          hasCheckin: false,
          hasCheckout: false,
          checkinMethod: 0,
          updatedAt: at,
        }
      case "reset-all":
        return {
          ...row,
          hasCheckin: false,
          hasCheckout: false,
          checkinMethod: 0,
          updatedAt: at,
        }
      default:
        return row
    }
  })
}

