"use client"

import { useEffect, useRef, useState } from "react"

import { DEFAULT_API_URL } from "@workspace/api-client"

import { io, type Socket } from "socket.io-client"

import { readAdminSession } from "@/lib/auth-session"

export const EVENT_ATTENDANCE_SOCKET_PATH = "/api/socket"

export type EventAttendanceSocketPayload = {
  kind: "checkin" | "checkout"

  eventId: string

  at: string

  email: string

  fullName: string

  source: "hanet" | "manual"

  deviceId?: string | null

  deviceName?: string | null

  registrationId?: string | null

  checkinId?: string | null

  duplicate?: boolean

  hasCheckin?: boolean

  hasCheckout?: boolean
}

function getSocketOrigin(): string {
  const api = (process.env.NEXT_PUBLIC_API_URL ?? DEFAULT_API_URL).replace(
    /\/$/,

    ""
  )

  return api.replace(/\/api$/i, "")
}

function resolveSocketRole(): string {
  const session = readAdminSession()

  const primary = session?.roles?.[0]?.name?.trim()

  return primary ? primary.toLowerCase() : "admin"
}

const POLL_WHEN_DISCONNECTED_MS = 5_000

const POLL_WHEN_CONNECTED_MS = 45_000

export function useEventAttendanceSocket(
  eventId: string,

  enabled: boolean,

  onAttendance?: (payload: EventAttendanceSocketPayload) => void
): {
  connected: boolean

  socketError: boolean
} {
  const socketRef = useRef<Socket | null>(null)

  const onAttendanceRef = useRef(onAttendance)

  useEffect(() => {
    onAttendanceRef.current = onAttendance
  }, [onAttendance])

  const [connected, setConnected] = useState(false)

  const [socketError, setSocketError] = useState(false)

  useEffect(() => {
    if (!enabled || !eventId || typeof window === "undefined") {
      setConnected(false)

      setSocketError(false)

      return
    }

    const session = readAdminSession()

    const userId = session?.id != null ? String(session.id) : null

    if (!userId) {
      setConnected(false)

      setSocketError(true)

      return
    }

    let disposed = false

    const socket = io(getSocketOrigin(), {
      path: EVENT_ATTENDANCE_SOCKET_PATH,

      transports: ["polling", "websocket"],

      reconnection: true,

      reconnectionAttempts: 10,

      withCredentials: true,

      auth: {
        userId,

        role: resolveSocketRole(),
      },
    })

    socketRef.current = socket

    const onConnect = () => {
      if (disposed) return

      setConnected(true)

      setSocketError(false)

      socket.emit("event:join", { eventId })
    }

    const onDisconnect = () => {
      if (disposed) return

      setConnected(false)
    }

    const onConnectError = () => {
      if (disposed) return

      setConnected(false)

      setSocketError(true)
    }

    const onAttendance = (payload: EventAttendanceSocketPayload) => {
      if (disposed || payload?.eventId !== eventId) return

      onAttendanceRef.current?.(payload)
    }

    socket.on("connect", onConnect)

    socket.on("disconnect", onDisconnect)

    socket.on("connect_error", onConnectError)

    socket.on("event:attendance", onAttendance)

    return () => {
      disposed = true

      socket.off("connect", onConnect)

      socket.off("disconnect", onDisconnect)

      socket.off("connect_error", onConnectError)

      socket.off("event:attendance", onAttendance)

      if (socket.connected) {
        socket.emit("event:leave", { eventId })
      }

      socket.close()

      socketRef.current = null

      setConnected(false)

      setSocketError(false)
    }
  }, [enabled, eventId])

  return { connected, socketError }
}

export function eventRegistrationsPollInterval(
  connected: boolean
): number | false {
  return connected ? POLL_WHEN_CONNECTED_MS : POLL_WHEN_DISCONNECTED_MS
}

src/app/events/_component/_query/use-eve.content:
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@/lib/fetch-all-admin-list"
import { useQuery } from "@tanstack/react-query"
import type { StoreSyncSdk } from "@workspace/api-client"
import type { EventLiveQueryOptions } from "./use-events-queries"

type Dict = Record<string, unknown>

const LIVE_LIST_LIMIT = 200

function liveQueryOptions(eventId: string, options?: EventLiveQueryOptions) {
  return {
    enabled: !!eventId && (options?.enabled ?? true),
    refetchInterval: options?.refetchInterval,
    refetchIntervalInBackground: Boolean(options?.refetchInterval),
    refetchOnWindowFocus: true,
  }
}

export function useEventRegistrationsQuery(
  apiParam: StoreSyncSdk,
  eventId: string,
  options?: EventLiveQueryOptions
): UseQueryResult<Dict[]> {
  return useQuery({
    queryKey: ["events", eventId, "registrations"],
    queryFn: async (): Promise<Dict[]> => {
      const result = await apiParam.eventRegistrations.list<Dict>({
        eventId,
        limit: LIVE_LIST_LIMIT,
      })
      return result.items
    },
    ...liveQueryOptions(eventId, options),
    /** Luôn re-render bảng khi patch cache optimistic (tránh structural sharing giữ reference cũ). */
    structuralSharing: false,
  })
}

export function useEventCheckinsQuery(
  apiParam: StoreSyncSdk,
  eventId: string,
  options?: EventLiveQueryOptions
): UseQueryResult<Dict[]> {
  return useQuery({
    queryKey: ["events", eventId, "checkins"],
    queryFn: async (): Promise<Dict[]> => {
      const result = await apiParam.eventCheckins.list<Dict>({
        eventId,
        limit: LIVE_LIST_LIMIT,
      })
      return result.items
    },
    ...liveQueryOptions(eventId, options),
  })
}

export function useEventCheckoutsQuery(
  apiParam: StoreSyncSdk,
  eventId: string,
  options?: EventLiveQueryOptions
): UseQueryResult<Dict[]> {
  return useQuery({
    queryKey: ["events", eventId, "checkouts"],
    queryFn: async (): Promise<Dict[]> => {
      const result = await apiParam.eventCheckouts.list<Dict>({
        eventId,
        limit: LIVE_LIST_LIMIT,
      })
      return result.items
    },
    ...liveQueryOptions(eventId, options),
  })
}

export function useEventSpeakersQuery(
  apiParam: StoreSyncSdk,
  eventId: string
): UseQueryResult<Dict[]> {
  return useQuery({
    queryKey: ["events", eventId, "speakers"],
    queryFn: async (): Promise<Dict[]> => {
      const result = await apiParam.eventSpeakers.list<Dict>({
        eventId,
        limit: ADMIN_LIST_EXPORT_FETCH_LIMIT,
      })
      return result.items
    },
    enabled: !!eventId,
  })
}

import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@/lib/admin-detail-query"
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@/lib/fetch-all-admin-list"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client"
import type { EventDetail, EventRow } from "../types"

export type EventLiveQueryOptions = {
  enabled?: boolean
  refetchInterval?: number | false
}

export const eventDetailQueryKey = (id: string) =>
  ["events", "detail", id] as const

export function prefetchEventDetail(
  queryClient: QueryClient,
  apiParam: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(queryClient, eventDetailQueryKey(id), () =>
    apiParam.events.get<EventDetail>(id)
  )
}

export function useEventDetailQuery(
  apiParam: StoreSyncSdk,
  id: string,
  options?: EventLiveQueryOptions
) {
  return useQuery({
    ...adminDetailQueryOptions(
      eventDetailQueryKey(id),
      async () => apiParam.events.get<EventDetail>(id),
      id
    ),
    ...options,
    enabled: !!id && (options?.enabled ?? true),
  })
}

export function useEventsListQuery(
  apiParam: StoreSyncSdk,
  enabled: boolean,
  filters?: Record<string, string>
): UseQueryResult<EventRow[]> {
  return useQuery({
    queryKey: ["events", "list", filters],
    queryFn: async (): Promise<EventRow[]> => {
      const limit = ADMIN_LIST_EXPORT_FETCH_LIMIT
      const items: EventRow[] = []
      let page = 1
      let total = Number.POSITIVE_INFINITY
      while (items.length < total) {
        const result = await apiParam.events.list<EventRow>({
          page,
          limit,
          status: "active",
          filters,
        })
        items.push(...result.items)
        total = result.total
        if (result.items.length === 0) break
        page += 1
      }
      return items
    },
    enabled,
  })
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk
  trashPage: number
  trashPageSize: number
  debouncedTrashQ: string
  enabled: boolean
}

export function useEventsTrashQuery({
  api: apiParam,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  enabled,
  filters,
}: UseTrashQueryProps & { filters?: Record<string, string> }): UseQueryResult<
  PagedResult<EventRow>
> {
  return useQuery({
    queryKey: [
      "events",
      "trash",
      trashPage,
      trashPageSize,
      debouncedTrashQ,
      filters,
    ],
    enabled,
    queryFn: async (): Promise<PagedResult<EventRow>> =>
      apiParam.events.list<EventRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        filters,
      }),
  })
}

src/app/events/_component/_table/events-.content:
"use client"

import type {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import type { EventRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"

export interface EventsTableProps {
  data: EventRow[]
  columns: ColumnDef<EventRow>[]
  isLoading: boolean
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  total: number
  onClearFilters: () => void
  onBulkDelete: (rows: EventRow[]) => Promise<void>
  onBulkPurge: (rows: EventRow[]) => Promise<void>
  onRowPrefetch?: (row: EventRow) => void
}

export function EventsTable({
  data,
  columns,
  isLoading,
  columnFilters,
  onColumnFiltersChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  total,
  onClearFilters,
  onBulkDelete,
  onBulkPurge,
  onRowPrefetch,
}: EventsTableProps) {
  return (
    <AdminDataTable<EventRow>
      tableScope="events"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel='Chưa có sự kiện — bấm "Thêm sự kiện".'
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo tên..."
      onClearFilters={onClearFilters}
      onRowPointerEnter={
        onRowPrefetch ? (row) => onRowPrefetch(row.original) : undefined
      }
      clearFiltersVariant="destructive"
      xlsxExport={buildAdminTableXlsxExport("events", {
        pageCount: data.length,
        total,
      })}
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        {
          id: "bulk-event-delete",
          label: "Xóa tạm đã chọn",
          variant: "destructive",
          confirm: {
            title: "Đưa các sự kiện đã chọn vào thùng rác?",
            description: (rows) => `Bạn đã chọn ${rows.length} sự kiện.`,
            confirmLabel: "Xóa tạm",
            destructive: true,
          },
          onAction: onBulkDelete,
        },
        {
          id: "bulk-event-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          confirm: {
            title: "Xóa vĩnh viễn các sự kiện đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} sự kiện. Hành động này không thể hoàn tác!`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      footer={
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            {isLoading ? "Đang tải..." : `Tổng ${total} sự kiện`}
          </p>
        </div>
      }
    />
  )
}

"use client"

import type {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import type { EventRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"
import { api } from "@/lib/api"
import {
  createAdminTrashExportFetchPage,
  type AdminTrashExportParams,
} from "@/lib/admin-trash-export"

export interface EventsTrashTableProps {
  data: EventRow[]
  columns: ColumnDef<EventRow>[]
  isLoading: boolean
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  onClearFilters: () => void
  onBulkRestore: (rows: EventRow[]) => Promise<void>
  onBulkPurge: (rows: EventRow[]) => Promise<void>
  trashExportParams?: AdminTrashExportParams
}

export function EventsTrashTable({
  data,
  columns,
  isLoading,
  columnFilters,
  onColumnFiltersChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  page,
  pageSize,
  total,
  onPageChange,
  onPageSizeChange,
  onClearFilters,
  onBulkRestore,
  onBulkPurge,
  trashExportParams,
}: EventsTrashTableProps) {
  return (
    <AdminDataTable<EventRow>
      tableScope="events-trash"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Thùng rác trống."
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm trong thùng rác..."
      onClearFilters={onClearFilters}
      clearFiltersVariant="destructive"
      xlsxExport={buildAdminTableXlsxExport("events-trash", {
        pageCount: data.length,
        total,
      })}
      exportFetchPage={
        trashExportParams
          ? createAdminTrashExportFetchPage<EventRow>(
              (params) => api.events.list<EventRow>(params),
              trashExportParams
            )
          : undefined
      }
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        {
          id: "bulk-event-restore",
          label: "Khôi phục đã chọn",
          variant: "default",
          confirm: {
            title: "Khôi phục các sự kiện đã chọn?",
            description: (rows) => `Bạn đã chọn ${rows.length} sự kiện.`,
            confirmLabel: "Khôi phục",
          },
          onAction: onBulkRestore,
        },
        {
          id: "bulk-event-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          confirm: {
            title: "Xóa vĩnh viễn các sự kiện đã chọn?",
            description: () => `Hành động này không thể hoàn tác.`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      pagination={{
        page,
        pageSize,
        total,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có sự kiện trong thùng rác",
        itemLabel: "sự kiện",
      }}
    />
  )
}

src/app/file-storage/page.tsx.content:
"use client"

import { useCallback, useEffect, useMemo, useState } from "react"
import type {
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import { Button } from "@ui/components/button"
import {
  AdminListPageHeader,
  AdminPageGuard,
  AdminPageLoading,
  AdminPageSection,
} from "@ui/components/admin"
import { ImageLightbox } from "@ui/components/image-lightbox"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell"
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client"
import type { DataTableUserSearchHandlers } from "@ui/components/data-table"
import { useAuth } from "@/providers/auth-provider"
import { api } from "@/lib/api"
import { normalizeAdminFilterValue } from "@/lib/build-admin-filter-query"
import { useDebouncedValue } from "@/hooks/use-debounced-value"

const UPLOAD_OWNER_FILTER_DEBOUNCE_MS = 400
import {
  ArchiveRestore,
  Download,
  FileText,
  Image as ImageIcon,
  Loader2,
  Shuffle,
  Upload,
  Video,
  Music,
} from "lucide-react"
import {
  formatExtensionsSummary,
  getRealmDefaultExtensions,
} from "./_component/storage-upload-policy"
import {
  FileStorageCreateFolderButton,
  FileStorageDeleteFolderButton,
  FileStorageFolderNav,
  FileStorageGlobalEmpty,
  FileStorageImportConfirmDialogs,
  FileStorageMoveDialog,
  FileStorageReorganizeDialog,
  FileStorageTable,
  FileStorageUploadDialog,
  getFileStorageColumns,
  StorageVideoPreview,
  useFileStorageActions,
  useFileStorageList,
  type FileStorageRow,
  type StorageRealm,
} from "./_component"
import {
  isImageStorageRow,
  resolveStorageAssetUrl,
  resolveFolderPathAfterCreate,
} from "./_component/utils"

const REALM_ORDER: StorageRealm[] = ["images", "files", "videos", "audio"]

const REALM_ICONS: Record<StorageRealm, typeof ImageIcon> = {
  images: ImageIcon,
  files: FileText,
  videos: Video,
  audio: Music,
}

function FileStoragePageInner() {
  const { user } = useAuth()
  const canUpload = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_CREATE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false
  const canDelete = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_DELETE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false
  const canView = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_VIEW) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false
  const canManage = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false

  const [reorganizeOpen, setReorganizeOpen] = useState(false)
  const [moveDialogOpen, setMoveDialogOpen] = useState(false)
  const [moveRows, setMoveRows] = useState<FileStorageRow[]>([])

  const [activeRealm, setActiveRealm] = useState<StorageRealm>("images")
  const [activeFolderPath, setActiveFolderPath] = useState("")
  const [includeDescendants, setIncludeDescendants] = useState(false)
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(20)
  const [selectedRowIds, setSelectedRowIds] = useState<RowSelectionState>({})
  const [lightboxOpen, setLightboxOpen] = useState(false)
  const [lightboxIndex, setLightboxIndex] = useState(0)
  const [videoPreviewRow, setVideoPreviewRow] = useState<FileStorageRow | null>(
    null
  )
  const [folderRefreshKey, setFolderRefreshKey] = useState(0)

  const bumpFolderList = useCallback(() => {
    setFolderRefreshKey((key) => key + 1)
  }, [])

  const uploadOwnerFilter = useMemo(() => {
    const raw = columnFilters.find((f) => f.id === "uploadOwnerId")?.value
    return normalizeAdminFilterValue(raw) ?? ""
  }, [columnFilters])

  const debouncedUploadOwnerFilter = useDebouncedValue(
    uploadOwnerFilter,
    UPLOAD_OWNER_FILTER_DEBOUNCE_MS
  )

  const {
    rows,
    realms,
    childFolders,
    breadcrumb,
    loading,
    isFetching,
    total,
    reload,
  } = useFileStorageList(
    activeRealm,
    activeFolderPath,
    page,
    pageSize,
    includeDescendants,
    debouncedUploadOwnerFilter
  )

  const totalInStorage = useMemo(
    () => realms.reduce((sum, realm) => sum + realm.count, 0),
    [realms]
  )

  const realmTabs = useMemo(() => {
    const byId = new Map(realms.map((r) => [r.id, r]))
    return REALM_ORDER.map((id) => {
      const fromApi = byId.get(id)
      return (
        fromApi ?? {
          id,
          label:
            id === "images"
              ? "Hình ảnh"
              : id === "files"
                ? "Tệp tin"
                : id === "videos"
                  ? "Video"
                  : "Âm thanh",
          count: 0,
        }
      )
    })
  }, [realms])

  const {
    uploadDialogOpen,
    setUploadDialogOpen,
    setUploading,
    importInputRef,
    uploading,
    importing,
    deletingPath,
    downloadingPath,
    uploadAccept,
    handleImport,
    importConfirm,
    clearImportConfirm,
    handleImportConfirmRestore,
    handleImportConfirmOverwrite,
    handleImportSkipOverwrite,
    handleDownload,
    handleDownloadAll,
    handleBulkDownload,
    downloadingAll,
    handleDelete,
    handleBulkDelete,
    handleDeleteAllInTab,
    fetchAllRowsInScope,
    openUploadPicker,
    openImportPicker,
  } = useFileStorageActions({
    activeRealm,
    activeFolderPath,
    includeDescendants,
    uploadOwnerFilter: debouncedUploadOwnerFilter,
    reload,
  })

  const activeRealmMeta = realmTabs.find((r) => r.id === activeRealm)
  const currentFolderLabel =
    breadcrumb[breadcrumb.length - 1]?.label ??
    activeRealmMeta?.label ??
    activeRealm
  const activeTabLabel = breadcrumb.length
    ? `${activeRealmMeta?.label ?? activeRealm} · ${breadcrumb.map((c) => c.label).join(" / ")}`
    : activeRealmMeta?.label

  const realmUploadHint = useMemo(
    () => formatExtensionsSummary(getRealmDefaultExtensions(activeRealm)),
    [activeRealm]
  )

  const lightboxImages = useMemo(
    () =>
      rows
        .filter((r) => isImageStorageRow(r))
        .map((r) => ({
          key: r.relativePath,
          src: resolveStorageAssetUrl(r),
          altText: r.originalName,
        })),
    [rows]
  )

  const openImagePreview = useCallback(
    (row: FileStorageRow) => {
      const idx = lightboxImages.findIndex((li) => li.key === row.relativePath)
      if (idx >= 0) {
        setLightboxIndex(idx)
        setLightboxOpen(true)
      }
    },
    [lightboxImages]
  )

  const openVideoPreview = useCallback((row: FileStorageRow) => {
    setVideoPreviewRow(row)
  }, [])

  const handleRealmChange = useCallback(
    (value: string) => {
      setActiveRealm(value as StorageRealm)
      setActiveFolderPath("")
      setColumnFilters([])
      setPage(1)
      setSelectedRowIds({})
      bumpFolderList()
    },
    [bumpFolderList]
  )

  const handleFolderNavigate = useCallback((folderPath: string) => {
    setActiveFolderPath(folderPath)
    setPage(1)
    setSelectedRowIds({})
  }, [])

  const handleFolderCreated = useCallback(
    async (folderPath: string) => {
      setActiveFolderPath(resolveFolderPathAfterCreate(folderPath, activeRealm))
      setPage(1)
      setSelectedRowIds({})
      bumpFolderList()
      await reload()
    },
    [activeRealm, bumpFolderList, reload]
  )

  const handleFolderDeleted = useCallback(async () => {
    const parentPath =
      breadcrumb.length >= 2 ? breadcrumb[breadcrumb.length - 2].id : ""
    setActiveFolderPath(parentPath)
    setPage(1)
    setSelectedRowIds({})
    bumpFolderList()
    await reload()
  }, [breadcrumb, bumpFolderList, reload])

  const handleBulkMove = useCallback((selected: FileStorageRow[]) => {
    setMoveRows(selected)
    setMoveDialogOpen(true)
  }, [])

  const handleMoveCompleted = useCallback(async () => {
    setSelectedRowIds({})
    await reload()
  }, [reload])

  const handleMoveAllInScope = useCallback(async () => {
    const allRows = await fetchAllRowsInScope()
    if (!allRows.length) return
    setMoveRows(allRows)
    setMoveDialogOpen(true)
  }, [fetchAllRowsInScope])

  const handleIncludeDescendantsChange = useCallback((value: boolean) => {
    setIncludeDescendants(value)
    setPage(1)
    setSelectedRowIds({})
  }, [])

  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updater) => {
      setColumnFilters(updater)
    },
    []
  )

  useEffect(() => {
    setPage(1)
    setSelectedRowIds({})
  }, [debouncedUploadOwnerFilter])

  const handleClearFilters = useCallback(() => {
    setColumnFilters([])
    setPage(1)
    setSelectedRowIds({})
  }, [])

  const uploadOwnerSearchHandlers = useMemo<DataTableUserSearchHandlers>(
    () => ({
      onSearch: async (q) => {
        const res = await api.users.list({ q, page: 1, limit: 10 })
        return res.items.map((user) => ({
          id: user.id,
          label: user.fullName?.trim() || user.email,
          sublabel: user.email,
        }))
      },
      onResolveUser: async (id) => {
        const user = await api.users.get(id)
        return {
          id: user.id,
          label: user.fullName?.trim() || user.email,
          sublabel: user.email,
        }
      },
    }),
    []
  )

  const columns = useMemo(
    () =>
      getFileStorageColumns({
        canDelete,
        deletingPath,
        downloadingPath,
        onPreviewImage: openImagePreview,
        onPreviewVideo: openVideoPreview,
        onDownload: handleDownload,
        onDelete: handleDelete,
        uploadOwnerSearchHandlers,
      }),
    [
      canDelete,
      deletingPath,
      downloadingPath,
      handleDelete,
      handleDownload,
      openImagePreview,
      openVideoPreview,
      uploadOwnerSearchHandlers,
    ]
  )

  const wrappedBulkDelete = useCallback(
    async (selected: FileStorageRow[]) => {
      await handleBulkDelete(selected)
      setSelectedRowIds({})
    },
    [handleBulkDelete]
  )

  const tableProps = {
    data: rows,
    columns,
    isLoading: loading,
    isFetching,
    itemLabel: "file" as const,
    page,
    pageSize,
    total,
    onPageChange: setPage,
    onPageSizeChange: setPageSize,
    selectedRowIds,
    onSelectedRowIdsChange: setSelectedRowIds,
    onBulkDelete: wrappedBulkDelete,
    onBulkDownload: handleBulkDownload,
    onBulkMove: canManage ? handleBulkMove : undefined,
    onMoveAllInScope: canManage ? handleMoveAllInScope : undefined,
    onDeleteAllInTab: canDelete ? handleDeleteAllInTab : undefined,
    columnFilters,
    onColumnFiltersChange: handleColumnFiltersChange,
    onClearFilters: handleClearFilters,
    includeDescendants,
    canDelete,
    canUpload,
    uploading,
    onUpload: openUploadPicker,
  }

  return (
    <AdminPageSection>
      <AdminListPageHeader
        icon={ImageIcon}
        title="Kho lưu trữ file"
        subtitle="Điều hướng folder không giới hạn cấp. Di chuyển file giữa Hình ảnh / Tệp tin / Video. Tạo hoặc xóa folder theo phạm vi đang mở."
        actions={
          canUpload || canView ? (
            <div className="flex items-center gap-2">
              {canUpload ? (
                <>
                  <input
                    ref={importInputRef}
                    type="file"
                    accept=".zip,application/zip"
                    className="hidden"
                    onChange={(e) => void handleImport(e)}
                  />
                  <Button
                    type="button"
                    onClick={openUploadPicker}
                    disabled={uploading || importing || downloadingAll}
                  >
                    {uploading ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <Upload className="size-4" />
                    )}
                    {uploading ? "Đang tải…" : "Tải lên"}
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={openImportPicker}
                    disabled={uploading || importing || downloadingAll}
                  >
                    {importing ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <ArchiveRestore className="size-4" />
                    )}
                    {importing ? "Đang khôi phục…" : "Khôi phục kho"}
                  </Button>
                </>
              ) : null}
              {canManage ? (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setReorganizeOpen(true)}
                  disabled={downloadingAll || uploading || importing}
                >
                  <Shuffle className="size-4" />
                  Cấu trúc lại folder
                </Button>
              ) : null}
              {canView ? (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => void handleDownloadAll()}
                  disabled={downloadingAll || uploading || importing}
                >
                  {downloadingAll ? (
                    <Loader2 className="size-4 animate-spin" />
                  ) : (
                    <Download className="size-4" />
                  )}
                  {downloadingAll ? "Đang tải…" : "Tải về tất cả"}
                </Button>
              ) : null}
            </div>
          ) : undefined
        }
      />

      {loading && totalInStorage === 0 && realms.length === 0 ? (
        <AdminPageLoading variant="list" />
      ) : !loading && totalInStorage === 0 ? (
        <FileStorageGlobalEmpty
          canUpload={canUpload}
          uploading={uploading}
          importing={importing}
          onUpload={openUploadPicker}
          onImport={openImportPicker}
        />
      ) : (
        <Tabs value={activeRealm} onValueChange={handleRealmChange}>
          <div className="flex flex-wrap items-center gap-2">
            <TabsList className={`${ADMIN_LIST_TABS_LIST_CLASS} flex-wrap`}>
              {realmTabs.map((realm) => {
                const Icon = REALM_ICONS[realm.id as StorageRealm] ?? ImageIcon
                return (
                  <TabsTrigger
                    key={realm.id}
                    value={realm.id}
                    className={ADMIN_LIST_TABS_TRIGGER_CLASS}
                  >
                    <Icon className="size-4" />
                    {realm.label}
                    <span className="text-muted-foreground">
                      ({realm.count})
                    </span>
                  </TabsTrigger>
                )
              })}
            </TabsList>
            <p className="w-full text-xs text-muted-foreground">
              Tab «{activeRealmMeta?.label ?? activeRealm}»: cho phép import{" "}
              {realmUploadHint}. Folder cấp 1 có thể tùy chỉnh khi tạo mới.
            </p>
          </div>

          {realmTabs.map((realm) => (
            <TabsContent key={realm.id} value={realm.id} className="space-y-4">
              {activeRealm === realm.id ? (
                <div className="space-y-4">
                  <FileStorageFolderNav
                    realm={activeRealm}
                    realmLabel={realm.label}
                    breadcrumb={breadcrumb}
                    childFolders={childFolders}
                    activeFolderPath={activeFolderPath}
                    includeDescendants={includeDescendants}
                    onIncludeDescendantsChange={handleIncludeDescendantsChange}
                    onNavigate={handleFolderNavigate}
                    foldersRefreshKey={folderRefreshKey}
                    actions={
                      <>
                        {canUpload ? (
                          <FileStorageCreateFolderButton
                            realm={activeRealm}
                            parentFolderPath={activeFolderPath}
                            parentLabel={currentFolderLabel}
                            onCreated={handleFolderCreated}
                            disabled={uploading || importing}
                          />
                        ) : null}
                        {canDelete && activeFolderPath ? (
                          <FileStorageDeleteFolderButton
                            realm={activeRealm}
                            folderPath={activeFolderPath}
                            folderLabel={currentFolderLabel}
                            onDeleted={handleFolderDeleted}
                            disabled={uploading || importing}
                          />
                        ) : null}
                      </>
                    }
                  />
                  <FileStorageTable
                    tableScope={`file-storage-${realm.id}-${activeFolderPath || "root"}`}
                    emptyLabel={
                      debouncedUploadOwnerFilter
                        ? "Không có file khớp bộ lọc người upload."
                        : `Chưa có file trong «${currentFolderLabel}».`
                    }
                    emptySummary={
                      debouncedUploadOwnerFilter
                        ? "Không có file khớp bộ lọc"
                        : `Không có file trong ${currentFolderLabel}`
                    }
                    tabLabel={currentFolderLabel}
                    {...tableProps}
                  />
                </div>
              ) : null}
            </TabsContent>
          ))}
        </Tabs>
      )}

      <ImageLightbox
        open={lightboxOpen}
        images={lightboxImages}
        index={lightboxIndex}
        onIndexChange={setLightboxIndex}
        onClose={() => setLightboxOpen(false)}
      />

      <StorageVideoPreview
        row={videoPreviewRow}
        open={videoPreviewRow != null}
        onClose={() => setVideoPreviewRow(null)}
      />

      {canManage ? (
        <FileStorageReorganizeDialog
          open={reorganizeOpen}
          onOpenChange={setReorganizeOpen}
          realm={activeRealm}
          activeFolderPath={activeFolderPath}
          scopeLabel={activeTabLabel ?? activeRealmMeta?.label ?? activeRealm}
          onCompleted={reload}
        />
      ) : null}

      {canManage ? (
        <FileStorageMoveDialog
          open={moveDialogOpen}
          onOpenChange={setMoveDialogOpen}
          selectedRows={moveRows}
          onMoved={handleMoveCompleted}
        />
      ) : null}

      {canUpload ? (
        <FileStorageImportConfirmDialogs
          state={importConfirm}
          importing={importing}
          onClose={clearImportConfirm}
          onConfirmRestore={handleImportConfirmRestore}
          onConfirmOverwrite={handleImportConfirmOverwrite}
          onSkipOverwrite={handleImportSkipOverwrite}
        />
      ) : null}

      {canUpload ? (
        <FileStorageUploadDialog
          open={uploadDialogOpen}
          onOpenChange={setUploadDialogOpen}
          activeRealm={activeRealm}
          activeFolderPath={activeFolderPath}
          activeTabLabel={activeTabLabel}
          uploadAccept={uploadAccept}
          onUploaded={reload}
          onUploadingChange={setUploading}
        />
      ) : null}
    </AdminPageSection>
  )
}

export default function FileStoragePage() {
  return (
    <AdminPageGuard permission="uploads:view">
      <FileStoragePageInner />
    </AdminPageGuard>
  )
}

src/app/file-storage/_component/columns-.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { FileTypeIcon, FileTypeIconSm } from "@ui/components/file-type-icon"
import { defineDataTableActionsColumn } from "@ui/components/data-table"
import { Film, Play } from "lucide-react"
import { formatAdminDateTime } from "@/lib/format-admin-datetime"
import type { FileStorageRow } from "./types"
import {
  formatFileSize,
  formatUploadOwnerCell,
  isImageStorageRow,
  isVideoStorageRow,
  resolveStorageAssetUrl,
  storageThumbnailUrl,
} from "./utils"

export type FileStoragePickerColumnsProps = {
  onPick: (row: FileStorageRow) => void
  canPick?: (row: FileStorageRow) => boolean
  isSelected?: (row: FileStorageRow) => boolean
  multiSelect?: boolean
}

export function getFileStoragePickerColumns({
  onPick,
  canPick = isImageStorageRow,
  isSelected,
  multiSelect = false,
}: FileStoragePickerColumnsProps): ColumnDef<FileStorageRow>[] {
  return [
    {
      id: "preview",
      header: "Xem trước",
      enableSorting: false,
      enableColumnFilter: false,
      size: 80,
      meta: { className: "w-[180px] min-w-[180px] max-w-[180px]" },
      cell: ({ row }) => {
        const item = row.original
        const pickable = canPick(item)
        const selected = Boolean(isSelected?.(item))

        if (isImageStorageRow(item)) {
          return (
            <button
              type="button"
              disabled={!pickable}
              onClick={() => pickable && onPick(item)}
              className={[
                "flex size-full cursor-pointer items-center justify-center overflow-hidden rounded-md border bg-muted disabled:cursor-not-allowed disabled:opacity-50",
                selected
                  ? "ring-2 ring-primary ring-offset-1"
                  : "border-border",
              ].join(" ")}
            >
              <img
                src={storageThumbnailUrl(item)}
                alt={item.originalName}
                className="size-full object-cover"
                loading="lazy"
                decoding="async"
              />
            </button>
          )
        }

        if (isVideoStorageRow(item)) {
          return (
            <div className="relative flex size-full items-center justify-center overflow-hidden rounded-md border border-border bg-muted">
              <Film className="size-8 text-muted-foreground" />
              <span className="absolute inset-0 flex items-center justify-center bg-black/25">
                <Play className="size-6 fill-white text-white" />
              </span>
            </div>
          )
        }

        return <FileTypeIcon filename={item.originalName} />
      },
    },
    {
      accessorKey: "originalName",
      header: "Tên file",
      enableSorting: false,
      enableColumnFilter: false,
      cell: ({ getValue, row }) => (
        <div className="flex min-w-0 items-center gap-2">
          <FileTypeIconSm filename={row.original.originalName} />
          <a
            href={resolveStorageAssetUrl(row.original)}
            target="_blank"
            rel="noopener noreferrer"
            className="truncate text-sm font-medium underline-offset-2 hover:underline"
            title={row.original.originalName}
            onClick={(e) => e.stopPropagation()}
          >
            {String(getValue())}
          </a>
        </div>
      ),
    },
    {
      accessorKey: "mediaKind",
      header: "Loại media",
      enableSorting: false,
      enableColumnFilter: false,
      size: 110,
      meta: { className: "w-[110px] min-w-[110px] max-w-[110px]" },
      cell: ({ row }) => {
        const kind = row.original.mediaKind
        const label =
          kind === "image"
            ? "Ảnh"
            : kind === "video"
              ? "Video"
              : kind === "audio"
                ? "Âm thanh"
                : kind === "document"
                  ? "Tài liệu"
                  : kind === "archive"
                    ? "Nén"
                    : "Khác"

        return (
          <Badge variant="secondary" className="text-[10px]">
            {label}
          </Badge>
        )
      },
    },
    {
      accessorKey: "size",
      header: "Kích thước",
      enableSorting: false,
      enableColumnFilter: false,
      size: 120,
      meta: { className: "w-[120px] min-w-[120px] max-w-[120px]" },
      cell: ({ getValue }) => (
        <span className="text-sm text-muted-foreground tabular-nums">
          {formatFileSize(getValue() as number)}
        </span>
      ),
    },
    {
      accessorKey: "createdAt",
      header: "Ngày tải lên",
      enableSorting: false,
      enableColumnFilter: false,
      size: 180,
      meta: { className: "w-[180px] min-w-[180px] max-w-[180px]" },
      cell: ({ getValue }) => (
        <span className="text-xs text-muted-foreground tabular-nums">
          {formatAdminDateTime(getValue() as number | string)}
        </span>
      ),
    },
    defineDataTableActionsColumn<FileStorageRow>({
      cell: ({ row }) => {
        const item = row.original
        const pickable = canPick(item)
        const selected = Boolean(isSelected?.(item))
        return (
          <Button
            type="button"
            size="sm"
            variant={!pickable ? "outline" : selected ? "secondary" : "default"}
            disabled={!pickable}
            className="h-8 shrink-0 px-3 text-xs"
            onClick={() => onPick(item)}
          >
            {multiSelect ? (selected ? "Bỏ chọn" : "Chọn") : "Chọn"}
          </Button>
        )
      },
    }),
  ]
}

