import JSZip from "jszip"
import { DEFAULT_API_URL } from "@workspace/api-client"
import type { FileStorageRow } from "./types"

const STORAGE_UPLOADS_PREFIX = "/api/uploads/"

function getApiOrigin(): string {
  const configured = process.env.NEXT_PUBLIC_API_URL ?? DEFAULT_API_URL
  return configured.replace(/\/api\/?$/, "")
}

type StorageAssetRef = Pick<FileStorageRow, "url" | "relativePath">

/** URL tuyệt đối tới public uploads trên API (tránh request nhầm sang :3001). */
export function resolveStorageAssetUrl(row: StorageAssetRef): string {
  const raw = row.url?.trim()
  if (raw?.startsWith("http://") || raw?.startsWith("https://")) {
    return raw
  }
  const apiOrigin = getApiOrigin()
  const relative = row.relativePath.replace(/\\/g, "/").replace(/^\//, "")
  if (raw?.startsWith(STORAGE_UPLOADS_PREFIX)) {
    return `${apiOrigin}${raw}`
  }
  if (raw?.startsWith("api/uploads/")) {
    return `${apiOrigin}/${raw}`
  }
  return `${apiOrigin}${STORAGE_UPLOADS_PREFIX}${relative}`
}

/** Thumbnail nhỏ qua `/api/uploads/resized/*` — giảm băng thông trong bảng. */
export function storageThumbnailUrl(row: StorageAssetRef, width = 120): string {
  const base = resolveStorageAssetUrl(row)
  const marker = STORAGE_UPLOADS_PREFIX
  const idx = base.indexOf(marker)
  if (idx === -1 || base.includes(`${marker}resized/`)) {
    return base
  }
  const origin = base.slice(0, idx + marker.length)
  const path = base.slice(idx + marker.length)
  if (!path) return base
  return `${origin}resized/${path}?w=${width}&q=75`
}

async function fetchStorageBlob(row: FileStorageRow): Promise<Blob> {
  const response = await fetch(resolveStorageAssetUrl(row))
  if (!response.ok) {
    throw new Error(`Không tải được file (${response.status})`)
  }
  return response.blob()
}

function triggerBrowserDownload(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.rel = "noopener"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

/** Tải file từ URL public uploads về máy (giữ tên gốc). */
export async function downloadStorageFile(row: FileStorageRow): Promise<void> {
  const blob = await fetchStorageBlob(row)
  const filename =
    row.originalName?.trim() || row.fileName?.trim() || "download"
  triggerBrowserDownload(blob, filename)
}

/** Đường dẫn trong ZIP = relativePath trên kho (vd. images/2024/01/a.webp). */
export function storageZipEntryPath(
  row: FileStorageRow,
  used: Set<string>
): string {
  const relative =
    row.relativePath.replace(/\\/g, "/").trim() ||
    row.originalName?.trim() ||
    row.fileName?.trim() ||
    "file"
  return uniqueZipEntryPath(relative, used)
}

function uniqueZipEntryPath(base: string, used: Set<string>): string {
  if (!used.has(base)) {
    used.add(base)
    return base
  }
  const dot = base.lastIndexOf(".")
  const stem = dot > 0 ? base.slice(0, dot) : base
  const ext = dot > 0 ? base.slice(dot) : ""
  let index = 2
  let candidate = `${stem}-${index}${ext}`
  while (used.has(candidate)) {
    index += 1
    candidate = `${stem}-${index}${ext}`
  }
  used.add(candidate)
  return candidate
}

/** Nén và tải về danh sách file (một file .zip, giữ cấu trúc thư mục kho). */
export async function downloadStorageFilesAsZip(
  rows: FileStorageRow[],
  zipFilename: string,
  onProgress?: (done: number, total: number) => void
): Promise<{ success: number; fail: number }> {
  if (!rows.length) {
    throw new Error("Không có file để tải về")
  }

  const zip = new JSZip()
  const usedPaths = new Set<string>()
  let success = 0
  let fail = 0

  const concurrency = 6
  let cursor = 0

  async function worker(): Promise<void> {
    while (cursor < rows.length) {
      const index = cursor
      cursor += 1
      const row = rows[index]
      if (!row) continue
      try {
        const blob = await fetchStorageBlob(row)
        zip.file(storageZipEntryPath(row, usedPaths), blob)
        success += 1
      } catch {
        fail += 1
      }
      onProgress?.(index + 1, rows.length)
    }
  }

  await Promise.all(
    Array.from({ length: Math.min(concurrency, rows.length) }, () => worker())
  )

  if (success === 0) {
    throw new Error("Không tải được file nào")
  }

  const zipBlob = await zip.generateAsync({ type: "blob" })
  triggerBrowserDownload(zipBlob, zipFilename)
  return { success, fail }
}

/** Hiển thị ID người upload trong bảng file-storage. */
export function formatUploadOwnerLabel(uploadOwnerId?: string | null): string {
  const id = uploadOwnerId?.trim()
  if (!id) return "—"
  if (id.length <= 24) return id
  return `${id.slice(0, 10)}…${id.slice(-8)}`
}

export function formatUploadOwnerCell(row: {
  uploadOwnerId?: string | null
  uploadOwnerName?: string | null
}): { primary: string; title: string } {
  const id = row.uploadOwnerId?.trim()
  const name = row.uploadOwnerName?.trim()
  if (!id && !name) {
    return { primary: "—", title: "File cũ hoặc không có prefix ID" }
  }
  if (name) {
    return {
      primary: name,
      title: id ? `${name} (${id})` : name,
    }
  }
  return {
    primary: formatUploadOwnerLabel(id),
    title: id ?? "",
  }
}

export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export function isImageMime(mime: string): boolean {
  return mime.startsWith("image/")
}

export function isVideoMime(mime: string): boolean {
  return mime.startsWith("video/")
}

/** Ảnh / video có thể xem trước trong UI (kiểu Google Drive). */
export function isPreviewableStorageRow(
  row: Pick<FileStorageRow, "mediaKind" | "mimeType">
): boolean {
  if (row.mediaKind === "image" || row.mediaKind === "video") return true
  return isImageMime(row.mimeType) || isVideoMime(row.mimeType)
}

export function isImageStorageRow(
  row: Pick<FileStorageRow, "mediaKind" | "mimeType">
): boolean {
  return row.mediaKind === "image" || isImageMime(row.mimeType)
}

export function isVideoStorageRow(
  row: Pick<FileStorageRow, "mediaKind" | "mimeType">
): boolean {
  return row.mediaKind === "video" || isVideoMime(row.mimeType)
}

export type StorageFolderRef = { path: string; name: string; label?: string }

export type StorageFolderTreeNode = {
  path: string
  name: string
  slug?: string
  children: StorageFolderTreeNode[]
}

function folderDisplayName(
  folderByPath: Map<string, StorageFolderRef>,
  diskPath: string,
  slugSegment: string
): string {
  const folder = folderByPath.get(diskPath)
  return folder?.label?.trim() || folder?.name?.trim() || slugSegment
}

function normalizeFolderDiskPath(
  folderPath: string,
  realm: StorageRealmRef
): string {
  const normalized = folderPath.replace(/\\/g, "/").replace(/\/$/, "")
  const root = storageRealmRoot(realm)
  if (normalized === root || normalized.startsWith(`${root}/`)) {
    return normalized
  }
  if (
    realm === "images" &&
    !normalized.startsWith("files/") &&
    !normalized.startsWith("videos/") &&
    !normalized.startsWith("audio/") &&
    normalized !== "files" &&
    normalized !== "videos" &&
    normalized !== "audio"
  ) {
    return `${root}/${normalized}`
  }
  return normalized
}

/** Cây thư mục đích theo realm — bỏ nút gốc images/files/videos, path node = disk path. */
export function buildRealmFolderTree(
  folders: StorageFolderRef[],
  realm: StorageRealmRef
): StorageFolderTreeNode[] {
  const root = storageRealmRoot(realm)
  const diskPaths = [
    ...new Set(
      filterFoldersByRealm(folders, realm).map((folder) =>
        normalizeFolderDiskPath(folder.path, realm)
      )
    ),
  ]
    .filter((diskPath) => diskPath !== root)
    .sort((a, b) => a.localeCompare(b))

  const roots: StorageFolderTreeNode[] = []
  const nodeMap = new Map<string, StorageFolderTreeNode>()
  const folderByPath = new Map(
    folders.map((folder) => [folder.path.replace(/\\/g, "/"), folder])
  )

  for (const diskPath of diskPaths) {
    const parts = diskPath.split("/").filter(Boolean)
    const relParts = parts[0] === root ? parts.slice(1) : parts
    if (!relParts.length) continue

    let siblings = roots
    let accumulated = root
    for (const part of relParts) {
      accumulated = `${accumulated}/${part}`
      let node = nodeMap.get(accumulated)
      if (!node) {
        node = {
          path: accumulated,
          name: folderDisplayName(folderByPath, accumulated, part),
          slug: part,
          children: [],
        }
        nodeMap.set(accumulated, node)
        siblings.push(node)
      }
      siblings = node.children
    }
  }

  return roots
}

/** Xây cây thư mục từ danh sách path phẳng (images/admincp/…). */
export function buildStorageFolderTree(
  folders: StorageFolderRef[]
): StorageFolderTreeNode[] {
  const roots: StorageFolderTreeNode[] = []
  const nodeMap = new Map<string, StorageFolderTreeNode>()
  const folderByPath = new Map(
    folders.map((folder) => [folder.path.replace(/\\/g, "/"), folder])
  )

  const sorted = [...folders].sort((a, b) => a.path.localeCompare(b.path))
  for (const folder of sorted) {
    const parts = folder.path.replace(/\\/g, "/").split("/").filter(Boolean)
    let currentPath = ""
    let siblings = roots

    for (const part of parts) {
      currentPath = currentPath ? `${currentPath}/${part}` : part
      let node = nodeMap.get(currentPath)
      if (!node) {
        node = {
          path: currentPath,
          name: folderDisplayName(folderByPath, currentPath, part),
          slug: part,
          children: [],
        }
        nodeMap.set(currentPath, node)
        siblings.push(node)
      }
      siblings = node.children
    }
  }

  return roots
}

/** Lọc cây — giữ nhánh có node khớp từ khóa hoặc con khớp. */
export function filterStorageFolderTree(
  nodes: StorageFolderTreeNode[],
  query: string
): StorageFolderTreeNode[] {
  const q = query.trim().toLowerCase()
  if (!q) return nodes

  const visit = (node: StorageFolderTreeNode): StorageFolderTreeNode | null => {
    const selfMatch =
      node.path.toLowerCase().includes(q) || node.name.toLowerCase().includes(q)
    const children = node.children
      .map(visit)
      .filter((child): child is StorageFolderTreeNode => child !== null)
    if (selfMatch || children.length > 0) {
      return { ...node, children }
    }
    return null
  }

  return nodes
    .map(visit)
    .filter((node): node is StorageFolderTreeNode => node !== null)
}

/** Thu thập path các node có con — dùng auto-expand khi lọc. */
export function collectStorageFolderExpandablePaths(
  nodes: StorageFolderTreeNode[],
  out = new Set<string>()
): Set<string> {
  for (const node of nodes) {
    if (node.children.length > 0) {
      out.add(node.path)
      collectStorageFolderExpandablePaths(node.children, out)
    }
  }
  return out
}

/** Mở rộng các nhánh cha của path đã chọn. */
export function expandStorageFolderAncestors(
  folderPath: string,
  expanded: Set<string>
): void {
  const parts = folderPath.replace(/\\/g, "/").split("/").filter(Boolean)
  let current = ""
  for (let i = 0; i < parts.length - 1; i += 1) {
    current = current ? `${current}/${parts[i]}` : parts[i]
    expanded.add(current)
  }
}

type StorageRealmRef = "images" | "files" | "videos" | "audio"

export const REALM_STORAGE_LABELS: Record<StorageRealmRef, string> = {
  images: "Hình ảnh",
  files: "Tệp tin",
  videos: "Video",
  audio: "Âm thanh",
}

export const REALM_STORAGE_ROOT_PATH: Record<StorageRealmRef, string> = {
  images: "images",
  files: "files",
  videos: "videos",
  audio: "audio",
}

export function buildRealmVirtualRoots(realm: StorageRealmRef): Array<{
  value: string
  label: string
}> {
  return [
    {
      value: REALM_STORAGE_ROOT_PATH[realm],
      label: `Gốc — ${REALM_STORAGE_LABELS[realm]}`,
    },
  ]
}

function storageRealmRoot(realm: StorageRealmRef): string {
  if (realm === "files") return "files"
  if (realm === "videos") return "videos"
  if (realm === "audio") return "audio"
  return "images"
}

/** Gợi ý thư mục mặc định theo realm + tab folder đang xem. */
export function resolveDefaultFolderPath(
  folders: StorageFolderRef[],
  activeRealm: StorageRealmRef,
  activeFolderTab: string
): string {
  const root = storageRealmRoot(activeRealm)

  if (!folders.length) {
    if (!activeFolderTab) return root
    return activeRealm === "images"
      ? activeFolderTab
      : `${root}/${activeFolderTab}`
  }

  if (!activeFolderTab) {
    const underRoot = folders
      .filter((f) => f.path === root || f.path.startsWith(`${root}/`))
      .sort((a, b) => a.path.length - b.path.length)
    return underRoot[0]?.path ?? root
  }

  const candidates =
    activeRealm === "files"
      ? [`files/${activeFolderTab}`, "files", activeFolderTab]
      : activeRealm === "videos"
        ? [`videos/${activeFolderTab}`, "videos", activeFolderTab]
        : activeRealm === "audio"
          ? [`audio/${activeFolderTab}`, "audio", activeFolderTab]
          : [
              `images/${activeFolderTab}`,
              activeFolderTab,
              `images/${activeFolderTab}/`,
            ]

  for (const candidate of candidates) {
    const normalized = candidate.replace(/\/$/, "")
    const exact = folders.find((f) => f.path === normalized)
    if (exact) return exact.path
  }

  const prefix =
    activeRealm === "files"
      ? "files"
      : activeRealm === "videos"
        ? "videos"
        : activeRealm === "audio"
          ? "audio"
          : `images/${activeFolderTab}`
  const underTab = folders
    .filter((f) => f.path === prefix || f.path.startsWith(`${prefix}/`))
    .sort((a, b) => a.path.length - b.path.length)
  if (underTab.length > 0) return underTab[0].path

  return activeRealm === "images"
    ? activeFolderTab
    : `${root}/${activeFolderTab}`
}

export function normalizeParentFolderDiskPath(
  realm: StorageRealmRef,
  folderPath: string
): string {
  const fp = folderPath.trim().replace(/\\/g, "/").replace(/\/$/, "")
  if (!fp) return ""
  if (
    fp.startsWith("images/") ||
    fp.startsWith("files/") ||
    fp.startsWith("videos/") ||
    fp.startsWith("audio/")
  ) {
    return fp
  }
  if (realm === "images") {
    return fp === "images" ? "" : `images/${fp}`
  }
  if (realm === "files") return fp === "files" ? "" : `files/${fp}`
  if (realm === "videos") {
    return fp === "videos" ? "" : `videos/${fp}`
  }
  return fp === "audio" ? "" : `audio/${fp}`
}

/** Parent path + resourceType khi tạo folder tại path điều hướng hiện tại. */
export function resolveCreateFolderParent(
  realm: StorageRealmRef,
  parentFolderPath = ""
): {
  parentPath?: string
  resourceType: "images" | "files" | "videos" | "audio"
} {
  const parentDisk = normalizeParentFolderDiskPath(realm, parentFolderPath)
  if (!parentDisk) {
    if (realm === "images") {
      return { parentPath: "images", resourceType: "images" }
    }
    return { parentPath: undefined, resourceType: realm }
  }
  return {
    parentPath: parentDisk,
    resourceType: inferFolderResourceType(parentDisk),
  }
}

export function resolveStorageFolderDiskPath(
  realm: StorageRealmRef,
  folderPath: string
): string {
  const disk = normalizeParentFolderDiskPath(realm, folderPath)
  return disk || ""
}

export function filterFoldersByRealm(
  folders: StorageFolderRef[],
  realm: StorageRealmRef
): StorageFolderRef[] {
  const root = storageRealmRoot(realm)
  return folders.filter((folder) => {
    const path = folder.path.replace(/\\/g, "/")
    if (realm === "images") {
      return (
        path.startsWith("images/") ||
        path === "images" ||
        (!path.startsWith("files/") &&
          !path.startsWith("videos/") &&
          !path.startsWith("audio/") &&
          path !== "files" &&
          path !== "videos" &&
          path !== "audio")
      )
    }
    return path === root || path.startsWith(`${root}/`)
  })
}

function normalizeFolderSearchText(value: string): string {
  return value.trim().toLocaleLowerCase("vi")
}

/** Lọc folder theo tên / path (UTF-8) trong một realm. */
export function filterStorageFoldersByQuery(
  folders: StorageFolderRef[],
  query: string,
  realm: StorageRealmRef,
  limit = 40
): StorageFolderRef[] {
  const q = normalizeFolderSearchText(query)
  if (!q) return []

  const inRealm = filterFoldersByRealm(folders, realm)
  const matched = inRealm.filter((folder) => {
    const path = normalizeFolderSearchText(folder.path.replace(/\\/g, "/"))
    const name = normalizeFolderSearchText(folder.name)
    const label = normalizeFolderSearchText(folder.label ?? "")
    const leaf = normalizeFolderSearchText(
      folder.path.replace(/\\/g, "/").split("/").pop() ?? ""
    )
    return (
      path.includes(q) ||
      name.includes(q) ||
      label.includes(q) ||
      leaf.includes(q)
    )
  })

  matched.sort((a, b) => {
    const aPath = a.path.replace(/\\/g, "/")
    const bPath = b.path.replace(/\\/g, "/")
    const aLeaf = normalizeFolderSearchText(aPath.split("/").pop() ?? "")
    const bLeaf = normalizeFolderSearchText(bPath.split("/").pop() ?? "")
    const aExact = aLeaf === q ? 0 : 1
    const bExact = bLeaf === q ? 0 : 1
    if (aExact !== bExact) return aExact - bExact
    const aStarts = aLeaf.startsWith(q) ? 0 : 1
    const bStarts = bLeaf.startsWith(q) ? 0 : 1
    if (aStarts !== bStarts) return aStarts - bStarts
    return aPath.localeCompare(bPath, "vi")
  })

  return matched.slice(0, limit)
}

/** Gợi ý chuyển tab sau khi tạo folder mới. */
/** Phạm vi cấu trúc lại folder theo folder đang mở. */
export function resolveReorganizeScopePath(
  realm: StorageRealmRef,
  activeFolderPath: string
): string {
  const disk = normalizeParentFolderDiskPath(realm, activeFolderPath)
  return disk || storageRealmRoot(realm)
}

export function resolveFolderPathAfterCreate(
  folderPath: string,
  realm: StorageRealmRef
): string {
  const parts = folderPath.replace(/\\/g, "/").split("/").filter(Boolean)
  if (!parts.length) return ""

  if (realm === "images") {
    if (parts[0] === "images") return parts.slice(1).join("/")
    return parts.join("/")
  }
  if (realm === "files") {
    if (parts[0] === "files") return parts.slice(1).join("/") || "files"
    return parts.join("/")
  }
  if (parts[0] === "videos") {
    return parts.slice(1).join("/") || "videos"
  }
  if (parts[0] === "audio") {
    return parts.slice(1).join("/") || "audio"
  }
  return parts.join("/")
}

export function inferFolderResourceType(
  folderPath: string
): "images" | "files" | "videos" | "audio" {
  const normalized = folderPath.replace(/\\/g, "/").replace(/\/$/, "")
  if (normalized === "files" || normalized.startsWith("files/")) {
    return "files"
  }
  if (normalized === "videos" || normalized.startsWith("videos/")) {
    return "videos"
  }
  if (normalized === "audio" || normalized.startsWith("audio/")) {
    return "audio"
  }
  return "images"
}

export function formatStorageFolderOption(folder: StorageFolderRef): string {
  return folder.path
}

src/app/file-storage/_component/_hooks/u.content:
"use client"

import { useCallback, useRef, useState } from "react"
import { toast } from "@ui/components/sonner"
import {
  deleteUploadedFile,
  deleteUploadedFilesBulk,
  exportFileStorageArchive,
  fetchAllFileStorageRows,
  importFileStorageArchive,
} from "@/lib/admin-uploads"
import type { FileStorageImportConfirmState } from "../file-storage-import-confirm-dialogs"
import {
  buildAcceptAttribute,
  getRealmDefaultExtensions,
} from "../storage-upload-policy"
import type { FileStorageRow, StorageRealm } from "../types"
import { downloadStorageFile } from "../utils"

function triggerBrowserDownload(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.rel = "noopener"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

type UseFileStorageActionsOptions = {
  activeRealm: StorageRealm
  activeFolderPath: string
  includeDescendants: boolean
  uploadOwnerFilter?: string
  reload: () => Promise<void>
}

export function useFileStorageActions({
  activeRealm,
  activeFolderPath,
  includeDescendants,
  uploadOwnerFilter = "",
  reload,
}: UseFileStorageActionsOptions) {
  const importInputRef = useRef<HTMLInputElement>(null)
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [importing, setImporting] = useState(false)
  const [deletingPath, setDeletingPath] = useState<string | null>(null)
  const [downloadingPath, setDownloadingPath] = useState<string | null>(null)
  const [downloadingAll, setDownloadingAll] = useState(false)
  const [importConfirm, setImportConfirm] =
    useState<FileStorageImportConfirmState | null>(null)

  const handleDelete = useCallback(
    async (row: FileStorageRow) => {
      if (deletingPath) return
      setDeletingPath(row.relativePath)
      try {
        await deleteUploadedFile(row.relativePath)
        toast.success("Đã xóa file")
        await reload()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi xóa file")
        throw err
      } finally {
        setDeletingPath(null)
      }
    },
    [deletingPath, reload]
  )

  const handleDownload = useCallback(
    async (row: FileStorageRow) => {
      if (downloadingPath) return
      setDownloadingPath(row.relativePath)
      try {
        await downloadStorageFile(row)
        toast.success(`Đã tải về ${row.originalName}`)
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi tải file")
        throw err
      } finally {
        setDownloadingPath(null)
      }
    },
    [downloadingPath]
  )

  const handleDownloadAll = useCallback(async () => {
    if (downloadingAll || downloadingPath) return
    setDownloadingAll(true)
    const listToast = toast.loading(
      "Đang xuất toàn bộ kho lưu trữ trên server…"
    )
    try {
      const { blob, meta } = await exportFileStorageArchive()
      if (!blob.size) {
        toast.error("Không có file để tải về", { id: listToast })
        return
      }
      triggerBrowserDownload(blob, "kho-luu-tru.zip")
      if (meta.skipped > 0) {
        toast.success(
          `Đã xuất ${meta.fileCount} file (${meta.skipped} file bỏ qua)`,
          { id: listToast }
        )
      } else {
        toast.success(`Đã xuất toàn bộ ${meta.fileCount} file`, {
          id: listToast,
        })
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Lỗi tải về tất cả", {
        id: listToast,
      })
    } finally {
      setDownloadingAll(false)
    }
  }, [downloadingAll, downloadingPath])

  const handleBulkDownload = useCallback(
    async (selectedRows: FileStorageRow[]) => {
      if (!selectedRows.length) return
      let success = 0
      let fail = 0
      for (const row of selectedRows) {
        try {
          await downloadStorageFile(row)
          success++
        } catch {
          fail++
        }
      }
      if (success > 0) {
        toast.success(`Đã tải về ${success} file`)
      }
      if (fail > 0) {
        toast.error(`${fail} file tải về thất bại`)
      }
    },
    []
  )

  const runBulkDeletePaths = useCallback(
    async (paths: string[]) => {
      if (!paths.length) return
      const pending = toast.loading(`Đang xóa ${paths.length} file…`)
      try {
        const result = await deleteUploadedFilesBulk(paths)
        if (result.failed > 0) {
          const sample = result.errors
            .slice(0, 2)
            .map((entry) => entry.message)
            .join("; ")
          toast.warning(
            `Đã xóa ${result.deleted}/${paths.length} file (${result.failed} lỗi)${sample ? `: ${sample}` : ""}`,
            { id: pending }
          )
        } else {
          toast.success(`Đã xóa ${result.deleted} file`, { id: pending })
        }
        await reload()
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi xóa hàng loạt", {
          id: pending,
        })
        throw err
      }
    },
    [reload]
  )

  const handleBulkDelete = useCallback(
    async (selectedRows: FileStorageRow[]) => {
      const paths = selectedRows.map((r) => r.relativePath)
      await runBulkDeletePaths(paths)
    },
    [runBulkDeletePaths]
  )

  const handleDeleteAllInTab = useCallback(async () => {
    const listToast = toast.loading("Đang lấy danh sách file trong tab…")
    try {
      const allRows = await fetchAllFileStorageRows(
        activeRealm,
        activeFolderPath || undefined,
        {
          includeDescendants,
          uploadOwnerId: uploadOwnerFilter.trim() || undefined,
        }
      )
      if (!allRows.length) {
        toast.error("Không có file để xóa", { id: listToast })
        return
      }
      toast.dismiss(listToast)
      await runBulkDeletePaths(allRows.map((r) => r.relativePath))
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Lỗi xóa toàn tab", {
        id: listToast,
      })
      throw err
    }
  }, [
    activeFolderPath,
    activeRealm,
    includeDescendants,
    uploadOwnerFilter,
    runBulkDeletePaths,
  ])

  const fetchAllRowsInScope = useCallback(async () => {
    return fetchAllFileStorageRows(activeRealm, activeFolderPath || undefined, {
      includeDescendants,
      uploadOwnerId: uploadOwnerFilter.trim() || undefined,
    })
  }, [activeFolderPath, activeRealm, includeDescendants, uploadOwnerFilter])

  const clearImportConfirm = useCallback(() => {
    setImportConfirm(null)
    if (importInputRef.current) importInputRef.current.value = ""
  }, [])

  const runImportArchive = useCallback(
    async (file: File, overwrite: boolean) => {
      setImporting(true)
      const importToast = toast.loading("Đang khôi phục kho lưu trữ…")
      try {
        const result = await importFileStorageArchive(file, { overwrite })
        const total =
          result.totalEntries ??
          result.restored + result.skipped + result.failed
        const parts = [
          `Đã khôi phục ${result.restored}/${total} file trong ZIP`,
        ]
        if ((result.skippedDuplicates ?? 0) > 0) {
          parts.push(`bỏ qua ${result.skippedDuplicates} file trùng`)
        }
        if ((result.skippedUnsupportedExt ?? 0) > 0) {
          parts.push(`${result.skippedUnsupportedExt} định dạng không hỗ trợ`)
        }
        if (result.failed > 0) parts.push(`${result.failed} lỗi`)
        if ((result.listedTotal ?? 0) > 0) {
          parts.push(`${result.listedTotal} file trong kho`)
        }
        toast.success(parts.join(" · "), { id: importToast })
        if (result.failed > 0 && result.errors.length) {
          toast.error(result.errors.slice(0, 3).join("\n"))
        }
        setImportConfirm(null)
        await reload()
      } catch (err) {
        toast.error(
          err instanceof Error ? err.message : "Lỗi khôi phục kho lưu trữ",
          { id: importToast }
        )
      } finally {
        setImporting(false)
        if (importInputRef.current) importInputRef.current.value = ""
      }
    },
    [reload]
  )

  const handleImport = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!file.name.toLowerCase().endsWith(".zip")) {
      toast.error("Vui lòng chọn file ZIP backup (kho-luu-tru.zip)")
      if (importInputRef.current) importInputRef.current.value = ""
      return
    }

    const sizeMb = (file.size / (1024 * 1024)).toFixed(1)
    setImportConfirm({ file, sizeMb, step: "restore" })
  }, [])

  const handleImportConfirmRestore = useCallback(() => {
    setImportConfirm((current) =>
      current ? { ...current, step: "overwrite" } : null
    )
  }, [])

  const handleImportConfirmOverwrite = useCallback(() => {
    if (!importConfirm?.file) return
    void runImportArchive(importConfirm.file, true)
  }, [importConfirm, runImportArchive])

  const handleImportSkipOverwrite = useCallback(() => {
    if (!importConfirm?.file) {
      clearImportConfirm()
      return
    }
    void runImportArchive(importConfirm.file, false)
  }, [clearImportConfirm, importConfirm, runImportArchive])

  const openUploadPicker = useCallback(() => {
    setUploadDialogOpen(true)
  }, [])

  const openImportPicker = useCallback(() => {
    importInputRef.current?.click()
  }, [])

  const uploadAccept = buildAcceptAttribute(
    getRealmDefaultExtensions(activeRealm)
  )

  return {
    uploadDialogOpen,
    setUploadDialogOpen,
    setUploading,
    importInputRef,
    uploading,
    importing,
    deletingPath,
    downloadingPath,
    downloadingAll,
    uploadAccept,
    handleImport,
    importConfirm,
    clearImportConfirm,
    handleImportConfirmRestore,
    handleImportConfirmOverwrite,
    handleImportSkipOverwrite,
    handleDownload,
    handleDownloadAll,
    handleBulkDownload,
    handleDelete,
    handleBulkDelete,
    handleDeleteAllInTab,
    fetchAllRowsInScope,
    openUploadPicker,
    openImportPicker,
  }
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { toast } from "@ui/components/sonner"
import { fetchImages } from "@/lib/admin-uploads"
import type { FileStorageRow, StorageRealm, StorageTab } from "../types"

export function useFileStorageList(
  activeRealm: StorageRealm,
  activeFolderPath: string,
  page: number,
  pageSize: number,
  includeDescendants = false,
  uploadOwnerFilter = ""
) {
  const [rows, setRows] = useState<FileStorageRow[]>([])
  const [realms, setRealms] = useState<StorageTab[]>([])
  const [childFolders, setChildFolders] = useState<StorageTab[]>([])
  const [breadcrumb, setBreadcrumb] = useState<
    Array<{ id: string; label: string }>
  >([])
  const [loading, setLoading] = useState(true)
  const [isFetching, setIsFetching] = useState(false)
  const [total, setTotal] = useState(0)

  const reload = useCallback(async () => {
    setIsFetching(true)
    try {
      const data = await fetchImages(page, pageSize, {
        realm: activeRealm,
        folderPath: activeFolderPath || undefined,
        includeDescendants,
        uploadOwnerId: uploadOwnerFilter.trim() || undefined,
      })
      setRows(data.data)
      setRealms(data.realms ?? [])
      setChildFolders(data.childFolders ?? data.tabs ?? [])
      setBreadcrumb(data.breadcrumb ?? [])
      setTotal(data.pagination.total)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Lỗi tải danh sách")
    } finally {
      setLoading(false)
      setIsFetching(false)
    }
  }, [
    activeFolderPath,
    activeRealm,
    includeDescendants,
    page,
    pageSize,
    uploadOwnerFilter,
  ])

  useEffect(() => {
    void reload()
  }, [reload])

  return {
    rows,
    realms,
    childFolders,
    breadcrumb,
    loading,
    isFetching,
    total,
    reload,
  }
}

"use client"

import { useEffect, useState } from "react"
import { fetchStorageFolders, type FolderItem } from "@/lib/admin-uploads"

export function useStorageFolders(refreshKey = 0) {
  const [folders, setFolders] = useState<FolderItem[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    void fetchStorageFolders()
      .then((data) => {
        if (!cancelled) setFolders(data)
      })
      .catch(() => {
        if (!cancelled) setFolders([])
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })

    return () => {
      cancelled = true
    }
  }, [refreshKey])

  return { folders, loading }
}

