    >
      <body
        className="flex min-h-full flex-col bg-background font-sans text-foreground"
        suppressHydrationWarning
      >
        <AdminRootProviders>
          <QueryProvider>
            <AuthProvider>
              <BackendAdminLayoutProvider>
                {children}
              </BackendAdminLayoutProvider>
            </AuthProvider>
          </QueryProvider>
        </AdminRootProviders>
      </body>
    </html>
  )
}

