src/app/my-students/page.tsx.content:
"use client"

import { useCallback, useMemo, useState } from "react"
import type { ColumnFiltersState } from "@tanstack/react-table"
import { useQuery, useQueryClient } from "@tanstack/react-query"
import { GraduationCap, Plus, BarChart3 } from "lucide-react"
import { Button } from "@ui/components/button"
import {
  AdminListPageHeader,
  AdminPageGuard,
  AdminPageHeaderPrimaryButton,
  AdminPageSection,
} from "@ui/components/admin"
import { useAuth } from "@/providers/auth-provider"
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client"
import { api } from "@/lib/api"
import { queryKeys } from "@/hooks/queries"
import {
  AddStudentDialog,
  MyStudentsTable,
  StudentGradeDialog,
  DEMO_GRADE_STUDENT,
  getMyStudentsColumns,
  type GradeDialogTarget,
  type MyStudentRow,
} from "./_component"
import {
  myStudentsPollInterval,
  useMyStudentsSocket,
} from "./_component/use-my-students-socket"

import { useAdminMutation } from "@/hooks/use-admin-mutation"
export default function MyStudentsPage() {
  const { user } = useAuth()
  const canCreate = user
    ? canUserAccess(user, PERMISSION_CODES.STUDENTS_CREATE) ||
      canUserAccess(user, PERMISSION_CODES.STUDENTS_VIEW_OWN)
    : false
  const canDelete = user
    ? canUserAccess(user, PERMISSION_CODES.STUDENTS_VIEW_OWN) ||
      canUserAccess(user, PERMISSION_CODES.STUDENTS_DELETE) ||
      canUserAccess(user, PERMISSION_CODES.STUDENTS_MANAGE)
    : false

  const queryClient = useQueryClient()
  const [addOpen, setAddOpen] = useState(false)
  const [gradeTarget, setGradeTarget] = useState<GradeDialogTarget | null>(null)
  const [globalFilter, setGlobalFilter] = useState("")
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])

  const handleStudentReviewed = useCallback(() => {
    void queryClient.invalidateQueries({ queryKey: queryKeys.myStudents() })
  }, [queryClient])

  const { connected: socketConnected } = useMyStudentsSocket(
    true,
    handleStudentReviewed
  )

  const { data: students, isLoading } = useQuery<MyStudentRow[]>({
    queryKey: queryKeys.myStudents(),
    queryFn: async () => {
      const result = await api.myStudents.list()
      return result as unknown as MyStudentRow[]
    },

    refetchInterval: (query) => {
      const rows = query.state.data as MyStudentRow[] | undefined
      const hasPending = (rows ?? []).some((row) => row.status === "pending")
      return myStudentsPollInterval(socketConnected, hasPending)
    },
  })

  const deleteMutation = useAdminMutation({
    toast: {
      loading: "Đang xóa liên kết…",
      success: "Đã xóa liên kết sinh viên.",
      error: (err) =>
        err instanceof Error
          ? err.message
          : "Không thể xóa liên kết sinh viên.",
    },
    mutationFn: async (id: string) => {
      await api.myStudents.remove(id)
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: queryKeys.myStudents() })
    },
  })

  const handleDelete = useCallback(
    async (row: MyStudentRow) => {
      await deleteMutation.mutateAsync(row.id)
    },
    [deleteMutation]
  )

  const handleViewGrades = useCallback((row: MyStudentRow) => {
    setGradeTarget({
      studentCode: row.studentCode,
      studentName: row.studentName,
    })
  }, [])

  const columns = useMemo(
    () =>
      getMyStudentsColumns({
        onViewGrades: handleViewGrades,
        onDelete: handleDelete,
        canDelete,
        deleteBusy: deleteMutation.isPending,
      }),
    [canDelete, deleteMutation.isPending, handleDelete, handleViewGrades]
  )

  const clearFilters = useCallback(() => {
    setColumnFilters([])
    setGlobalFilter("")
  }, [])

  const displayName = user?.name?.trim() || user?.email || "Phụ huynh"
  const isDev = process.env.NODE_ENV === "development"

  const devToolbarExtra = isDev ? (
    <Button
      type="button"
      variant="outline"
      size="sm"
      className="h-8 gap-1.5 border-dashed border-yellow-400 text-yellow-800 dark:text-yellow-400"
      onClick={() =>
        setGradeTarget({
          studentCode: DEMO_GRADE_STUDENT.code,
          studentName: DEMO_GRADE_STUDENT.name,
        })
      }
    >
      <BarChart3 className="size-3.5" aria-hidden />
      Demo bảng điểm
    </Button>
  ) : undefined

  return (
    <AdminPageGuard permission={PERMISSION_CODES.STUDENTS_VIEW_OWN}>
      <AdminPageSection>
        <AdminListPageHeader
          title="Quản lý sinh viên"
          subtitle={
            <>
              Xin chào,{" "}
              <span className="font-semibold text-foreground">
                {displayName}
              </span>
              . Quản lý liên kết sinh viên và theo dõi kết quả học tập.
            </>
          }
          icon={GraduationCap}
          actions={
            canCreate ? (
              <AdminPageHeaderPrimaryButton onClick={() => setAddOpen(true)}>
                <Plus className="size-4" />
                Thêm sinh viên
              </AdminPageHeaderPrimaryButton>
            ) : undefined
          }
        />

        <MyStudentsTable
          data={students ?? []}
          columns={columns}
          isLoading={isLoading}
          columnFilters={columnFilters}
          onColumnFiltersChange={setColumnFilters}
          globalFilter={globalFilter}
          onGlobalFilterChange={setGlobalFilter}
          onClearFilters={clearFilters}
          filterToolbarExtra={devToolbarExtra}
        />

        <AddStudentDialog
          open={addOpen}
          onClose={() => setAddOpen(false)}
          onSuccess={() =>
            queryClient.invalidateQueries({ queryKey: queryKeys.myStudents() })
          }
        />

        <StudentGradeDialog
          target={gradeTarget}
          onClose={() => setGradeTarget(null)}
        />
      </AdminPageSection>
    </AdminPageGuard>
  )
}

src/app/my-students/_component/add-stude.content:
"use client"

import { useState } from "react"
import { useAdminMutation } from "@/hooks/use-admin-mutation"
import { Plus, AlertCircle } from "lucide-react"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog"
import { api } from "@/lib/api"

export function AddStudentDialog({
  open,
  onClose,
  onSuccess,
}: {
  open: boolean
  onClose: () => void
  onSuccess: () => void
}) {
  const [studentCode, setStudentCode] = useState("")
  const [studentName, setStudentName] = useState("")
  const [note, setNote] = useState("")
  const [error, setError] = useState("")

  const mutation = useAdminMutation({
    mutationKey: ["my-students", "create"],
    toast: {
      loading: "Đang gửi yêu cầu liên kết…",
      success: "Đã gửi yêu cầu liên kết sinh viên",
      error: (err) =>
        err instanceof Error ? err.message : "Không gửi được yêu cầu",
    },
    mutationFn: async () => {
      await api.myStudents.add({ studentCode, studentName, note })
    },
    onSuccess: () => {
      setStudentCode("")
      setStudentName("")
      setNote("")
      setError("")
      onSuccess()
      onClose()
    },
    onError: (err) => {
      setError(err instanceof Error ? err.message : "Lỗi hệ thống")
    },
  })

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Plus className="size-5" />
            Thêm liên kết học sinh
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="studentCode">
              Mã sinh viên <span className="text-rose-500">*</span>
            </Label>
            <Input
              id="studentCode"
              value={studentCode}
              onChange={(e) => setStudentCode(e.target.value)}
              placeholder="VD: SV2024001"
              autoFocus
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="studentName">Họ tên con</Label>
            <Input
              id="studentName"
              value={studentName}
              onChange={(e) => setStudentName(e.target.value)}
              placeholder="Nhập họ tên để dễ nhận diện"
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="note">Ghi chú</Label>
            <Input
              id="note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Thông tin thêm cho quản trị viên"
            />
          </div>
          {error && (
            <p className="flex items-center gap-1.5 text-sm text-rose-600">
              <AlertCircle className="size-4" />
              {error}
            </p>
          )}
          <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-700 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-400">
            Yêu cầu sẽ chờ xác nhận từ quản trị viên trước khi hiển thị bảng
            điểm.
          </p>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={onClose}
            disabled={mutation.isPending}
          >
            Hủy
          </Button>
          <Button
            onClick={() => mutation.mutate()}
            disabled={!studentCode.trim() || mutation.isPending}
          >
            {mutation.isPending ? "Đang gửi…" : "Gửi yêu cầu"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

src/app/my-students/_component/columns.t.content:
"use client"

import type { ColumnDef, FilterFnOption } from "@tanstack/react-table"
import {
  UsageStatusBadge,
  type UsageStatusTone,
} from "@ui/components/usage-status-badge"
import {
  BarChart3,
  CheckCircle2,
  Clock,
  GraduationCap,
  Settings2,
  Trash2,
  XCircle,
} from "lucide-react"
import {
  DataTableRowActionsMenu,
  defineDataTableActionsColumn,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import type { MyStudentRow } from "./types"
import { defineRelationExportColumns } from "@ui/components/data-table"
import {
  adminDateRangeFilterFn,
  defineAdminCreatedAtColumn,
} from "@/lib/admin-table-columns"
import { formatAdminDateTime } from "@/lib/format-admin-datetime"

function recordLabel(row: MyStudentRow): string {
  return row.studentName?.trim() || row.studentCode
}

export interface MyStudentsColumnsProps {
  onViewGrades: (row: MyStudentRow) => void
  onDelete: (row: MyStudentRow) => void | Promise<void>
  canDelete: boolean
  deleteBusy?: boolean
}

export function getMyStudentsColumns(
  props: MyStudentsColumnsProps
): ColumnDef<MyStudentRow>[] {
  const { onViewGrades, onDelete, canDelete, deleteBusy } = props

  return [
    {
      id: "student",
      header: "Sinh viên",
      accessorFn: (row) =>
        [row.studentCode, row.studentName].filter(Boolean).join(" "),
      enableColumnFilter: true,
      meta: {
        filterLabel: "Sinh viên",
        filterPlaceholder: "Mã hoặc họ tên…",
      },
      enableSorting: true,
      sortingFn: (a, b) => {
        const la = recordLabel(a.original)
        const lb = recordLabel(b.original)
        return la.localeCompare(lb, "vi")
      },
      cell: ({ row }) => (
        <div className="flex items-center gap-2.5">
          <div className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
            <GraduationCap className="size-4" aria-hidden />
          </div>
          <div className="min-w-0">
            {row.original.studentName && (
              <p className="truncate font-medium">{row.original.studentName}</p>
            )}
            <p className="font-mono text-xs text-muted-foreground">
              {row.original.studentCode}
            </p>
          </div>
        </div>
      ),
    },
    {
      accessorKey: "note",
      header: "Ghi chú",
      enableColumnFilter: true,
      cell: ({ getValue }) => {
        const v = getValue() as string | null
        return v ? (
          <span className="text-xs text-muted-foreground">{v}</span>
        ) : (
          <span className="text-xs italic opacity-40">—</span>
        )
      },
    },
    defineAdminCreatedAtColumn<MyStudentRow>({ header: "Ngày gửi" }),
    {
      accessorKey: "status",
      header: "Trạng thái",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.getValue(columnId)) === String(filterValue)
      },
      enableSorting: false,
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "pending", label: "Chờ duyệt" },
          { value: "approved", label: "Đã duyệt" },
          { value: "rejected", label: "Từ chối" },
        ],
      },
      cell: ({ getValue }) => {
        const s = getValue() as MyStudentRow["status"]
        const STATUS_CONFIG: Record<
          MyStudentRow["status"],
          { label: string; icon: typeof Clock; tone: UsageStatusTone }
        > = {
          pending: { label: "Chờ duyệt", icon: Clock, tone: "warning" },
          approved: { label: "Đã duyệt", icon: CheckCircle2, tone: "success" },
          rejected: { label: "Từ chối", icon: XCircle, tone: "danger" },
        }
        const cfg = STATUS_CONFIG[s]
        const StatusIcon = cfg.icon
        return (
          <UsageStatusBadge tone={cfg.tone} className="gap-1 text-[10px]">
            <StatusIcon className="size-3 shrink-0" aria-hidden />
            {cfg.label}
          </UsageStatusBadge>
        )
      },
    },
    {
      accessorKey: "reviewedAt",
      header: "Duyệt lúc",
      enableColumnFilter: true,
      filterFn: adminDateRangeFilterFn as FilterFnOption<MyStudentRow>,
      meta: {
        defaultHidden: true,
        filterVariant: "date-range",
        filterPlaceholder: "Chọn khoảng ngày",
      },
      cell: ({ getValue }) => {
        const v = getValue() as string | null
        return (
          <span className="text-xs text-muted-foreground tabular-nums">
            {formatAdminDateTime(v)}
          </span>
        )
      },
    },
    ...defineRelationExportColumns<MyStudentRow>(
      [{ id: "parentId", header: "ID phụ huynh", getValue: (r) => r.parentId }],
      { enableColumnFilter: false }
    ),
    defineDataTableActionsColumn<MyStudentRow>({
      cell: ({ row }) => {
        const data = row.original
        const label = recordLabel(data)
        const actions: DataTableRowActionItem[] = []

        if (data.status === "approved") {
          actions.push({
            key: "grades",
            label: "Xem kết quả học tập",
            hint: "Bảng điểm chi tiết, TB năm học và học kỳ",
            onClick: () => onViewGrades(data),
            icon: <BarChart3 />,
            group: "primary",
          })
        }

        if (canDelete) {
          const approved = data.status === "approved"
          actions.push({
            key: "unlink",
            label: approved ? "Gỡ liên kết" : "Xóa yêu cầu",
            hint: approved
              ? "Ngừng theo dõi bảng điểm sinh viên này"
              : "Xóa yêu cầu liên kết chưa hoặc đã bị từ chối",
            onClick: () => onDelete(data),
            icon: <Trash2 />,
            group: "danger",
            menuVariant: "destructive",
            confirm: approved
              ? {
                  title: `Gỡ liên kết ${label}?`,
                  description:
                    "Bạn sẽ không còn xem được bảng điểm của sinh viên này.",
                  confirmLabel: "Gỡ liên kết",
                  destructive: true,
                }
              : {
                  title: `Xóa yêu cầu ${label}?`,
                  description: "Thao tác không thể hoàn tác.",
                  confirmLabel: "Xóa",
                  destructive: true,
                },
          })
        }

        return (
          <DataTableRowActionsMenu
            actions={actions}
            busy={deleteBusy}
            groups={{
              primary: { label: "Theo dõi", icon: Settings2 },
              danger: { label: "Liên kết", sublabel: true },
            }}
          />
        )
      },
    }),
  ]
}

export function getMyStudentGlobalFilterText(row: MyStudentRow): string {
