"use client"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@ui/components/select"
import { StoreOrderStatusBadge } from "@ui/components/product"
import type { OrderStatus } from "@workspace/api-client"
import { ORDER_STATUS_LABELS, ORDER_STATUSES } from "./types"

export type OrderStatusCellProps = {
  status: OrderStatus
  canUpdate: boolean
  busy?: boolean
  onChange: (status: OrderStatus) => void | Promise<void>
}

export function OrderStatusCell({
  status,
  canUpdate,
  busy,
  onChange,
}: OrderStatusCellProps) {
  if (!canUpdate) {
    return <StoreOrderStatusBadge status={status} />
  }

  return (
    <Select
      value={status}
      onValueChange={(v) => void onChange(v as OrderStatus)}
