"use client"

import { useCallback, useEffect, useMemo } from "react"
import { useParams } from "next/navigation"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { useQueryClient } from "@tanstack/react-query"
import { toast } from "@ui/components/sonner"
import {
  AdminPageGuard,
  AdminPageSection,
  AdminPageLoading,
} from "@ui/components/admin"
import { api } from "@/lib/api"
import {
  PostFormShell,
  usePostForm,
  buildCategoryOptionTree,
  normalizeContentForEditor,
  toLocalInputValue,
} from "../../_component"
import {
  usePostDetailQuery,
  useCategoriesQuery,
  useTagsQuery,
} from "../../_component/_query"
import type { PostFormValues } from "../../_component"

import { useAdminMutation } from "@/hooks/use-admin-mutation"
function EditPostPageInner() {
  const crudNav = useAdminCrudNavigation("/posts")
  const params = useParams()
  const postId = params.id as string
  const queryClient = useQueryClient()
  const form = usePostForm()

  const {
    data: post,
    isLoading,
    error,
    refetch,
  } = usePostDetailQuery(api, postId)
  const categoriesQuery = useCategoriesQuery(api)
  const tagsQuery = useTagsQuery(api)

  const categoryTreeOptions = useMemo(
    () => buildCategoryOptionTree(categoriesQuery.data ?? []),
    [categoriesQuery.data]
  )

  useEffect(() => {
    if (error) {
      toast.error("Không tải được bài viết")
      crudNav.list()
    }
  }, [error, crudNav])

  useEffect(() => {
    if (!post) return
    form.reset({
      id: post.id,
      title: post.title,
      slug: post.slug,
      excerpt: post.excerpt ?? "",
      image: post.image ?? "",
      content: normalizeContentForEditor(post.content),
      published: post.published,
      publishedAt: toLocalInputValue(post.publishedAt ?? ""),
      categoryIds: post.categories.map((item) => item.id),
      tagIds: post.tags.map((item) => item.id),
    })
  }, [post, form])

  const updateMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: (_data, variables) =>
        `Đã cập nhật bài viết "${(variables.title as string)?.trim()}"`,
      error: (err) =>
        err instanceof Error ? err.message : "Không thể cập nhật bài viết",
    },
    mutationFn: async (input: Record<string, unknown>) =>
      api.posts.update(postId, input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["media", "posts"] })
      crudNav.view(String(postId))
    },
  })

  const handleSubmit = useCallback(
    async (values: PostFormValues) => {
      const payload = {
        title: values.title.trim(),
        slug:
          values.slug.trim() ||
          values.title.trim().toLowerCase().replace(/\s+/g, "-"),
        excerpt: values.excerpt.trim() || null,
        image: values.image.trim() || null,
        content: values.content,
        published: values.published,
        publishedAt: values.publishedAt || null,
        categoryIds: values.categoryIds,
        tagIds: values.tagIds,
      }
      await updateMutation.mutateAsync(payload)
    },
    [updateMutation]
  )

  if (isLoading) {
    return <AdminPageLoading variant="form" />
  }

  if (!post) return null

  return (
    <AdminPageSection>
      <PostFormShell
        form={form}
        onSubmit={handleSubmit}
        submitting={updateMutation.isPending}
        editingId={postId}
        categoryTreeOptions={categoryTreeOptions}
        tagsOptions={tagsQuery.data ?? []}
        onBack={() => crudNav.view(String(postId))}
        onReset={async () => {
          await refetch()
        }}
      />
    </AdminPageSection>
  )
}

export default function EditPostPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <EditPostPageInner />
    </AdminPageGuard>
  )
}

src/app/posts/[id]/page.tsx.content:
"use client"

import { useEffect } from "react"
import dynamic from "next/dynamic"
import { useParams } from "next/navigation"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { toast } from "@ui/components/sonner"
import {
  Calendar,
  Clock,
  User,
  ImageIcon,
  FileText,
  Link,
  Tags,
  Globe,
} from "lucide-react"
import { Badge } from "@ui/components/badge"
import {
  FieldSet,
  FieldSetContent,
  FieldSectionBadge,
  FieldSectionField,
  FieldSectionLegend,
} from "@ui/components/field"
import { useAuth } from "@/providers/auth-provider"
import {
  AdminPageGuard,
  AdminPageSection,
  AdminPageLoading,
  AdminDetailPageHeader,
  AdminDetailLayout,
  AdminDetailMain,
  AdminDetailSidebar,
} from "@ui/components/admin"
import { PERMISSION_CODES, canUserAccess } from "@workspace/api-client"
import { api } from "@/lib/api"
import { normalizeContentForEditor, formatDateTime } from "../_component"
import { usePostDetailQuery } from "../_component/_query"

const LexicalEditor = dynamic(
  () =>
    import("@thangph2146/lexical-editor").then((mod) => ({
      default: mod.LexicalEditor,
    })),
  { ssr: false }
)

function PostDetailInner() {
  const crudNav = useAdminCrudNavigation("/posts")
  const params = useParams()
  const postId = params.id as string
  const { user } = useAuth()
  const canUpdate = user
    ? canUserAccess(user, PERMISSION_CODES.POSTS_UPDATE)
    : false

  const { data: post, isLoading, error } = usePostDetailQuery(api, postId)

  useEffect(() => {
    if (error) {
      toast.error("Không tải được bài viết")
      crudNav.list()
    }
  }, [error, crudNav])

  if (isLoading) {
    return <AdminPageLoading />
  }

  if (!post) return null

  const content = normalizeContentForEditor(post.content)
  const previewPath = post.slug ? `/bai-viet/${post.slug}` : "—"

  return (
    <AdminPageSection>
      <AdminDetailPageHeader
        title="Chi tiết bài viết"
        subtitle="Quản lý bài viết và nội dung xuất bản."
        variant="module"
        onBack={() => crudNav.list()}
        onEdit={canUpdate ? () => crudNav.edit(String(postId)) : undefined}
      />

      <AdminDetailLayout className="my-6">
        <AdminDetailMain>
          <FieldSet variant="section">
            <FieldSectionLegend icon={FileText} title="Nội dung chi tiết" />
            <FieldSetContent variant="section" className="pt-0">
              {content ? (
                <LexicalEditor
                  value={content}
                  readOnly
                  className="mx-auto max-w-4xl"
                />
              ) : (
                <p className="text-sm text-muted-foreground italic">
                  Bài viết chưa có nội dung
                </p>
              )}
            </FieldSetContent>
          </FieldSet>
        </AdminDetailMain>

        <AdminDetailSidebar className="sticky top-2 max-h-[calc(100vh-80px)] overflow-y-auto">
          <FieldSet variant="section">
            <FieldSectionLegend icon={ImageIcon} title="Hình ảnh đại diện" />
            <FieldSetContent variant="section" className="pt-0">
              {post.image ? (
                <div className="overflow-hidden rounded-lg border border-border/70">
                  <img
                    src={post.image}
                    alt={post.title}
                    className="aspect-[16/10] w-full object-cover"
                  />
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Chưa có ảnh đại diện.
                </p>
              )}
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={FileText}
              title="Thông tin cơ bản"
              description="Tiêu đề, slug và mô tả ngắn."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <FieldSectionField label="Tiêu đề" icon={FileText}>
                <p className="whitespace-pre-wrap">{post.title}</p>
              </FieldSectionField>
              <FieldSectionField label="Slug" icon={Link}>
                <p className="text-muted-foreground">{post.slug || "—"}</p>
              </FieldSectionField>
              <FieldSectionField label="Đường dẫn công khai" icon={Globe}>
                <p className="font-mono text-xs break-all text-muted-foreground">
                  {previewPath}
                </p>
              </FieldSectionField>
              {post.excerpt ? (
                <FieldSectionField label="Mô tả ngắn">
                  <p className="whitespace-pre-wrap text-muted-foreground">
                    {post.excerpt}
                  </p>
                </FieldSectionField>
              ) : null}
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={Calendar}
              title="Xuất bản"
              description="Trạng thái hiển thị và thời điểm phát hành."
            />
            <FieldSetContent variant="section" className="space-y-3 pt-0">
              <FieldSectionField label="Trạng thái">
                {post.published ? (
                  <Badge>Đã xuất bản</Badge>
                ) : (
                  <Badge variant="outline">Bản nháp</Badge>
                )}
              </FieldSectionField>
              {post.publishedAt ? (
                <FieldSectionField
                  label="Ngày xuất bản"
                  icon={Calendar}
                  valueClassName="tabular-nums font-medium"
                >
                  {formatDateTime(post.publishedAt)}
                </FieldSectionField>
              ) : null}
              <FieldSectionField label="Tác giả" icon={User}>
                {post.author.name ?? post.author.email}
              </FieldSectionField>
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={Tags}
              title="Phân loại"
              badge={
                <FieldSectionBadge>
                  {post.categories.length + post.tags.length}
                </FieldSectionBadge>
              }
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <FieldSectionField label="Danh mục" icon={Tags}>
                {post.categories.length > 0 ? (
                  <div className="flex flex-wrap gap-1.5">
                    {post.categories.map((cat) => (
                      <Badge
                        key={cat.id}
                        variant="secondary"
                        className="text-xs"
                      >
                        {cat.name}
                      </Badge>
                    ))}
                  </div>
                ) : (
                  <p className="text-muted-foreground italic">Chưa phân loại</p>
                )}
              </FieldSectionField>
              <FieldSectionField label="Thẻ">
                {post.tags.length > 0 ? (
                  <div className="flex flex-wrap gap-1.5">
                    {post.tags.map((tag) => (
                      <Badge key={tag.id} variant="outline" className="text-xs">
                        {tag.name}
                      </Badge>
                    ))}
                  </div>
                ) : (
                  <p className="text-muted-foreground italic">Chưa có thẻ</p>
                )}
              </FieldSectionField>
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend
              icon={Clock}
              title="Thời gian"
              description="Mốc tạo và cập nhật bài viết."
            />
            <FieldSetContent variant="section" className="space-y-3 pt-0">
              <FieldSectionField
                label="Ngày tạo"
                icon={Calendar}
                valueClassName="font-medium"
              >
                {formatDateTime(post.createdAt)}
              </FieldSectionField>
              <FieldSectionField
                label="Cập nhật lần cuối"
                icon={Clock}
                valueClassName="font-medium"
              >
                {formatDateTime(post.updatedAt)}
              </FieldSectionField>
            </FieldSetContent>
          </FieldSet>
        </AdminDetailSidebar>
      </AdminDetailLayout>
    </AdminPageSection>
  )
}

export default function PostDetailPage() {
  return (
    <AdminPageGuard permission={PERMISSION_CODES.POSTS_VIEW}>
      <PostDetailInner />
    </AdminPageGuard>
  )
}

src/app/posts/_component/columns.tsx.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"

import { UsageStatusFromValue } from "@ui/components/usage-status-badge"

import {
  defineAdminCrudActionsColumn,
  defineAdminTrashActionsColumn,
} from "@ui/components/admin"

import { defineRelationExportColumns } from "@ui/components/data-table"

import type { AdminCrudRowHandlers } from "@/lib/admin-row-action-handlers"

import {
  type AdminTableView,
  buildAdminTableColumns,
  defineAdminCreatedAtColumn,
  defineAdminUpdatedAtColumn,
} from "@/lib/admin-table-columns"

import type { PostListRow, TaxonomyOption, CategoryTreeOption } from "./types"

import { SummaryBadges } from "./summary-badges"

export function getPostColumns({
  view = "list",

  navigateToEdit,

  navigateToView,

  rowActions,

  categoryTreeOptions,

  tagsOptions,

  canUpdate,

  canDelete,

  canRestore,
}: {
  view?: AdminTableView

  navigateToEdit: (id: string) => void

  navigateToView: (id: string) => void

  rowActions: AdminCrudRowHandlers<PostListRow>

  categoryTreeOptions: CategoryTreeOption[]

  tagsOptions: TaxonomyOption[]

  canUpdate: boolean

  canDelete: boolean

  canRestore?: boolean
}): ColumnDef<PostListRow>[] {
  const dataColumns: ColumnDef<PostListRow>[] = [
    {
      accessorKey: "title",

      header: "Tiêu đề",

      enableColumnFilter: true,
      filterFn: () => true,

      cell: ({ row }) => (
        <div className="space-y-1">
          <p className="font-medium">{row.original.title}</p>

          <p className="text-xs text-muted-foreground">{row.original.slug}</p>
        </div>
      ),
    },

    {
      accessorKey: "categories",

      id: "categoryId",

      header: "Danh mục",

      meta: {
        filterVariant: "tree-multi-select",

        treeOptions: categoryTreeOptions.map((c) => ({
          value: c.id,

          label: c.name,

          children: c.subRows?.map((s) => ({
            value: s.id,

            label: s.name,

            children: s.subRows?.map((ss) => ({
              value: ss.id,
              label: ss.name,
            })),
          })),
        })),
      },

      cell: ({ row }) => <SummaryBadges items={row.original.categories} />,
    },

    {
      accessorKey: "tags",

      id: "tagId",

      header: "Thẻ",

      enableColumnFilter: true,

      enableSorting: false,

      filterFn: () => true,

      meta: {
        filterVariant: "select",

        selectOptions: tagsOptions.map((t) => ({ value: t.id, label: t.name })),
      },

      cell: ({ row }) => <SummaryBadges items={row.original.tags} />,
    },

    {
      id: "authorName",

      header: "Tác giả",

      accessorFn: (row) => row.author?.name?.trim() || row.author?.email || "",

      meta: { filterPlaceholder: "Lọc tác giả…" },

      cell: ({ row }) => {
        const author = row.original.author

        const label = author?.name?.trim() || author?.email || ""

        return label || "—"
      },
    },

    ...defineRelationExportColumns<PostListRow>([
      {
        id: "authorEmail",

        header: "Email tác giả",

        getValue: (row) => row.author?.email ?? "",
      },

      {
        id: "authorId",

        header: "ID tác giả",

        getValue: (row) => row.author?.id ?? "",

        defaultHidden: true,
      },
    ]),

    {
      accessorKey: "published",

      header: "Trạng thái",

      cell: ({ row }) => (
        <UsageStatusFromValue
