src/app/products/page.tsx.content:
"use client"

import { useEffect, useMemo, useState } from "react"
import type { ColumnDef, RowSelectionState } from "@tanstack/react-table"
import { useQueryClient } from "@tanstack/react-query"
import { Package, Plus, AlertCircle } from "lucide-react"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@ui/components/tabs"
import {
  AdminListPageHeader,
  AdminPageGuard,
  AdminPageHeaderPrimaryButton,
  AdminPageSection,
  AdminReadOnlyHint,
  AdminTabCountBadge,
} from "@ui/components/admin"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "@ui/lib/layout-shell"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { useDebouncedValue } from "@/hooks/use-debounced-value"
import { useAuth } from "@/providers/auth-provider"
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client"
import { api } from "@/lib/api"
import { useAdminCrudRowHandlers } from "@/lib/admin-row-action-handlers"
import { useAdminMutation } from "@/hooks/use-admin-mutation"
import {
  getProductColumns,
  ProductsTable,
  prefetchProductDetail,
  useProductsListQuery,
  useProductsTrashQuery,
  type ProductRow,
} from "./_component"

function ProductsPageInner() {
  const queryClient = useQueryClient()
  const crudNav = useAdminCrudNavigation("/products", {
    prefetchDetail: (id) => prefetchProductDetail(queryClient, api, id),
  })
  const { user } = useAuth()
  const canWrite = user
    ? canUserAccess(user, PERMISSION_CODES.PRODUCTS_MANAGE) ||
      canUserAccess(user, PERMISSION_CODES.PRODUCTS_CREATE) ||
      canUserAccess(user, PERMISSION_CODES.PRODUCTS_UPDATE)
    : false
  const canDelete = user
    ? canUserAccess(user, PERMISSION_CODES.PRODUCTS_MANAGE) ||
      canUserAccess(user, PERMISSION_CODES.PRODUCTS_DELETE)
    : false
  const canRestore = canWrite

  const [mainTab, setMainTab] = useState<"list" | "trash">("list")
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(20)
  const [trashPage, setTrashPage] = useState(1)
  const [trashPageSize, setTrashPageSize] = useState(15)
  const [globalFilter, setGlobalFilter] = useState("")
  const [trashGlobalFilter, setTrashGlobalFilter] = useState("")
  const [listSelection, setListSelection] = useState<RowSelectionState>({})
  const debouncedQ = useDebouncedValue(globalFilter, 300)
  const debouncedTrashQ = useDebouncedValue(trashGlobalFilter, 300)

  const listQuery = useProductsListQuery(api, {
    page,
    limit: pageSize,
    q: debouncedQ.trim() || undefined,
    status: "active",
    enabled: mainTab === "list",
  })

  const trashQuery = useProductsTrashQuery(api, {
    page: trashPage,
    limit: trashPageSize,
    q: debouncedTrashQ.trim() || undefined,
    enabled: mainTab === "trash",
  })

  const invalidate = () =>
    queryClient.invalidateQueries({ queryKey: ["products"] })

  const deleteMutation = useAdminMutation({
    mutationFn: (id: string) => api.products.remove(Number(id)),
    onSuccess: invalidate,
  })
  const restoreMutation = useAdminMutation({
    mutationFn: (id: string) => api.products.restore(Number(id)),
    onSuccess: invalidate,
  })

  const rowActions = useAdminCrudRowHandlers<ProductRow>({
    getRecordLabel: (row) => row.name,
    entityLabel: "sản phẩm",
    deleteMutation,
    restoreMutation,
  })

  const columns = useMemo<ColumnDef<ProductRow>[]>(
    () =>
      getProductColumns({
        view: "list",
        openDetail: (row) => crudNav.view(row.id),
        openEdit: (row) => crudNav.edit(row.id),
        rowActions,
        canWrite,
        canDelete,
      }),
    [crudNav, rowActions, canWrite, canDelete]
  )

  const trashColumns = useMemo<ColumnDef<ProductRow>[]>(
    () =>
      getProductColumns({
        view: "trash",
        rowActions,
        canWrite,
        canRestore,
      }),
    [rowActions, canWrite, canRestore]
  )

  useEffect(() => {
    setPage(1)
  }, [debouncedQ, pageSize])
  useEffect(() => {
    setTrashPage(1)
  }, [debouncedTrashQ, trashPageSize])

  return (
    <AdminPageSection>
      <AdminListPageHeader
        title="Sản phẩm"
        subtitle="Catalog storefront — ảnh đơn hàng được snapshot khi checkout."
        icon={Package}
        readOnlyHint={
          user && !canWrite ? (
            <AdminReadOnlyHint>
              Chỉ xem — cần quyền{" "}
              <span className="font-mono">products:manage</span>.
            </AdminReadOnlyHint>
          ) : undefined
        }
        actions={
          canWrite ? (
            <AdminPageHeaderPrimaryButton
              type="button"
              onClick={() => crudNav.new()}
            >
              <Plus className="size-5" aria-hidden /> Thêm sản phẩm
            </AdminPageHeaderPrimaryButton>
          ) : undefined
        }
      />

      <Tabs
        value={mainTab}
        onValueChange={(v) => {
          if (v === "list" || v === "trash") setMainTab(v)
        }}
        className="space-y-6"
      >
        <TabsList className={ADMIN_LIST_TABS_LIST_CLASS}>
          <TabsTrigger value="list" className={ADMIN_LIST_TABS_TRIGGER_CLASS}>
            Danh sách
            <AdminTabCountBadge count={listQuery.data?.total ?? 0} />
          </TabsTrigger>
          {canWrite && (
            <TabsTrigger
              value="trash"
              className={ADMIN_LIST_TABS_TRIGGER_CLASS}
            >
              Thùng rác
              <AdminTabCountBadge count={trashQuery.data?.total ?? 0} />
            </TabsTrigger>
          )}
        </TabsList>

        <TabsContent value="list" className="mt-0">
          {listQuery.error ? (
            <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-destructive">
              <AlertCircle className="mb-2 size-5" />
              {listQuery.error.message}
            </div>
          ) : (
            <ProductsTable
              data={listQuery.data?.items ?? []}
              columns={columns}
              isLoading={listQuery.isLoading}
              total={listQuery.data?.total ?? 0}
              page={page}
              pageSize={pageSize}
              onPageChange={setPage}
              onPageSizeChange={setPageSize}
              globalFilter={globalFilter}
              onGlobalFilterChange={setGlobalFilter}
              selectedRowIds={listSelection}
              onSelectedRowIdsChange={setListSelection}
              onClearFilters={() => setGlobalFilter("")}
              onRowPrefetch={(row) => crudNav.prefetch(row.id)}
              onBulkDelete={
                canDelete
                  ? async (rows) => {
                      for (const row of rows) {
                        await deleteMutation.mutateAsync(row.id)
                      }
                    }
                  : undefined
              }
            />
          )}
        </TabsContent>

        {canWrite && (
          <TabsContent value="trash" className="mt-0">
            <ProductsTable
              data={trashQuery.data?.items ?? []}
              columns={trashColumns}
              isLoading={trashQuery.isLoading}
              total={trashQuery.data?.total ?? 0}
              page={trashPage}
              pageSize={trashPageSize}
              onPageChange={setTrashPage}
              onPageSizeChange={setTrashPageSize}
              globalFilter={trashGlobalFilter}
              onGlobalFilterChange={setTrashGlobalFilter}
              selectedRowIds={listSelection}
              onSelectedRowIdsChange={setListSelection}
              onClearFilters={() => setTrashGlobalFilter("")}
            />
          </TabsContent>
        )}
      </Tabs>
    </AdminPageSection>
  )
}

export default function ProductsPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <ProductsPageInner />
    </AdminPageGuard>
  )
}

src/app/products/[id]/edit/page.tsx.content:
"use client"

import { useCallback, useEffect, useRef } from "react"
import { useParams } from "next/navigation"
import { useQueryClient } from "@tanstack/react-query"
import { toast } from "@ui/components/sonner"
import {
  AdminPageGuard,
  AdminPageLoading,
  AdminPageSection,
} from "@ui/components/admin"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import { api } from "@/lib/api"
import { useAdminMutation } from "@/hooks/use-admin-mutation"
import {
  ProductFormShell,
  useProductForm,
  buildProductPayload,
  productToFormValues,
  useProductDetailQuery,
  type ProductFormValues,
} from "../../_component"

function EditProductPageInner() {
  const crudNav = useAdminCrudNavigation("/products")
  const params = useParams()
  const id = params.id as string
  const queryClient = useQueryClient()
  const { data, isLoading, isError } = useProductDetailQuery(api, id)
  const { form } = useProductForm()
  const hydratedIdRef = useRef<string | null>(null)

  useEffect(() => {
    hydratedIdRef.current = null
  }, [id])

  useEffect(() => {
    if (!data || hydratedIdRef.current === id) return
    form.reset(productToFormValues(data))
    hydratedIdRef.current = id
  }, [data, form, id])

  useEffect(() => {
    if (isError) {
      toast.error("Không tải được sản phẩm")
      crudNav.list()
    }
  }, [isError, crudNav])

  const updateMutation = useAdminMutation({
    mutationKey: ["products", "update", id],
    toast: {
      loading: "Đang lưu sản phẩm…",
      success: () => "Đã cập nhật sản phẩm",
      error: (err) =>
        err instanceof Error ? err.message : "Không thể cập nhật sản phẩm",
    },
    mutationFn: (body: ReturnType<typeof buildProductPayload>) =>
      api.products.update(Number(id), body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["products"] })
      crudNav.view(id)
    },
  })

  const handleSubmit = useCallback(
    async (values: ProductFormValues) => {
      await updateMutation.mutateAsync(buildProductPayload(values))
    },
    [updateMutation]
  )

  if (isLoading) return <AdminPageLoading />
  if (!data) return null

  return (
    <AdminPageSection>
      <ProductFormShell
        form={form}
        onSubmit={handleSubmit}
        submitting={updateMutation.isPending}
        editingId={id}
        onBack={() => crudNav.view(id)}
        onReset={() => form.reset(productToFormValues(data))}
      />
    </AdminPageSection>
  )
}

export default function EditProductPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <EditProductPageInner />
    </AdminPageGuard>
  )
}

