}

src/app/products/_component/product-cata.content:
"use client"

import { useEffect, useMemo, useState } from "react"
import { Package } from "lucide-react"
import {
  PanelDialog,
  PanelDialogSearch,
} from "@ui/components/dialogs/panel-dialog"
import { Button } from "@ui/components/button"
import { resolveMediaUrl } from "@ui/lib/resolve-media-url"
import { api } from "@/lib/api"
import { useProductsListQuery } from "./use-products-queries"
import type { ProductRow } from "./types"

function firstProductImage(product: ProductRow): string {
  const fromUnit = product.unitTypes?.find((u) => u.images?.length)?.images?.[0]
  return fromUnit ?? product.images?.[0] ?? ""
}

export type ProductCatalogPickerDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (product: ProductRow) => void
  excludeProductId?: string | null
  title?: string
}

export function ProductCatalogPickerDialog({
  open,
  onOpenChange,
  onSelect,
  excludeProductId,
  title = "Chọn sản phẩm quà tặng",
}: ProductCatalogPickerDialogProps) {
  const [q, setQ] = useState("")
  const [debouncedQ, setDebouncedQ] = useState("")

  useEffect(() => {
    if (!open) {
      setQ("")
      setDebouncedQ("")
      return
    }
    const timer = window.setTimeout(() => setDebouncedQ(q.trim()), 280)
    return () => window.clearTimeout(timer)
  }, [q, open])

  const listQuery = useProductsListQuery(api, {
    page: 1,
    limit: 30,
    q: debouncedQ || undefined,
    enabled: open,
  })

  const items = useMemo(() => {
    const rows = listQuery.data?.items ?? []
    if (!excludeProductId) return rows
    return rows.filter((row) => row.id !== excludeProductId)
  }, [listQuery.data?.items, excludeProductId])

  return (
    <PanelDialog
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description="Chọn sản phẩm có sẵn trong kho làm quà tặng kèm."
      size="md"
      footer={
        <Button
          type="button"
          variant="outline"
          onClick={() => onOpenChange(false)}
        >
          Đóng
        </Button>
      }
    >
      <div className="space-y-4">
        <PanelDialogSearch
          id="product-catalog-picker-q"
          value={q}
          onChange={setQ}
          placeholder="Tìm theo tên hoặc SKU…"
        />

        <div className="max-h-[min(52vh,420px)] space-y-1 overflow-y-auto rounded-lg border bg-card p-1">
          {listQuery.isLoading ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              Đang tải…
            </p>
          ) : listQuery.isError ? (
            <p className="px-3 py-6 text-center text-sm text-destructive">
              Không tải được danh sách sản phẩm.
            </p>
          ) : items.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              Không có sản phẩm phù hợp.
            </p>
          ) : (
            items.map((product) => {
              const image = firstProductImage(product)
              const imageSrc = image ? resolveMediaUrl(image, 96) : ""
              return (
                <button
                  key={product.id}
                  type="button"
                  onClick={() => {
                    onSelect(product)
                    onOpenChange(false)
                  }}
                  className="flex w-full items-center gap-3 rounded-md px-2 py-2 text-left transition-colors hover:bg-muted/60"
                >
                  <div className="relative size-11 shrink-0 overflow-hidden rounded-md border bg-muted">
                    {imageSrc ? (
                      <img
                        src={imageSrc}
                        alt=""
                        className="size-full object-cover"
                        loading="lazy"
                        decoding="async"
                      />
                    ) : (
                      <div className="flex size-full items-center justify-center">
                        <Package
                          className="size-4 text-muted-foreground/50"
                          aria-hidden
                        />
                      </div>
                    )}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium">
                      {product.name}
                    </p>
                    <p className="truncate font-mono text-xs text-muted-foreground">
                      {product.sku}
                    </p>
                  </div>
                </button>
              )
            })
          )}
        </div>
      </div>
    </PanelDialog>
  )
}

export { firstProductImage }

src/app/products/_component/product-form.content:
"use client"

import { zodResolver } from "@hookform/resolvers/zod"
import { useForm, type UseFormReturn } from "react-hook-form"
import { z } from "zod"
import {
  AdminFormLayout,
  AdminFormMain,
  AdminFormPageHeader,
  AdminFormSidebar,
  ProductFormSidebar,
} from "@ui/components/admin"
import {
  FieldSet,
  FieldSetContent,
  FieldSectionLegend,
} from "@ui/components/field"
import type {
  CreateProductInput,
  Product,
  ProductGiftRule,
  ProductUnitType,
} from "@workspace/api-client"
import { productBaseStock } from "@workspace/api-client"
import {
  EMPTY_UNIT_ROW,
  formatImageUrls,
  parseImageUrls,
  type ProductFormValues,
  type ProductUnitFormRow,
} from "./types"
import { ProductUnitVariantsField } from "./product-unit-variants-field"

const unitRowSchema = z.object({
  type: z.string().min(1, "Bắt buộc"),
  label: z.string().min(1, "Bắt buộc"),
  sku: z.string(),
  retailPrice: z.string().min(1, "Bắt buộc"),
  wholesalePrice: z.string(),
  minWholesaleQty: z.string(),
  qtyPerUnit: z.string(),
  imageUrls: z.string(),
  tierMinQty: z.string(),
  tierUnitPrice: z.string(),
  tierLabel: z.string(),
  gifts: z.array(
    z.object({
      label: z.string(),
      minQty: z.string(),
      name: z.string(),
      sku: z.string(),
      qty: z.string(),
      image: z.string(),
      productId: z.string(),
      scope: z.enum(["line", "product"]),
    })
  ),
  isDefault: z.boolean(),
})

const schema = z.object({
  sku: z.string().min(1, "Bắt buộc"),
  name: z.string().min(1, "Bắt buộc"),
  category: z.string().min(1, "Bắt buộc"),
  description: z.string(),
  isActive: z.boolean(),
  fulfillmentNote: z.string(),
  baseStock: z.string(),
  units: z.array(unitRowSchema).min(1, "Cần ít nhất một loại hàng"),
})

function unitRowToApi(row: ProductUnitFormRow, index: number): ProductUnitType {
  const retail = Math.max(0, Math.floor(Number(row.retailPrice) || 0))
  const wholesaleRaw = Math.floor(Number(row.wholesalePrice) || 0)
  const wholesale = wholesaleRaw > 0 ? wholesaleRaw : null
  const minQ = Math.max(0, Math.floor(Number(row.minWholesaleQty) || 0))
  const images = parseImageUrls(row.imageUrls)

  const tierMin = Math.floor(Number(row.tierMinQty) || 0)
  const tierPrice = Math.floor(Number(row.tierUnitPrice) || 0)
  const priceTiers =
    tierMin > 0 && tierPrice > 0
      ? [
          {
            minQty: tierMin,
            unitPrice: tierPrice,
            label: row.tierLabel.trim() || undefined,
          },
        ]
      : undefined

  const giftRules: ProductGiftRule[] = []
  row.gifts.forEach((gift, giftIndex) => {
    const giftMin = Math.floor(Number(gift.minQty) || 0)
    const giftName = gift.name.trim()
    if (giftMin <= 0 || !giftName) return
    giftRules.push({
      id: `gift-${row.type.trim() || index}-${giftIndex}`,
      label: gift.label.trim() || giftName,
      trigger: { scope: gift.scope, minQty: giftMin },
      gift: {
        name: giftName,
        sku: gift.sku.trim() || undefined,
        productId: gift.productId.trim() ? Number(gift.productId) : undefined,
        qty: Math.max(1, Math.floor(Number(gift.qty) || 1)),
        image: gift.image.trim() || undefined,
        qtyMultiplier: "once",
      },
      applyPer: "order",
    })
  })
  const giftRulesOrUndefined = giftRules.length ? giftRules : undefined

  return {
    type: row.type.trim(),
    label: row.label.trim() || row.type.trim(),
    sku: row.sku.trim() || undefined,
    retailPrice: retail,
    wholesalePrice: wholesale,
    minWholesaleQty: minQ,
    qtyPerUnit: Math.max(1, Math.floor(Number(row.qtyPerUnit) || 1)),
    images: images.length ? images : undefined,
    priceTiers,
    giftRules: giftRulesOrUndefined,
    isDefault: row.isDefault,
    isActive: true,
  }
}

export function useProductForm(defaults?: Partial<ProductFormValues>) {
  const form = useForm<ProductFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      sku: "",
      name: "",
      category: "general",
      description: "",
      isActive: true,
      fulfillmentNote: "",
      baseStock: "0",
      units: [{ ...EMPTY_UNIT_ROW }],
      ...defaults,
    },
  })
  return { form }
}

function unitToFormRow(
  unit: ProductUnitType,
  isDefault: boolean
): ProductUnitFormRow {
  const tier = unit.priceTiers?.[0]
  return {
    type: unit.type,
    label: unit.label,
    sku: unit.sku ?? "",
    retailPrice: String(unit.retailPrice ?? 0),
    wholesalePrice: String(unit.wholesalePrice ?? 0),
    minWholesaleQty: String(unit.minWholesaleQty ?? 0),
    qtyPerUnit: String(unit.qtyPerUnit ?? 1),
    imageUrls: formatImageUrls(unit.images),
    tierMinQty: tier ? String(tier.minQty) : "",
    tierUnitPrice: tier ? String(tier.unitPrice) : "",
    tierLabel: tier?.label ?? "",
    gifts: (unit.giftRules ?? []).map((gift) => ({
      label: gift.label ?? "",
      minQty: gift.trigger.minQty ? String(gift.trigger.minQty) : "",
      name: gift.gift.name ?? "",
      sku: gift.gift.sku ?? "",
      qty: String(gift.gift.qty ?? 1),
      image: gift.gift.image ?? "",
      productId: gift.gift.productId ? String(gift.gift.productId) : "",
      scope: gift.trigger.scope === "product" ? "product" : "line",
    })),
    isDefault,
  }
}

export function productToFormValues(product: Product): ProductFormValues {
  const units = product.unitTypes?.length
    ? product.unitTypes.map((u, i) => unitToFormRow(u, u.isDefault ?? i === 0))
    : [
        unitToFormRow(
          {
            type: product.unit,
            label: product.unit,
            retailPrice: product.retailPrice,
            wholesalePrice: product.wholesalePrice,
            minWholesaleQty: 0,
            qtyPerUnit: 1,
            images: product.images ?? undefined,
          },
          true
        ),
      ]

  if (!units.some((u) => u.isDefault)) {
    units[0] = { ...units[0]!, isDefault: true }
  }

  return {
    sku: product.sku,
    name: product.name,
    category: product.category,
    description: product.description ?? "",
    isActive: product.isActive,
    fulfillmentNote: product.fulfillmentNote ?? "",
    baseStock: String(productBaseStock(product)),
    units,
  }
}

export function buildProductPayload(
  values: ProductFormValues
): CreateProductInput {
  const unitTypes = values.units.map((row, index) => unitRowToApi(row, index))
  const defaultUnit = unitTypes.find((u) => u.isDefault) ?? unitTypes[0]!
  const allImages = unitTypes.flatMap((u) => u.images ?? [])
  const totalStock = Math.max(0, Math.floor(Number(values.baseStock) || 0))

  return {
    sku: values.sku.trim(),
    name: values.name.trim(),
    category: values.category.trim(),
    description: values.description?.trim() || null,
    basePrice: defaultUnit.retailPrice,
    retailPrice: defaultUnit.retailPrice,
    wholesalePrice: defaultUnit.wholesalePrice ?? 0,
    stock: totalStock,
    unit: defaultUnit.type,
    unitTypes,
    images: allImages.length ? [...new Set(allImages)] : null,
    fulfillmentNote: values.fulfillmentNote.trim() || null,
    isActive: values.isActive,
  }
}

export function ProductFormShell({
  form,
  onSubmit,
  submitting,
  editingId,
  onBack,
  onReset,
}: {
  form: UseFormReturn<ProductFormValues>
  onSubmit: (values: ProductFormValues) => Promise<void>
  submitting: boolean
  editingId: string | null
  onBack: () => void
  onReset: () => void
}) {
  const { register, watch, setValue } = form
  const isActive = watch("isActive")
  const units = watch("units") ?? []
  const baseStock = watch("baseStock")

  return (
    <>
      <AdminFormPageHeader
        title={editingId ? "Chỉnh sửa sản phẩm" : "Thêm sản phẩm"}
        subtitle="Mỗi loại hàng có giá, ảnh, tồn và quà tặng riêng — snapshot lúc checkout."
        onBack={onBack}
        onReset={onReset}
        formId="product-form"
        submitting={submitting}
        isEdit={!!editingId}
      />
      <AdminFormLayout id="product-form" onSubmit={form.handleSubmit(onSubmit)}>
        <AdminFormMain className="space-y-6">
          <FieldSet variant="section">
            <FieldSectionLegend
              title="Loại hàng (biến thể)"
              description="Giá, ảnh, tồn pool chung, bậc giá và quà tặng theo từng loại."
            />
            <FieldSetContent variant="section" className="pt-0">
              <ProductUnitVariantsField
                form={form}
                currentProductId={editingId}
              />
            </FieldSetContent>
          </FieldSet>
        </AdminFormMain>
        <AdminFormSidebar className="sticky top-2 max-h-[calc(100vh-80px)] overflow-y-auto">
          <ProductFormSidebar
            register={register}
            isActive={isActive}
            onIsActiveChange={(v) => setValue("isActive", v)}
            baseStock={baseStock}
            units={units}
          />
        </AdminFormSidebar>
      </AdminFormLayout>
    </>
  )
}

src/app/products/_component/product-imag.content:
import { resolveStorageFolderSlugPath } from "@workspace/api-client"
import {
  createStorageFolder,
  fetchStorageFolders,
  type FolderItem,
} from "@/lib/admin-uploads"
import { resolveFolderPathAfterCreate } from "@/app/file-storage/_component/utils"
import {
  extensionsFromGroupIds,
  getRealmDefaultGroupIds,
} from "@/app/file-storage/_component/storage-upload-policy"

export const PRODUCT_IMAGE_PARENT_LABEL = "Sản phẩm"
export const PRODUCT_IMAGE_PARENT_SLUG = "san-pham"

export type ProductImageUploadInput = {
  productName?: string
  productSlug?: string
  productSku?: string
}

export type ProductImageUploadContext = {
  productName: string
  productSlug: string
  productSku?: string
  folderLabel: string
}

function leafSlugFromText(input: string): string {
  const from = resolveStorageFolderSlugPath(input.trim())
  if (!from?.slugPath) return ""
  const parts = from.slugPath.split("/").filter(Boolean)
  return parts[parts.length - 1] ?? ""
}

export function resolveProductImageSlug(
  productName: string,
  productSlug?: string,
  productSku?: string
): string {
  const explicit = productSlug?.trim()
  if (explicit) return explicit

  const fromName = leafSlugFromText(productName)
  if (fromName) return fromName

  return leafSlugFromText(productSku ?? "")
}

/** Đọc trực tiếp từ form — tránh `watch` trong dialog bị stale. */
export function buildProductImageUploadContext(
  input: ProductImageUploadInput
): ProductImageUploadContext | null {
  const name = input.productName?.trim() ?? ""
  const sku = input.productSku?.trim() ?? ""
  const folderLabel = name || sku
  const slug = resolveProductImageSlug(name, input.productSlug, sku)

  if (!folderLabel || !slug) return null

  return {
    productName: name || folderLabel,
    productSlug: slug,
    productSku: sku || undefined,
    folderLabel,
  }
}

export function resolveProductImageFolderNav(
  productName: string,
  productSlug?: string,
  productSku?: string
): { navPath: string; slug: string; label: string } | null {
  const ctx = buildProductImageUploadContext({
    productName,
    productSlug,
    productSku,
  })
  if (!ctx) return null
  return {
    navPath: `${PRODUCT_IMAGE_PARENT_SLUG}/${ctx.productSlug}`,
    slug: ctx.productSlug,
    label: ctx.folderLabel,
  }
}

function folderNavPath(folder: FolderItem): string {
  return resolveFolderPathAfterCreate(folder.path.replace(/\\/g, "/"), "images")
}

export function folderMatchesProductImage(
  folder: FolderItem,
  slug: string
): boolean {
  const nav = folderNavPath(folder)
  if (nav === `${PRODUCT_IMAGE_PARENT_SLUG}/${slug}`) return true
  if (!nav.startsWith(`${PRODUCT_IMAGE_PARENT_SLUG}/`)) return false
  const leaf = nav.split("/").pop()
  return leaf === slug
}

export function findProductImageFolder(
  folders: FolderItem[],
  input: ProductImageUploadInput
): { navPath: string; uploadFolderPath: string } | null {
  const resolved = resolveProductImageFolderNav(
    input.productName ?? "",
    input.productSlug,
    input.productSku
  )
  if (!resolved) return null
  const match = folders.find((folder) =>
    folderMatchesProductImage(folder, resolved.slug)
  )
  if (!match) return null
  const navPath = folderNavPath(match)
  return { navPath, uploadFolderPath: navPath }
}

async function ensureProductImageParentFolder(
  folders: FolderItem[]
): Promise<void> {
  const parentExists = folders.some((folder) => {
    const nav = folderNavPath(folder)
    return nav === PRODUCT_IMAGE_PARENT_SLUG
  })
  if (parentExists) return

  await createStorageFolder({
    folderName: PRODUCT_IMAGE_PARENT_LABEL,
    parentPath: "images",
    resourceType: "images",
    allowedExtensions: extensionsFromGroupIds(
      "images",
      getRealmDefaultGroupIds("images")
    ),
  })
}

/** Tạo hoặc tái sử dụng folder ảnh chính của sản phẩm dưới «Sản phẩm». */
export async function ensureProductImageFolder(
  input: ProductImageUploadInput
): Promise<{ navPath: string; uploadFolderPath: string; created: boolean }> {
  const resolved = resolveProductImageFolderNav(
    input.productName ?? "",
    input.productSlug,
    input.productSku
  )
  if (!resolved) {
    throw new Error(
      "Nhập tên hoặc SKU sản phẩm ở form — hệ thống cần tạo slug folder lưu ảnh"
    )
  }

  let folders = await fetchStorageFolders()
  const existing = findProductImageFolder(folders, input)
  if (existing) {
    return { ...existing, created: false }
  }

  await ensureProductImageParentFolder(folders)
  folders = await fetchStorageFolders()

  const parentFolder = folders.find(
    (folder) => folderNavPath(folder) === PRODUCT_IMAGE_PARENT_SLUG
  )
  const parentDisk =
    parentFolder?.path.replace(/\\/g, "/") ??
    `images/${PRODUCT_IMAGE_PARENT_SLUG}`

  const created = await createStorageFolder({
    folderName: resolved.label,
    parentPath: parentDisk,
    resourceType: "images",
  })

  const navPath = resolveFolderPathAfterCreate(created.folderPath, "images")
  return {
    navPath,
    uploadFolderPath: navPath,
    created: true,
  }
}

src/app/products/_component/product-unit.content:
"use client"

import { useState } from "react"
import {
  Controller,
  useFieldArray,
  useWatch,
  type Control,
  type UseFormRegister,
  type UseFormSetValue,
} from "react-hook-form"
import {
  ImageUrlField,
  ProductUnitGiftCatalogCard,
  ProductUnitGiftPreview,
  ProductUnitGiftSourcePanel,
  type ProductUnitGiftSource,
  formatGiftScopeLabel,
} from "@ui/components/admin"
import { Button } from "@ui/components/button"
import { FormFieldCol } from "@ui/components/typing"
import { Input } from "@ui/components/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@ui/components/select"
import { Plus, Trash2 } from "lucide-react"
import {
  EMPTY_GIFT_ROW,
  type ProductFormValues,
  type ProductUnitGiftFormRow,
} from "./types"

export function hasSingleGiftData(gift: ProductUnitGiftFormRow) {
  return Boolean(
    gift.label.trim() ||
    gift.minQty.trim() ||
    gift.name.trim() ||
    gift.sku.trim() ||
    gift.image.trim() ||
    gift.productId.trim()
  )
}

export function hasGiftsData(gifts: ProductUnitGiftFormRow[] | undefined) {
  return (gifts ?? []).some(hasSingleGiftData)
}

type ProductUnitGiftsFieldProps = {
  control: Control<ProductFormValues>
  register: UseFormRegister<ProductFormValues>
  setValue: UseFormSetValue<ProductFormValues>
  unitIndex: number
  unitLabel: string
  onPickGiftImage: (giftIndex: number) => void
  onPickFromCatalog: (giftIndex: number) => void
}

function GiftRuleCard({
  control,
  register,
  setValue,
  unitIndex,
  giftIndex,
  unitLabel,
  onRemove,
  canRemove,
  onPickGiftImage,
  onPickFromCatalog,
}: {
  control: Control<ProductFormValues>
  register: UseFormRegister<ProductFormValues>
  setValue: UseFormSetValue<ProductFormValues>
  unitIndex: number
  giftIndex: number
  unitLabel: string
  onRemove: () => void
  canRemove: boolean
  onPickGiftImage: () => void
  onPickFromCatalog: () => void
}) {
  const base = `units.${unitIndex}.gifts.${giftIndex}` as const

  const gift =
    useWatch({
      control,
      name: base,
    }) ?? EMPTY_GIFT_ROW

  const [tabOverride, setTabOverride] = useState<ProductUnitGiftSource | null>(
    null
  )
  const sourceTab: ProductUnitGiftSource = gift.productId?.trim()
    ? "catalog"
    : (tabOverride ?? "manual")

  const handleSourceChange = (source: ProductUnitGiftSource) => {
    setTabOverride(source)
    if (source === "manual") {
      setValue(`${base}.productId`, "")
    }
  }

  return (
    <div className="space-y-3 rounded-lg border border-border/80 bg-card p-3 shadow-sm">
      <div className="flex items-center justify-between gap-2">
        <p className="text-sm font-medium">Quà #{giftIndex + 1}</p>
        {canRemove ? (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            onClick={onRemove}
            aria-label={`Xóa quà #${giftIndex + 1}`}
          >
            <Trash2 className="size-4" />
          </Button>
        ) : null}
      </div>

      <ProductUnitGiftSourcePanel
        source={sourceTab}
        onSourceChange={handleSourceChange}
        catalogContent={
          <ProductUnitGiftCatalogCard
            linked={Boolean(gift.productId?.trim())}
            name={gift.name}
            sku={gift.sku}
            imageUrl={gift.image}
            onPick={onPickFromCatalog}
            onClear={() => setValue(`${base}.productId`, "")}
          />
        }
        manualContent={
          <div className="grid gap-3 sm:grid-cols-2">
            <FormFieldCol label="Tên quà">
              <Input
                {...register(`${base}.name`)}
                placeholder="Cốc thủy tinh"
              />
            </FormFieldCol>
            <FormFieldCol label="SKU quà">
              <Input {...register(`${base}.sku`)} placeholder="GIFT-COC" />
            </FormFieldCol>
            <FormFieldCol label="Ảnh quà" className="sm:col-span-2">
              <Controller
                control={control}
                name={`${base}.image`}
                render={({ field }) => (
                  <ImageUrlField
                    value={field.value ?? ""}
                    onChange={field.onChange}
                    onPickFromStorage={onPickGiftImage}
                  />
                )}
              />
            </FormFieldCol>
          </div>
        }
      />

      <div className="grid gap-3 sm:grid-cols-2">
        <FormFieldCol label="Khi mua từ (sp)">
          <Input
            type="number"
            min={1}
            placeholder="10"
            className="tabular-nums"
            {...register(`${base}.minQty`)}
          />
        </FormFieldCol>
        <FormFieldCol
          label="Phạm vi đếm SL"
          description="SL kiểm tra điều kiện nhận quà này."
        >
          <Select
            value={gift.scope ?? "line"}
            onValueChange={(v) =>
              setValue(`${base}.scope`, v as "line" | "product")
            }
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder="Chọn phạm vi đếm SL">
                {formatGiftScopeLabel(gift.scope, unitLabel)}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="line">
                {formatGiftScopeLabel("line", unitLabel)}
              </SelectItem>
              <SelectItem value="product">
                {formatGiftScopeLabel("product", unitLabel)}
              </SelectItem>
            </SelectContent>
          </Select>
        </FormFieldCol>
        <FormFieldCol label="Nhãn KM (ngắn)">
          <Input {...register(`${base}.label`)} placeholder="Tặng cốc" />
        </FormFieldCol>
        <FormFieldCol label="Số quà / lần">
          <Input
            type="number"
            min={1}
            placeholder="1"
            className="tabular-nums"
            {...register(`${base}.qty`)}
          />
        </FormFieldCol>
      </div>
    </div>
  )
}

export function ProductUnitGiftsField({
  control,
  register,
  setValue,
  unitIndex,
  unitLabel,
  onPickGiftImage,
  onPickFromCatalog,
}: ProductUnitGiftsFieldProps) {
  const giftsPath = `units.${unitIndex}.gifts` as const
  const { fields, append, remove } = useFieldArray({
    control,
    name: giftsPath,
  })

  const gifts =
    useWatch({
      control,
      name: giftsPath,
    }) ?? []

  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(200px,240px)]">
      <div className="space-y-3">
        {fields.map((field, giftIndex) => (
          <GiftRuleCard
            key={field.id}
            control={control}
            register={register}
            setValue={setValue}
            unitIndex={unitIndex}
            giftIndex={giftIndex}
            unitLabel={unitLabel}
            canRemove={fields.length > 1}
            onRemove={() => remove(giftIndex)}
            onPickGiftImage={() => onPickGiftImage(giftIndex)}
            onPickFromCatalog={() => onPickFromCatalog(giftIndex)}
          />
        ))}

        <Button
          type="button"
          variant="outline"
          className="w-full sm:w-auto"
          onClick={() => append({ ...EMPTY_GIFT_ROW })}
        >
          <Plus className="size-4" /> Thêm quà tặng
        </Button>
      </div>

      <div className="flex flex-col gap-3 lg:sticky lg:top-2">
        <p className="text-xs font-medium text-muted-foreground">
          Xem trước khách hàng
        </p>
        {gifts.length === 0 ? (
          <p className="rounded-lg border bg-card p-3 text-xs text-muted-foreground shadow-sm">
            Chưa có quà tặng — bấm «Thêm quà tặng» để bắt đầu.
          </p>
        ) : (
          gifts.map((gift, i) => (
            <ProductUnitGiftPreview
              key={fields[i]?.id ?? i}
              giftLabel={gift?.label ?? ""}
              giftName={gift?.name ?? ""}
              giftMinQty={gift?.minQty ?? ""}
              giftQty={gift?.qty ?? "1"}
              giftImage={gift?.image ?? ""}
              giftScope={gift?.scope ?? "line"}
              unitLabel={unitLabel}
            />
          ))
        )}
      </div>
    </div>
  )
}

"use client"

import { useCallback, useState } from "react"
import {
  Controller,
  useFieldArray,
  useWatch,
  type UseFormReturn,
} from "react-hook-form"
import {
  ImageUrlListField,
  ProductUnitFormSubsection,
  ProductUnitOptionalSection,
  ProductUnitPromoDivider,
  ProductUnitPromoRuleCard,
  ProductUnitQtyInline,
  ProductUnitStockBlock,
  ProductUnitStockPoolBanner,
  ProductUnitVariantCardHeader,
  buildGiftsSummary,
  buildTierSummary,
  buildTierRuleText,
  buildWholesaleSummary,
  buildWholesaleRuleText,
  computeFormUnitStockPool,
  maxSellableFromPool,
} from "@ui/components/admin"
import { Button } from "@ui/components/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@ui/components/collapsible"
import { StorageImagePickerDialog } from "@/lib/storage-image-picker-dialog"
import { parseImageUrls, formatImageUrls } from "./types"
import { FormFieldCol } from "@ui/components/typing"
import { Input } from "@ui/components/input"
import { ChevronDown, Gift, Layers, Plus, Tag, Trash2 } from "lucide-react"
import { cn } from "@ui/lib/utils"
import type { ProductFormValues } from "./types"
import { EMPTY_GIFT_ROW, EMPTY_UNIT_ROW } from "./types"
import { buildProductImageUploadContext } from "./product-image-storage"
import {
  firstProductImage,
  ProductCatalogPickerDialog,
} from "./product-catalog-picker-dialog"
import { hasGiftsData, ProductUnitGiftsField } from "./product-unit-gifts-field"

function hasWholesaleData(wholesalePrice: string, minWholesaleQty: string) {
  return Number(wholesalePrice) > 0 || Number(minWholesaleQty) > 0
}

function hasTierData(
  tierMinQty: string,
  tierUnitPrice: string,
  tierLabel: string
) {
  return Boolean(tierMinQty.trim() || tierUnitPrice.trim() || tierLabel.trim())
}

function UnitPromoSections({
  form,
  index,
  unitLabel,
  onPickGiftImage,
  onPickFromCatalog,
}: {
  form: UseFormReturn<ProductFormValues>
  index: number
  unitLabel: string
  onPickGiftImage: (giftIndex: number) => void
  onPickFromCatalog: (giftIndex: number) => void
}) {
  const { control, register, setValue } = form

  const unitRow =
    useWatch({
      control,
      name: `units.${index}`,
    }) ?? EMPTY_UNIT_ROW

  const resolvedUnitLabel = unitRow.label?.trim() || unitLabel

  const wholesalePrice = unitRow.wholesalePrice ?? "0"
  const minWholesaleQty = unitRow.minWholesaleQty ?? "0"
  const tierMinQty = unitRow.tierMinQty ?? ""
  const tierUnitPrice = unitRow.tierUnitPrice ?? ""
  const tierLabel = unitRow.tierLabel ?? ""
  const gifts = unitRow.gifts ?? []

  const wholesaleHasData = hasWholesaleData(wholesalePrice, minWholesaleQty)
  const tierHasData = hasTierData(tierMinQty, tierUnitPrice, tierLabel)
  const giftHasData = hasGiftsData(gifts)

  const [wholesaleDraft, setWholesaleDraft] = useState(false)
  const [tierDraft, setTierDraft] = useState(false)
  const [giftDraft, setGiftDraft] = useState(false)

  const wholesaleEnabled = wholesaleHasData || wholesaleDraft
  const tierEnabled = tierHasData || tierDraft
  const giftEnabled = giftHasData || giftDraft

  const wholesaleSummary = buildWholesaleSummary(
    wholesalePrice,
    minWholesaleQty
  )
  const tierSummary = buildTierSummary(tierMinQty, tierUnitPrice, tierLabel)
  const giftSummary = buildGiftsSummary(gifts)
  const wholesaleRuleText = buildWholesaleRuleText(
    minWholesaleQty,
    wholesalePrice
  )
  const tierRuleText = buildTierRuleText(tierMinQty, tierUnitPrice, tierLabel)

  return (
    <div className="mt-4 space-y-3">
      <ProductUnitPromoDivider />

      <ProductUnitOptionalSection
        icon={Tag}
        title="Giá sỉ / khuyến mãi"
        description="Một mức giá ưu đãi cố định khi khách mua đủ số lượng — khác bậc giá (giảm theo từng mức SL)."
        enabled={wholesaleEnabled}
        summary={wholesaleSummary}
        summaryVariant="promo"
        onEnabledChange={(on) => {
          setWholesaleDraft(on)
          if (!on) {
            setValue(`units.${index}.wholesalePrice`, "0")
            setValue(`units.${index}.minWholesaleQty`, "0")
          }
        }}
      >
        <ProductUnitPromoRuleCard
          hint={wholesaleRuleText}
          condition={
            <ProductUnitQtyInline
              prefix="Từ"
              suffix="sp"
              input={
                <Input
                  type="number"
                  min={1}
                  placeholder="10"
                  className="h-8 tabular-nums"
                  {...register(`units.${index}.minWholesaleQty`)}
                />
              }
            />
          }
          result={
            <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
              <Input
                type="number"
                min={0}
                placeholder="28000"
                className="h-8 min-w-[6.5rem] flex-1 tabular-nums"
                {...register(`units.${index}.wholesalePrice`)}
              />
              <span className="text-sm text-muted-foreground">₫ / sp</span>
            </div>
          }
        />
      </ProductUnitOptionalSection>

      <ProductUnitOptionalSection
        icon={Layers}
        title="Bậc giá theo số lượng"
        description="Giảm đơn giá khi đạt ngưỡng SL — nhãn hiển thị trên storefront (vd. «Mua 5+»)."
        enabled={tierEnabled}
        summary={tierSummary}
        summaryVariant="category"
        onEnabledChange={(on) => {
          setTierDraft(on)
          if (!on) {
            setValue(`units.${index}.tierMinQty`, "")
            setValue(`units.${index}.tierUnitPrice`, "")
            setValue(`units.${index}.tierLabel`, "")
          }
        }}
      >
        <ProductUnitPromoRuleCard
          hint={tierRuleText}
          condition={
            <ProductUnitQtyInline
              prefix="Từ"
              suffix="sp"
              input={
                <Input
                  type="number"
                  min={1}
                  placeholder="5"
                  className="h-8 tabular-nums"
                  {...register(`units.${index}.tierMinQty`)}
                />
              }
            />
          }
          result={
            <div className="space-y-2">
              <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                <Input
                  type="number"
                  min={0}
                  placeholder="28000"
                  className="h-8 min-w-[6.5rem] flex-1 tabular-nums"
                  {...register(`units.${index}.tierUnitPrice`)}
                />
                <span className="text-sm text-muted-foreground">₫ / sp</span>
              </div>
              <Input
                {...register(`units.${index}.tierLabel`)}
                placeholder="Nhãn: Mua 5+"
                className="h-8"
              />
            </div>
          }
        />
      </ProductUnitOptionalSection>

      <ProductUnitOptionalSection
        icon={Gift}
        title="Quà tặng kèm"
        description="Tặng thêm sản phẩm khi khách mua đủ số lượng."
        enabled={giftEnabled}
        summary={giftSummary}
        summaryVariant="coupon"
        onEnabledChange={(on) => {
          setGiftDraft(on)
          if (on && gifts.length === 0) {
            setValue(`units.${index}.gifts`, [{ ...EMPTY_GIFT_ROW }])
          }
          if (!on) {
            setValue(`units.${index}.gifts`, [])
          }
        }}
      >
        <ProductUnitGiftsField
          control={control}
          register={register}
          setValue={setValue}
          unitIndex={index}
          unitLabel={resolvedUnitLabel}
          onPickGiftImage={onPickGiftImage}
          onPickFromCatalog={onPickFromCatalog}
        />
      </ProductUnitOptionalSection>
    </div>
  )
}

function UnitVariantCardBody({
  form,
  index,
  unitLabel,
  poolBase,
  onPickImages,
  onPickGiftImage,
  onPickFromCatalog,
}: {
  form: UseFormReturn<ProductFormValues>
  index: number
  unitLabel: string
  poolBase: number
  onPickImages: () => void
  onPickGiftImage: (giftIndex: number) => void
  onPickFromCatalog: (giftIndex: number) => void
}) {
  const { control, register, watch } = form
  const qtyPerUnit = watch(`units.${index}.qtyPerUnit`)
  const maxSell = maxSellableFromPool({ qtyPerUnit }, poolBase)

  return (
    <div className="space-y-4">
      <ProductUnitFormSubsection title="Định danh loại hàng">
        <div className="grid gap-4 sm:grid-cols-2">
          <FormFieldCol label="Mã loại (type)" required>
            <Input {...register(`units.${index}.type`)} placeholder="hop" />
          </FormFieldCol>
          <FormFieldCol label="Nhãn hiển thị" required>
            <Input {...register(`units.${index}.label`)} placeholder="Hộp" />
          </FormFieldCol>
          <FormFieldCol label="SKU biến thể" className="sm:col-span-2">
            <Input
              {...register(`units.${index}.sku`)}
              placeholder="DEMO-001-HOP"
            />
          </FormFieldCol>
        </div>
      </ProductUnitFormSubsection>

      <ProductUnitStockBlock
        unitLabel={unitLabel}
        qtyPerUnit={qtyPerUnit}
        poolBaseStock={poolBase}
        maxSellableFromPool={maxSell}
        qtyPerUnitInput={
          <Input
            type="number"
            min={1}
            placeholder="6"
            className="h-8 tabular-nums"
            {...register(`units.${index}.qtyPerUnit`)}
          />
        }
      />

      <ProductUnitFormSubsection title="Giá bán">
        <FormFieldCol
          label="Giá bán lẻ (VND)"
          required
          description="Giá mặc định khi chưa áp dụng KM, sỉ hay bậc giá."
          className="max-w-sm"
        >
          <Input
            type="number"
            min={0}
            className="tabular-nums"
            {...register(`units.${index}.retailPrice`)}
          />
        </FormFieldCol>
      </ProductUnitFormSubsection>

      <FormFieldCol label="Ảnh sản phẩm">
        <Controller
          control={control}
          name={`units.${index}.imageUrls`}
          render={({ field: imageField }) => (
            <ImageUrlListField
              value={imageField.value ?? ""}
              onChange={imageField.onChange}
              onPickFromStorage={onPickImages}
            />
          )}
        />
      </FormFieldCol>

      <UnitPromoSections
        form={form}
        index={index}
        unitLabel={unitLabel}
        onPickGiftImage={onPickGiftImage}
        onPickFromCatalog={onPickFromCatalog}
      />
    </div>
  )
}

export function ProductUnitVariantsField({
  form,
  currentProductId,
}: {
  form: UseFormReturn<ProductFormValues>
  currentProductId?: string | null
}) {
  const { control, register, watch, setValue } = form
  const { fields, append, remove } = useFieldArray({
    control,
    name: "units",
  })
  const [picker, setPicker] = useState<{
    index: number
    field: "imageUrls" | "giftImage"
    giftIndex?: number
  } | null>(null)
  const [catalogPicker, setCatalogPicker] = useState<{
    unitIndex: number
    giftIndex: number
  } | null>(null)

  const allUnits = useWatch({ control, name: "units" }) ?? []
  const baseStock = useWatch({ control, name: "baseStock" })
  const poolBase = computeFormUnitStockPool(baseStock)
  const useCollapsible = fields.length > 1

  const resolveProductUpload = useCallback(
    () =>
      buildProductImageUploadContext({
        productName: form.getValues("name"),
        productSku: form.getValues("sku"),
      }),
    [form]
  )

  return (
    <div className="space-y-4">
      <ProductUnitStockPoolBanner baseStock={baseStock} units={allUnits} />

      {fields.map((field, index) => {
        const isDefault = watch(`units.${index}.isDefault`)
        const unitLabel = watch(`units.${index}.label`) ?? ""
        const retailPrice = watch(`units.${index}.retailPrice`)
        const qtyPerUnit = watch(`units.${index}.qtyPerUnit`)

        const headerActions = (
          <div className="flex shrink-0 gap-2">
            {!isDefault ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  fields.forEach((_, i) => {
                    setValue(`units.${i}.isDefault`, i === index)
                  })
                }}
              >
                Đặt mặc định
              </Button>
            ) : null}
            {fields.length > 1 ? (
              <Button
                type="button"
                variant="ghost"
                size="icon-sm"
                onClick={() => remove(index)}
                aria-label="Xóa loại hàng"
              >
                <Trash2 className="size-4" />
              </Button>
            ) : null}
          </div>
        )

        const body = (
          <UnitVariantCardBody
            form={form}
            index={index}
            unitLabel={unitLabel}
            poolBase={poolBase}
            onPickImages={() => setPicker({ index, field: "imageUrls" })}
            onPickGiftImage={(giftIndex) =>
              setPicker({ index, field: "giftImage", giftIndex })
            }
            onPickFromCatalog={(giftIndex) =>
              setCatalogPicker({ unitIndex: index, giftIndex })
            }
          />
        )

        if (!useCollapsible) {
          return (
            <div
              key={field.id}
              className="rounded-lg border bg-card p-4 shadow-sm"
            >
              <div className="mb-3 flex items-center justify-between gap-2">
                <ProductUnitVariantCardHeader
                  index={index}
                  label={unitLabel}
                  isDefault={isDefault}
                  retailPrice={retailPrice}
                  qtyPerUnit={qtyPerUnit}
                  poolBase={poolBase}
                  expanded
                />
                {headerActions}
              </div>
              {body}
            </div>
          )
        }

        return (
          <Collapsible
            key={field.id}
            defaultOpen={isDefault}
            className="group overflow-hidden rounded-lg border bg-card shadow-sm"
          >
            <div className="flex items-center gap-2 p-4 pb-3">
              <CollapsibleTrigger
                className={cn(
                  "flex min-w-0 flex-1 items-center gap-2 rounded-md text-left transition-colors",
                  "hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                )}
              >
                <ProductUnitVariantCardHeader
                  index={index}
                  label={unitLabel}
                  isDefault={isDefault}
                  retailPrice={retailPrice}
                  qtyPerUnit={qtyPerUnit}
                  poolBase={poolBase}
                  expanded={false}
                />
                <ChevronDown
                  className="size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-data-open:rotate-180"
                  aria-hidden
                />
              </CollapsibleTrigger>
              {headerActions}
            </div>
            <CollapsibleContent className="border-t px-4 pb-4 pt-3">
              {body}
            </CollapsibleContent>
          </Collapsible>
        )
      })}

      <Button
        type="button"
        variant="outline"
        className="w-full sm:w-auto"
        onClick={() =>
          append({
            ...EMPTY_UNIT_ROW,
            isDefault: false,
            type: `loai-${fields.length + 1}`,
          })
        }
      >
        <Plus className="size-4" /> Thêm loại hàng
      </Button>

      <StorageImagePickerDialog
        open={picker !== null}
        multiSelect={picker?.field === "imageUrls"}
        resolveProductUpload={resolveProductUpload}
        onOpenChange={(open) => {
          if (!open) setPicker(null)
        }}
        onSelect={(urls) => {
          if (!picker || !urls[0]) return
          const idx = picker.index
          if (picker.field === "imageUrls") {
            const current = parseImageUrls(
              watch(`units.${idx}.imageUrls`) ?? ""
            )
            setValue(
              `units.${idx}.imageUrls`,
              formatImageUrls([...current, ...urls])
            )
          } else if (picker.giftIndex !== undefined) {
            setValue(`units.${idx}.gifts.${picker.giftIndex}.image`, urls[0]!)
          }
          setPicker(null)
        }}
      />

      <ProductCatalogPickerDialog
        open={catalogPicker !== null}
        onOpenChange={(open) => {
          if (!open) setCatalogPicker(null)
        }}
        excludeProductId={currentProductId}
        onSelect={(product) => {
          if (!catalogPicker) return
          const { unitIndex, giftIndex } = catalogPicker
          const base = `units.${unitIndex}.gifts.${giftIndex}` as const
          setValue(`${base}.productId`, product.id)
          setValue(`${base}.name`, product.name)
          setValue(`${base}.sku`, product.sku)
          const image = firstProductImage(product)
          if (image) setValue(`${base}.image`, image)
          const label = form.getValues(`${base}.label`)?.trim()
          if (!label) {
            setValue(`${base}.label`, `Tặng ${product.name}`)
          }
          setCatalogPicker(null)
        }}
      />
    </div>
  )
}

src/app/products/_component/products-tab.content:
"use client"

import type {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import type { ProductRow } from "./types"

export function ProductsTable({
  data,
  columns,
  isLoading,
  total,
  page,
  pageSize,
  onPageChange,
  onPageSizeChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  onClearFilters,
  onBulkDelete,
  onRowPrefetch,
}: {
  data: ProductRow[]
  columns: ColumnDef<ProductRow>[]
  isLoading: boolean
  total: number
  page: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  columnFilters?: ColumnFiltersState
  onColumnFiltersChange?: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  onClearFilters: () => void
  onBulkDelete?: (rows: ProductRow[]) => Promise<void>
  onRowPrefetch?: (row: ProductRow) => void
}) {
  return (
    <AdminDataTable<ProductRow>
      tableScope="products"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel='Chưa có sản phẩm — bấm "Thêm sản phẩm".'
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      onClearFilters={onClearFilters}
      pagination={{
        mode: "server",
        page,
        pageSize,
        total,
        onPageChange,
        onPageSizeChange,
      }}
      onRowPointerEnter={
        onRowPrefetch ? (row) => onRowPrefetch(row.original) : undefined
      }
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={
        onBulkDelete
          ? [
              {
                id: "bulk-product-delete",
                label: "Xóa tạm đã chọn",
                variant: "destructive" as const,
                confirm: {
                  title: "Đưa các sản phẩm đã chọn vào thùng rác?",
                  description: (rows: ProductRow[]) =>
                    `Bạn đã chọn ${rows.length} sản phẩm.`,
                  confirmLabel: "Xóa tạm",
                  destructive: true,
                },
                onAction: onBulkDelete,
              },
            ]
          : undefined
      }
    />
  )
