"use client"

import { useParams } from "next/navigation"
import { useAdminCrudNavigation } from "@/lib/admin-navigation"
import {
  Loader2,
  ArrowLeft,
  Globe,
  Hash,
  FileText,
  Calendar,
  Clock,
  Trash2,
} from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  FieldSet,
  FieldSetContent,
  FieldSectionDivider,
  FieldSectionField,
  FieldSectionLegend,
} from "@ui/components/field"
import {
  AdminDetailLayout,
  AdminDetailMain,
  AdminDetailPageHeader,
  AdminDetailSidebar,
  AdminPageGuard,
  AdminPageSection,
} from "@ui/components/admin"
import { useAuth } from "@/providers/auth-provider"
import { PERMISSION_CODES, canUserAccess } from "@workspace/api-client"
import { api } from "@/lib/api"
import { useSeoMetaDetailQuery } from "../_component"

function formatDateTime(value: string | null | undefined): string {
  if (!value) return "—"
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString("vi-VN")
}

function SeoMetaDetailInner() {
  const crudNav = useAdminCrudNavigation("/seo-metas")
  const params = useParams()
  const id = params.id as string
  const { user } = useAuth()
  const canUpdate = user
    ? canUserAccess(user, PERMISSION_CODES.SEO_METAS_UPDATE)
    : false

  const { data: detail, isLoading, isError } = useSeoMetaDetailQuery(api, id)

  if (isLoading) {
    return (
      <div className="flex min-h-[200px] items-center justify-center">
        <Loader2 className="size-6 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (isError || !detail) {
    return (
      <AdminPageSection>
        <p className="text-destructive">Không tìm thấy SEO metadata.</p>
        <Button type="button" variant="outline" onClick={() => crudNav.list()}>
          <ArrowLeft className="size-4" /> Quay lại
        </Button>
      </AdminPageSection>
    )
  }

  return (
    <AdminPageSection>
      <AdminDetailPageHeader
        title={`SEO: ${detail.page}`}
        subtitle={`Chi tiết SEO metadata cho trang "${detail.page}"`}
        variant="module"
        onBack={() => crudNav.list()}
        onEdit={canUpdate ? () => crudNav.edit(String(id)) : undefined}
      />

      <AdminDetailLayout>
        <AdminDetailMain>
          <FieldSet variant="section">
            <FieldSectionLegend
              icon={FileText}
              title="Thông tin cơ bản"
              description="Metadata SEO cho trang."
            />
            <FieldSetContent variant="section" className="space-y-4 pt-0">
              <FieldSectionField
                label="Đường dẫn"
                icon={Hash}
                valueClassName="font-mono font-medium"
              >
                {detail.page}
              </FieldSectionField>
              <FieldSectionField label="Trạng thái" icon={FileText}>
                {detail.status === 1 ? (
                  <Badge variant="default" className="text-[10px]">
                    Hoạt động
                  </Badge>
                ) : (
                  <Badge variant="outline" className="text-[10px]">
                    Tắt
                  </Badge>
                )}
              </FieldSectionField>
              <FieldSectionDivider />
              <FieldSectionField label="Title SEO" icon={FileText}>
                {detail.title ?? "—"}
              </FieldSectionField>
              <FieldSectionField label="Mô tả" icon={FileText}>
                {detail.description ?? "—"}
              </FieldSectionField>
              <FieldSectionField label="Từ khóa" icon={Hash}>
                {detail.keywords ?? "—"}
              </FieldSectionField>
            </FieldSetContent>
          </FieldSet>

          <FieldSet variant="section">
            <FieldSectionLegend icon={Calendar} title="Thời gian" />
            <FieldSetContent variant="section" className="space-y-3 pt-0">
              <div className="grid gap-4 sm:grid-cols-3">
                <FieldSectionField
                  label="Tạo lúc"
                  icon={Calendar}
                  valueClassName="font-medium"
                >
                  {formatDateTime(detail.createdAt)}
                </FieldSectionField>
                <FieldSectionField
                  label="Cập nhật lúc"
                  icon={Clock}
                  valueClassName="font-medium"
                >
                  {formatDateTime(detail.updatedAt)}
                </FieldSectionField>
                <FieldSectionField
                  label="Xóa lúc"
                  icon={Trash2}
                  valueClassName="font-medium"
                >
                  {formatDateTime(detail.deletedAt)}
                </FieldSectionField>
              </div>
            </FieldSetContent>
          </FieldSet>
        </AdminDetailMain>

        <AdminDetailSidebar>
          <div className="sticky top-2 flex flex-col gap-4">
            <FieldSet variant="section">
              <FieldSectionLegend icon={Globe} title="Open Graph" />
              <FieldSetContent variant="section" className="space-y-3 pt-0">
                <FieldSectionField label="OG Title" icon={Globe}>
                  {detail.ogTitle ?? "—"}
                </FieldSectionField>
                <FieldSectionField label="OG Mô tả" icon={Globe}>
                  {detail.ogDescription ?? "—"}
                </FieldSectionField>
                <FieldSectionField label="OG Ảnh" icon={Globe}>
                  {detail.ogImage ? (
                    <img
                      src={detail.ogImage}
                      alt="OG Image"
                      className="mt-1 max-h-32 rounded border object-cover"
                    />
                  ) : (
                    "—"
                  )}
                </FieldSectionField>
              </FieldSetContent>
            </FieldSet>
          </div>
        </AdminDetailSidebar>
      </AdminDetailLayout>
    </AdminPageSection>
  )
}

export default function SeoMetaDetailPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <SeoMetaDetailInner />
    </AdminPageGuard>
  )
}

src/app/seo-metas/_component/columns.tsx.content:
"use client"

import {
  defineAdminCrudActionsColumn,
  defineAdminTrashActionsColumn,
} from "@ui/components/admin"

import type { ColumnDef } from "@tanstack/react-table"
import { UsageStatusFromValue } from "@ui/components/usage-status-badge"
import type { AdminCrudRowHandlers } from "@/lib/admin-row-action-handlers"
import {
  type AdminTableView,
  buildAdminTableColumns,
} from "@/lib/admin-table-columns"
import type { SeoMetaRow } from "./types"

export function getSeoMetaColumns({
  view = "list",
  openDetail = () => {},
  openEdit = () => {},
  rowActions,
  canWrite,
  canDelete,
  canRestore,
  canHardDelete,
}: {
  view?: AdminTableView
  openDetail?: (row: SeoMetaRow) => void
  openEdit?: (row: SeoMetaRow) => void
  rowActions: AdminCrudRowHandlers<SeoMetaRow>
  canWrite: boolean
  canDelete?: boolean
  canRestore?: boolean
  canHardDelete?: boolean
}): ColumnDef<SeoMetaRow>[] {
  const dataColumns: ColumnDef<SeoMetaRow>[] = [
    {
      accessorKey: "page",
      header: "Đường dẫn",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ row, getValue }) => (
        <button
          type="button"
          className="text-left font-medium text-foreground transition-colors hover:text-primary"
          onClick={() => openDetail(row.original)}
        >
          {String(getValue())}
        </button>
      ),
    },
    {
      accessorKey: "title",
      header: "Title SEO",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => {
        const val = getValue() as string | null
        return (
          <span className="block max-w-[200px] truncate text-sm text-muted-foreground">
            {val ?? "—"}
          </span>
        )
      },
    },
    {
      accessorKey: "keywords",
      header: "Từ khóa",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => {
        const val = getValue() as string | null
        return (
          <span className="block max-w-[150px] truncate text-xs text-muted-foreground">
            {val ?? "—"}
          </span>
        )
      },
    },
    {
      accessorKey: "status",
      header: "Trạng thái",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.getValue(columnId)) === String(filterValue)
      },
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "1", label: "Hoạt động" },
          { value: "0", label: "Tắt" },
        ],
      },
      cell: ({ getValue }) => (
        <UsageStatusFromValue
          value={getValue() as number}
          labels={{ active: "Hoạt động", locked: "Tắt" }}
          className="text-[10px]"
        />
      ),
    },
  ]

  return buildAdminTableColumns({
    view,
    dataColumns,
    listActionsColumn: defineAdminCrudActionsColumn<SeoMetaRow>({
      canWrite,
      canDelete,
      canHardDelete,
      onView: openDetail,
      onEdit: openEdit,
      onSoftDelete: rowActions.onSoftDelete,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
    trashActionsColumn: defineAdminTrashActionsColumn<SeoMetaRow>({
      canWrite,
      canRestore,
      canHardDelete,
      onRestore: rowActions.onRestore,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
  })
}

src/app/seo-metas/_component/_query/inde.content:
import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@/lib/admin-detail-query"
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@/lib/fetch-all-admin-list"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client"
import type { SeoMetaDetail, SeoMetaRow } from "../types"

export const seoMetaDetailQueryKey = (id: string) =>
  ["seo-metas", "detail", id] as const

export function prefetchSeoMetaDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(queryClient, seoMetaDetailQueryKey(id), () =>
    api.seoMetas.get<SeoMetaDetail>(id)
  )
}

export function useSeoMetaDetailQuery(api: StoreSyncSdk, id: string) {
  return useQuery({
    ...adminDetailQueryOptions(
      seoMetaDetailQueryKey(id),
      async () => api.seoMetas.get<SeoMetaDetail>(id),
      id
    ),
  })
}

export function useSeoMetasListQuery(
  apiParam: StoreSyncSdk,
  enabled: boolean,
  filters?: Record<string, string>
): UseQueryResult<SeoMetaRow[]> {
  return useQuery({
    queryKey: ["seo-metas", "list", filters],
    queryFn: async (): Promise<SeoMetaRow[]> => {
      const limit = ADMIN_LIST_EXPORT_FETCH_LIMIT
      const items: SeoMetaRow[] = []
      let page = 1
      let total = Number.POSITIVE_INFINITY

      while (items.length < total) {
        const result = await apiParam.seoMetas.list<SeoMetaRow>({
          page,
          limit,
          status: "active",
          filters,
        })
        items.push(...result.items)
        total = result.total
        if (result.items.length === 0) break
        page += 1
      }

      return items
    },
    enabled,
  })
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk
  trashPage: number
  trashPageSize: number
  debouncedTrashQ: string
  enabled: boolean
}

export function useSeoMetasTrashQuery({
  api: apiParam,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  enabled,
  filters,
}: UseTrashQueryProps & { filters?: Record<string, string> }): UseQueryResult<
  PagedResult<SeoMetaRow>
> {
  return useQuery({
    queryKey: [
      "seo-metas",
      "trash",
      trashPage,
      trashPageSize,
      debouncedTrashQ,
      filters,
    ],
    enabled,
    queryFn: async (): Promise<PagedResult<SeoMetaRow>> => {
      return apiParam.seoMetas.list<SeoMetaRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        ...filters,
      })
    },
  })
}

