import { useCallback } from "react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { z } from "zod"

export const staffFormSchema = z.object({
  email: z.string().email("Email không hợp lệ"),
  fullName: z.string().min(1, "Họ tên không được để trống"),
  password: z
    .string()
    .min(6, "Mật khẩu tối thiểu 6 ký tự")
    .optional()
    .or(z.literal("")),
  isActive: z.boolean(),
  roleCodes: z.array(z.string()).min(1, "Vui lòng chọn ít nhất một vai trò"),
  avatar: z.string().optional(),
  phone: z.string().optional().or(z.literal("")),
  address: z.string().optional().or(z.literal("")),
  citizenId: z.string().optional().or(z.literal("")),
})

export type StaffFormValues = z.infer<typeof staffFormSchema>

interface UseStaffFormOptions {
  editingId?: string | null
}

export function useStaffForm(options: UseStaffFormOptions = {}) {
  const { editingId } = options

  const form = useForm<StaffFormValues>({
    resolver: zodResolver(staffFormSchema),
    defaultValues: {
      email: "",
      fullName: "",
      password: "",
      isActive: true,
      roleCodes: [],
      avatar: "",
      phone: "",
      address: "",
      citizenId: "",
    },
    mode: "onChange",
  })

  const resetForm = useCallback(() => {
    form.reset({
      email: "",
      fullName: "",
      password: "",
      isActive: true,
      roleCodes: [],
      phone: "",
      address: "",
      citizenId: "",
    })
  }, [form])

  const populateForm = useCallback(
    (user: {
      email: string
      fullName: string
      isActive: boolean
      roles: { code: string }[]
      avatar?: string | null
      phone?: string | null
      address?: string | null
      citizenId?: string | null
    }) => {
      form.reset({
        email: user.email,
        fullName: user.fullName,
        password: "",
        isActive: user.isActive,
        roleCodes: user.roles.map((r) => r.code),
        avatar: user.avatar ?? "",
        phone: user.phone ?? "",
        address: user.address ?? "",
        citizenId: user.citizenId ?? "",
      })
    },
    [form]
  )

  const toggleRole = useCallback(
    (code: string, checked: boolean) => {
      const currentRoles = form.getValues("roleCodes")
      if (checked) {
        form.setValue("roleCodes", [...new Set([...currentRoles, code])], {
          shouldDirty: true,
        })
      } else {
        form.setValue(
          "roleCodes",
          currentRoles.filter((c) => c !== code),
          { shouldDirty: true }
        )
      }
    },
    [form]
  )

  const getPayload = useCallback((): {
    email: string
    fullName: string
    password: string
    isActive: boolean
    roleCodes: string[]
    avatar?: string | null
    phone?: string | null
    address?: string | null
    citizenId?: string | null
  } => {
    const values = form.getValues()
    const payload: {
      email: string
      fullName: string
      password: string
      isActive: boolean
      roleCodes: string[]
      avatar?: string | null
      phone?: string | null
      address?: string | null
      citizenId?: string | null
    } = {
      fullName: values.fullName.trim(),
      isActive: values.isActive,
      email: "",
      password: "",
      roleCodes: values.roleCodes,
      avatar: values.avatar?.trim() || null,
      phone: values.phone?.trim() || null,
      address: values.address?.trim() || null,
      citizenId: values.citizenId?.trim() || null,
    }

    if (!editingId) {
      payload.email = values.email.trim()
      payload.password = values.password?.trim() || ""
    } else {
      payload.email = values.email.trim()
      const pw = values.password?.trim()
      payload.password = pw || ""
    }

    return payload
  }, [form, editingId])

  return {
    form,
    resetForm,
    populateForm,
    toggleRole,
    getPayload,
  }
}

src/app/staff/_component/_query/use-staf.content:
import { useQueryClient } from "@tanstack/react-query"
import type {
  CreateUserInput,
  StoreSyncSdk,
  UpdateUserInput,
} from "@workspace/api-client"
import { ApiError } from "@/lib/api"
import { queryKeys } from "@/hooks/queries"
import { syncAdminSessionIfCurrentUser } from "@/lib/auth-session"

import { useAdminMutation } from "@/hooks/use-admin-mutation"
type CreateStaffInput = Pick<
  CreateUserInput,
  | "email"
  | "fullName"
  | "password"
  | "isActive"
  | "roleCodes"
  | "phone"
  | "address"
  | "citizenId"
>

type UpdateStaffInput = Pick<
  UpdateUserInput,
  | "fullName"
  | "password"
  | "isActive"
  | "roleCodes"
  | "avatar"
  | "phone"
  | "address"
  | "citizenId"
>

export interface UseStaffMutationsProps {
  api: StoreSyncSdk
}

export function useStaffMutations({ api: apiClient }: UseStaffMutationsProps) {
  const queryClient = useQueryClient()

  const createMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã tạo tài khoản",
      error: (error) =>
        error instanceof ApiError ? error.message : "Không tạo được user",
    },
    mutationFn: async (input: CreateStaffInput) => {
      return apiClient.users.create({
        email: input.email,
        fullName: input.fullName,
        password: input.password,
        isActive: input.isActive,
        roleCodes: input.roleCodes,
        phone: input.phone,
        address: input.address,
        citizenId: input.citizenId,
      })
    },
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
      ])
    },
  })

  const updateMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã cập nhật nhân sự",
      error: (error) =>
        error instanceof ApiError ? error.message : "Không lưu được",
    },
    mutationFn: async ({
      id,
      input,
    }: {
      id: string
      input: UpdateStaffInput
    }) => {
      return apiClient.users.update(id, {
        fullName: input.fullName,
        isActive: input.isActive,
        password: input.password,
        roleCodes: input.roleCodes,
        avatar: input.avatar,
        phone: input.phone,
        address: input.address,
        citizenId: input.citizenId,
      })
    },
    onSuccess: async (data, variables) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
        queryClient.invalidateQueries({
          queryKey: queryKeys.staffProfile(variables.id),
        }),
      ])
      await syncAdminSessionIfCurrentUser(variables.id, data)
    },
  })

  const deleteMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã đưa tài khoản vào thùng rác",
      error: (error) =>
        error instanceof ApiError ? error.message : "Không xoá được",
    },
    mutationFn: async (id: string) => apiClient.users.remove(id),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
        queryClient.invalidateQueries({ queryKey: queryKeys.usersTrashed() }),
      ])
    },
  })

  const restoreMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã khôi phục tài khoản",
      error: (error) =>
        error instanceof ApiError ? error.message : "Không khôi phục được",
    },
    mutationFn: async (id: string) => apiClient.users.restore(id),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
        queryClient.invalidateQueries({ queryKey: queryKeys.usersTrashed() }),
      ])
    },
  })

  const purgeMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã xóa vĩnh viễn tài khoản",
      error: (error) =>
        error instanceof ApiError ? error.message : "Không xóa vĩnh viễn được",
    },
    mutationFn: async (id: string) => apiClient.users.purgeTrashed(id),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
        queryClient.invalidateQueries({ queryKey: queryKeys.usersTrashed() }),
      ])
    },
  })

  const bulkMutation = useAdminMutation({
    mutationFn: async (input: {
      action: "delete" | "restore" | "hard-delete"
      ids: string[]
    }) => apiClient.users.bulk(input),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: queryKeys.staffUserList() }),
        queryClient.invalidateQueries({ queryKey: queryKeys.usersTrashed() }),
      ])
    },
  })

  return {
    createMutation,
    updateMutation,
    deleteMutation,
    restoreMutation,
    purgeMutation,
    bulkMutation,
  }
}

src/app/staff/_component/_table/staff-tr.content:
import type {
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import { getStaffColumns } from "../columns"
import type { StaffRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"
import { api } from "@/lib/api"

interface StaffTrashTableProps {
  data: StaffRow[]
  isLoading: boolean
  total: number
  page: number
  pageSize: number
  appliedPage?: number
  appliedPageSize?: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  onRestore: (user: StaffRow) => void
  onPurge: (user: StaffRow) => void
  busy: boolean
  canRestore: boolean
  canHardDelete: boolean
  onBulkRestore: (ids: string[]) => void
  onBulkPurge: (ids: string[]) => void
  onClearFilters: () => void
  listParams: {
    q?: string
    filters?: Record<string, string>
  }
}

export function StaffTrashTable(props: StaffTrashTableProps) {
  const {
    data,
    isLoading,
    total,
    page,
    pageSize,
    appliedPage,
    appliedPageSize,
    onPageChange,
    onPageSizeChange,
    columnFilters,
    onColumnFiltersChange,
    globalFilter,
    onGlobalFilterChange,
    selectedRowIds,
    onSelectedRowIdsChange,
    onRestore,
    onPurge,
    busy,
    canRestore: canRestorePerm,
    canHardDelete: canHardDeletePerm,
    onBulkRestore,
    onBulkPurge,
    onClearFilters,
    listParams,
  } = props

  const canWriteTrash = canRestorePerm || canHardDeletePerm

  const columns = getStaffColumns({
    view: "trash",
    onView: () => {},
    onEdit: () => {},
    onDelete: () => {},
    onRestore,
    onPurge,
    onToggleActive: () => {},
    busy,
    isProtected: () => false,
    canWrite: canWriteTrash,
    canRestore: canRestorePerm,
    canHardDelete: canHardDeletePerm,
  })

  return (
    <AdminDataTable<StaffRow>
      tableScope="staff-trash"
      data={data}
      getRowId={(row) => String(row.id)}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Thùng rác trống hoặc không khớp tìm kiếm."
      defaultExpandedAll={false}
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo email, họ tên, SĐT (API)…"
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        ...(canRestorePerm
          ? [
              {
                id: "bulk-staff-restore" as const,
                label: "Khôi phục đã chọn",
                variant: "outline" as const,
                onAction: async (rows: StaffRow[]) => {
                  const ids = rows.map((u) => String(u.id))
                  if (!ids.length) return
                  await onBulkRestore(ids)
                },
              },
            ]
          : []),
        ...(canHardDeletePerm
          ? [
              {
                id: "bulk-staff-purge" as const,
                label: "Xóa vĩnh viễn đã chọn",
                variant: "destructive" as const,
                onAction: async (rows: StaffRow[]) => {
                  const ids = rows.map((u) => String(u.id))
                  if (!ids.length) return
                  await onBulkPurge(ids)
                },
              },
            ]
          : []),
      ]}
      onClearFilters={onClearFilters}
      xlsxExport={buildAdminTableXlsxExport("staff-trash", {
        pageCount: data.length,
        total,
      })}
      exportFetchPage={async ({ page: exportPage, limit }) => {
        const res = await api.users.listTrashed({
          page: exportPage,
          limit,
          q: listParams.q,
          filters: listParams.filters,
        })
        return { items: res.items, total: res.total }
      }}
      pagination={{
        page,
        pageSize,
        total,
        appliedPage,
        appliedPageSize,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Thùng rác trống hoặc không khớp tìm kiếm.",
        itemLabel: "tài khoản",
      }}
    />
  )
}

