                <Controller
                  name="name"
                  control={control}
                  render={({ field, fieldState }) => (
                    <FormFieldCol
                      label={
                        <div className="flex items-center gap-2">
                          <Tag className="size-4 text-muted-foreground" />
                          Tên hiển thị
                        </div>
                      }
                      required
                    >
                      <Input
                        placeholder="VD: công nghệ, giải trí, giáo dục"
                        {...field}
                        className={cn(fieldState.error && "border-destructive")}
                      />
                      {fieldState.error && (
                        <FieldError>{fieldState.error.message}</FieldError>
                      )}
                      <div className="mt-1 flex items-center justify-between text-xs text-muted-foreground">
                        <span>Tối đa 50 ký tự, nên ngắn gọn.</span>
                        <Badge
                          variant={nameLength > 50 ? "destructive" : "outline"}
                          className="ml-auto"
                        >
                          {nameLength} ký tự
                        </Badge>
                      </div>
                    </FormFieldCol>
                  )}
                />

                <Controller
                  name="slug"
                  control={control}
                  render={({ field, fieldState }) => (
                    <FormFieldCol
                      label={
                        <div className="flex items-center gap-2">
                          <Globe className="size-4 text-muted-foreground" />
                          Slug / đường dẫn
                        </div>
                      }
                    >
                      <Input
                        placeholder="cong-nghe"
                        {...field}
                        className={cn(fieldState.error && "border-destructive")}
                      />
                      {fieldState.error && (
                        <FieldError>{fieldState.error.message}</FieldError>
                      )}
                      <div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground">
                        <Globe className="size-3 shrink-0" />
                        <span className="font-mono break-all">
                          /the/{field.value || "ten-the"}
                        </span>
                      </div>
                    </FormFieldCol>
                  )}
                />
              </div>

              <Controller
                name="icon"
                control={control}
                render={({ field }) => (
                  <FormFieldCol
                    label={
                      <div className="flex items-center gap-2">
                        <ImageIcon className="size-4 text-muted-foreground" />
                        Biểu tượng
                      </div>
                    }
                  >
                    <IconPickerField
                      value={field.value}
                      onChange={(v) => field.onChange((v as string) ?? null)}
                      placeholder="Chọn biểu tượng"
                    />
                  </FormFieldCol>
                )}
              />
            </FieldSetContent>
          </FieldSet>
        </AdminFormMain>
      </AdminFormLayout>
    </>
  )
}

