"use client"

import { useCallback, useTransition } from "react"
import { useRouter } from "next/navigation"
import { useAdminRouteProgress } from "@ui/lib/admin-route-progress"

export type AdminCrudNavigationOptions = {
  /** Prefetch React Query detail (gọi từ list / hover dòng). */
  prefetchDetail?: (id: string) => void | Promise<void>
}

/**
 * Điều hướng CRUD admin: prefetch route + `startTransition` để chuyển trang mượt.
 * Dùng trên list page thay cho `router.push` trực tiếp.
 */
export function useAdminCrudNavigation(
  basePath: `/${string}`,
  options?: AdminCrudNavigationOptions
) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const { startIfNavigating } = useAdminRouteProgress()

  const prefetchHref = useCallback(
    (href: string) => {
      try {
        router.prefetch(href)
      } catch {
        // prefetch best-effort
      }
    },
    [router]
  )

  const navigate = useCallback(
    (href: string, beforePush?: () => void | Promise<void>) => {
      prefetchHref(href)
      startIfNavigating(href)
      void Promise.resolve(beforePush?.()).finally(() => {
        startTransition(() => {
          router.push(href)
        })
      })
    },
    [prefetchHref, router, startIfNavigating]
  )

  const prefetchRecord = useCallback(
    (id: string) => {
      const normalizedId = String(id)
      prefetchHref(`${basePath}/${normalizedId}`)
      prefetchHref(`${basePath}/${normalizedId}/edit`)
      void options?.prefetchDetail?.(normalizedId)
    },
    [basePath, options, prefetchHref]
  )

  return {
    isPending,
    list: () => navigate(basePath),
    new: () => navigate(`${basePath}/new`),
    view: (id: string) =>
      navigate(`${basePath}/${id}`, () => options?.prefetchDetail?.(id)),
    edit: (id: string) =>
      navigate(`${basePath}/${id}/edit`, () => options?.prefetchDetail?.(id)),
    prefetch: prefetchRecord,
    push: navigate,
    prefetchHref,
  }
}

src/lib/admin-row-action-handlers.ts.content:
import type { UseMutationResult } from "@tanstack/react-query"
import { useCallback, useMemo } from "react"

type RowWithId = { id: string }

export type AdminCrudRowHandlers<T extends RowWithId> = {
  getRecordLabel: (row: T) => string
  onSoftDelete?: (row: T) => void | Promise<void>
  onRestore?: (row: T) => void | Promise<void>
  onPurge?: (row: T) => void | Promise<void>
}

export function useAdminCrudRowHandlers<T extends RowWithId>(options: {
  getRecordLabel: (row: T) => string
  entityLabel?: string
  deleteMutation?: UseMutationResult<unknown, Error, string>
  restoreMutation?: UseMutationResult<unknown, Error, string>
  purgeMutation?: UseMutationResult<unknown, Error, string>
}): AdminCrudRowHandlers<T> {
  const { getRecordLabel, deleteMutation, restoreMutation, purgeMutation } =
    options

  const onSoftDelete = useCallback(
    async (row: T) => {
      if (!deleteMutation) return
      await deleteMutation.mutateAsync(row.id)
    },
    [deleteMutation]
  )

  const onRestore = useCallback(
    async (row: T) => {
      if (!restoreMutation) return
      await restoreMutation.mutateAsync(row.id)
    },
    [restoreMutation]
  )

  const onPurge = useCallback(
    async (row: T) => {
      if (!purgeMutation) return
      await purgeMutation.mutateAsync(row.id)
    },
    [purgeMutation]
  )

  return useMemo(
    () => ({
      getRecordLabel,
      onSoftDelete: deleteMutation ? onSoftDelete : undefined,
      onRestore: restoreMutation ? onRestore : undefined,
      onPurge: purgeMutation ? onPurge : undefined,
    }),
    [
      deleteMutation,
      getRecordLabel,
      onPurge,
      onRestore,
      onSoftDelete,
      purgeMutation,
      restoreMutation,
    ]
  )
}

